__bundleFactories["CustomHub.State"] = function()
-- BEGIN SOURCE: src/ReplicatedStorage/CustomHub/State.lua
local State = {}
State.__index = State

function State.new(defaults)
    local self = setmetatable({}, State)
    self._listeners = {}
    self._defaults = defaults
    self._maxStatusCharacters = defaults.StatusMaxCharacters or 88
    self._values = {
        selectedTab = defaults.SelectedTab,
        compact = defaults.Compact,
        uiSize = defaults.UiSize,
        status = "Hub UI ready; Main Farm is available but disabled.",
        statusKind = "info",
        statusValues = {},
        notification = nil,
        featureEnabled = {},
    }
    self._notificationSerial = 0
    self._activeNotificationKey = nil
    self._notificationLastShownAt = {}
    return self
end

function State:GetSnapshot()
    local featureEnabled = {}
    for key, value in pairs(self._values.featureEnabled) do
        featureEnabled[key] = value
    end
    local statusValues = {}
    for key, value in pairs(self._values.statusValues) do
        statusValues[key] = value
    end
    return {
        selectedTab = self._values.selectedTab,
        compact = self._values.compact,
        uiSize = self._values.uiSize,
        status = self._values.status,
        statusKind = self._values.statusKind,
        statusValues = statusValues,
        notification = self._values.notification,
        featureEnabled = featureEnabled,
    }
end

function State:_Notify()
    local snapshot = self:GetSnapshot()
    for index = #self._listeners, 1, -1 do
        local listener = self._listeners[index]
        local ok = pcall(listener, snapshot)
        if not ok then
            table.remove(self._listeners, index)
        end
    end
end

function State:Subscribe(listener)
    table.insert(self._listeners, listener)
    local connected = true
    return {
        Disconnect = function()
            if not connected then
                return
            end
            connected = false
            for index = #self._listeners, 1, -1 do
                if self._listeners[index] == listener then
                    table.remove(self._listeners, index)
                    break
                end
            end
        end,
    }
end

function State:_QueueErrorNotification(playerMessage, kind, options)
    local notificationKind = kind == "warning" and "warning" or "error"
    local title = notificationKind == "warning" and "Action needed" or "Action unavailable"
    local body = tostring(
        playerMessage
            or "That action couldn't be completed. Check the hub status line for details."
    )
    options = type(options) == "table" and options or {}
    local key = tostring(options.Key or (title .. "\0" .. body))
    local now = os.clock()

    local current = self._values.notification
    local cooldown = tonumber(options.Cooldown) or 30
    local lastShownAt = self._notificationLastShownAt[key]
    if current and current.Key == key
        and (current.Persistent == true or not lastShownAt or now - lastShownAt < cooldown)
    then
        current.Message = body
        current.Title = title
        current.Kind = notificationKind
        current.Persistent = current.Persistent or options.Persistent == true
        self._activeNotificationKey = key
        return
    end

    if lastShownAt and now - lastShownAt < cooldown then
        self._activeNotificationKey = key
        return
    end

    self._notificationLastShownAt[key] = now
    self._activeNotificationKey = key
    self._notificationSerial += 1
    self._values.notification = {
        Id = self._notificationSerial,
        Key = key,
        Title = title,
        Message = body,
        Kind = notificationKind,
        Persistent = options.Persistent == true,
    }
end

function State:ClearNotification(key)
    local notification = self._values.notification
    if key ~= nil and (not notification or notification.Key ~= key) then
        return false
    end
    self._activeNotificationKey = nil
    self._values.notification = nil
    if key ~= nil then
        self._notificationLastShownAt[key] = nil
    end
    self:_Notify()
    return true
end

function State:SetStatus(message, kind, playerMessage, notificationOptions)
    local text = tostring(message)
    if #text > self._maxStatusCharacters then
        text = text:sub(1, self._maxStatusCharacters - 3) .. "..."
    end
    self._values.status = text
    self._values.statusKind = kind or "info"
    if kind == "error" or (kind == "warning" and playerMessage ~= nil) then
        self:_QueueErrorNotification(playerMessage, kind, notificationOptions)
    else
        self._activeNotificationKey = nil
    end
    self:_Notify()
end

function State:SetSelectedTab(tabName)
    self._values.selectedTab = tabName
    self:_Notify()
end

function State:SetCompact(enabled)
    self._values.compact = enabled == true
    self:_Notify()
end

function State:SetUiSize(size)
    self._values.uiSize = size
    self:_Notify()
end

function State:SetFeatureEnabled(actionId, enabled)
    self._values.featureEnabled[actionId] = enabled == true
    self:_Notify()
end

function State:SetStatusValues(values)
    local nextValues = {}
    if type(values) == "table" then
        for key, value in pairs(values) do
            nextValues[key] = tostring(value)
        end
    end
    self._values.statusValues = nextValues
    self:_Notify()
end

function State:ResetPresentation()
    self._values.selectedTab = self._defaults.SelectedTab
    self._values.compact = self._defaults.Compact
    self._values.uiSize = self._defaults.UiSize
    self._values.status = "UI presentation settings reset; feature states are unchanged."
    self._values.statusKind = "success"
    self:_Notify()
end

return State
-- END SOURCE: src/ReplicatedStorage/CustomHub/State.lua
end

__bundleFactories["CustomHub.Compatibility"] = function()
-- BEGIN SOURCE: src/ReplicatedStorage/CustomHub/Compatibility.lua
local Players = game:GetService("Players")
local UserInputService = game:GetService("UserInputService")
local Workspace = game:GetService("Workspace")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local CollectionService = game:GetService("CollectionService")
local HttpService = game:GetService("HttpService")

local Compatibility = {}
Compatibility.__index = Compatibility

local TITLE_MENU_PROBE_TIMEOUT = 5
local TITLE_MENU_PROBE_INTERVAL = 0.05
local TITLE_MENU_CLOSE_GUARD_DURATION = 1.5
local TITLE_LOCKED_CONFIRMATION_DELAY = 0.25
local TITLE_STATE_CACHE_TTL = 5
local TITLE_STATE_UNKNOWN_CACHE_TTL = 1

function Compatibility.new()
    return setmetatable({
        Player = Players.LocalPlayer,
        Players = Players,
        ReplicatedStorage = ReplicatedStorage,
        Workspace = Workspace,
        RunService = RunService,
        CollectionService = CollectionService,
        HttpService = HttpService,
        NpcManager = nil,
        NpcCatalogNames = nil,
    }, Compatibility)
end

function Compatibility:GetLocalSettingsStorage()
    local apiOk, api = pcall(function()
        return {
            Read = readfile,
            Write = writefile,
            Exists = isfile,
            IsFolder = isfolder,
            MakeFolder = makefolder,
        }
    end)
    if not apiOk or type(api) ~= "table"
        or type(api.Read) ~= "function"
        or type(api.Write) ~= "function"
    then
        return nil, "Local file APIs are unavailable"
    end

    return {
        Exists = type(api.Exists) == "function" and function(path)
            return api.Exists(path)
        end or nil,
        Read = function(path)
            return api.Read(path)
        end,
        Write = function(path, content)
            local folder = "CustomHub"
            if type(api.IsFolder) == "function" then
                local folderOk, exists = pcall(api.IsFolder, folder)
                if folderOk and not exists and type(api.MakeFolder) == "function" then
                    local makeOk, makeError = pcall(api.MakeFolder, folder)
                    if not makeOk then
                        local retryOk, existsAfter = pcall(api.IsFolder, folder)
                        if not retryOk or not existsAfter then
                            return false, tostring(makeError)
                        end
                    end
                end
            elseif type(api.MakeFolder) == "function" then
                pcall(api.MakeFolder, folder)
            end

            local writeOk, result = pcall(api.Write, path, content)
            if not writeOk then
                return false, tostring(result)
            end
            return true
        end,
    }
end

function Compatibility:GetNpcManager()
    if self.NpcManager then
        return self.NpcManager
    end
    local managerModule = self.ReplicatedStorage
        and self.ReplicatedStorage:FindFirstChild("NPCManager")
    if not managerModule or not managerModule:IsA("ModuleScript") then
        return nil, "NPCManager module is unavailable"
    end
    local ok, manager = pcall(require, managerModule)
    if not ok or type(manager) ~= "table"
        or type(manager.getNPCsByName) ~= "function"
    then
        return nil, "NPCManager lookup is unavailable: " .. tostring(manager)
    end
    self.NpcManager = manager
    return manager
end

function Compatibility:GetNpcCatalogNames()
    if self.NpcCatalogNames then
        return table.clone(self.NpcCatalogNames)
    end
    local managerModule = self.ReplicatedStorage
        and self.ReplicatedStorage:FindFirstChild("NPCManager")
    local npcListModule = managerModule
        and managerModule:FindFirstChild("NPCList")
    if not npcListModule or not npcListModule:IsA("ModuleScript") then
        return nil, "NPCManager.NPCList module is unavailable"
    end
    local ok, npcList = pcall(require, npcListModule)
    local list = ok and type(npcList) == "table" and npcList.List
    if type(list) ~= "table" then
        return nil, "NPCManager NPC list is unavailable: " .. tostring(npcList)
    end
    local names = {}
    for name in pairs(list) do
        if type(name) == "string" and name ~= "" then
            table.insert(names, name)
        end
    end
    table.sort(names)
    self.NpcCatalogNames = names
    return table.clone(names)
end

function Compatibility:GetNpcModelsByName(name)
    if type(name) ~= "string" or name == "" then
        return {}, "NPC name is invalid"
    end
    local manager, managerError = self:GetNpcManager()
    if not manager then
        return {}, managerError
    end
    local ok, entries = pcall(manager.getNPCsByName, name)
    if not ok or type(entries) ~= "table" then
        return {}, ok and "NPCManager returned no entry list" or tostring(entries)
    end
    local models = {}
    local seen = {}
    for _, entry in ipairs(entries) do
        local stateOk, model = pcall(function()
            local modelState = entry and entry._modelState
            return modelState and modelState._instance
        end)
        if stateOk and model and typeof(model) == "Instance"
            and model:IsA("Model") and not seen[model]
        then
            seen[model] = true
            table.insert(models, model)
        end
    end
    return models
end

function Compatibility:GetPlayerGui()
    if not self.Player then
        return nil, "LocalPlayer is unavailable"
    end
    local playerGui = self.Player:FindFirstChildOfClass("PlayerGui")
    if not playerGui then
        return nil, "PlayerGui is unavailable"
    end
    return playerGui
end

function Compatibility:SelectTeamIfPrompted(teamName, timeoutSeconds)
    if teamName ~= "Marines" and teamName ~= "Pirates" then
        return false, "Unsupported team"
    end
    local player = self.Player
    if not player then
        return false, "LocalPlayer is unavailable"
    end

    local playerGui = player:FindFirstChildOfClass("PlayerGui")
    if not playerGui then
        return false, "PlayerGui is unavailable"
    end

    local timeout = math.clamp(tonumber(timeoutSeconds) or 6, 0, 8)
    local deadline = os.clock() + timeout
    local attempted = false
    while os.clock() <= deadline do
        local main = playerGui:FindFirstChild("Main (minimal)")
            or playerGui:FindFirstChild("Main")
        local chooseTeam = main and main:FindFirstChild("ChooseTeam")
        if chooseTeam and chooseTeam.Visible then
            local container = chooseTeam:FindFirstChild("Container")
            local teamCard = container and container:FindFirstChild(teamName)
            local frame = teamCard and teamCard:FindFirstChild("Frame")
            local button = frame and frame:FindFirstChildWhichIsA("GuiButton", true)
            if not button and teamCard then
                button = teamCard:FindFirstChildWhichIsA("GuiButton", true)
            end

            if button then
                attempted = true
                local inputOk = pcall(function()
                    local guiService = game:GetService("GuiService")
                    local inputManager = game:GetService("VirtualInputManager")
                    guiService.SelectedObject = button
                    inputManager:SendKeyEvent(
                        true,
                        Enum.KeyCode.Return,
                        false,
                        button
                    )
                    inputManager:SendKeyEvent(
                        false,
                        Enum.KeyCode.Return,
                        false,
                        button
                    )
                    guiService.SelectedObject = nil
                end)
                if not inputOk then
                    pcall(function()
                        button:Activate()
                    end)
                else
                    task.wait(0.1)
                    if chooseTeam.Visible then
                        pcall(function()
                            button:Activate()
                        end)
                    end
                end
                task.wait(0.35)
            else
                task.wait(0.1)
            end
        elseif player.Team then
            return true, "A team is already selected"
        else
            task.wait(0.1)
        end

        if not (chooseTeam and chooseTeam.Visible) then
            if player.Team then
                return true, "Team selected"
            elseif attempted then
                return true, "Team selection accepted"
            end
        end
    end

    if player.Team then
        return true, "A team is already selected"
    end
    return false, attempted
        and ("Could not confirm the " .. teamName .. " team selection")
        or "Team selection screen was not found"
end

function Compatibility:_GetHttpRequestFunction()
    local ok, requestFunction = pcall(function()
        if type(request) == "function" then
            return request
        end
        if type(http_request) == "function" then
            return http_request
        end
        if type(syn) == "table" and type(syn.request) == "function" then
            return syn.request
        end
        if type(http) == "table" and type(http.request) == "function" then
            return http.request
        end
        if type(fluxus) == "table" and type(fluxus.request) == "function" then
            return fluxus.request
        end
        return nil
    end)
    if not ok then
        return nil
    end
    return type(requestFunction) == "function" and requestFunction or nil
end

function Compatibility:GetPublicServers(cursor)
    local placeId = tonumber(game.PlaceId)
    if not placeId or placeId <= 0 then
        return nil, "Current place id is unavailable"
    end

    local url = "https://games.roblox.com/v1/games/"
        .. tostring(math.floor(placeId))
        .. "/servers/Public?sortOrder=Asc&limit=25"
    if type(cursor) == "string" and cursor ~= "" then
        local encodeOk, encodedCursor = pcall(function()
            return self.HttpService:UrlEncode(cursor)
        end)
        if not encodeOk then
            return nil, "Could not encode the server-list cursor"
        end
        url = url .. "&cursor=" .. encodedCursor
    end

    local responseBody
    local requestFunction = self:_GetHttpRequestFunction()
    if requestFunction then
        local requestOk, response = pcall(requestFunction, {
            Url = url,
            Method = "GET",
        })
        if requestOk and type(response) == "table" then
            local statusCode = tonumber(response.StatusCode or response.Status)
            if statusCode and (statusCode < 200 or statusCode >= 300) then
                return nil, "Roblox server list returned HTTP "
                    .. tostring(statusCode)
                    .. " for place "
                    .. tostring(math.floor(placeId))
            end
            responseBody = response.Body
        elseif not requestOk then
            return nil, tostring(response)
        end
    end

    if type(responseBody) ~= "string" or responseBody == "" then
        local httpOk, body = pcall(function()
            return game:HttpGet(url)
        end)
        if not httpOk or type(body) ~= "string" then
            return nil, "Public server list access is unavailable"
        end
        responseBody = body
    end

    local decodeOk, data = pcall(function()
        return self.HttpService:JSONDecode(responseBody)
    end)
    if not decodeOk or type(data) ~= "table" or type(data.data) ~= "table" then
        return nil, "Roblox returned an invalid public server list"
    end
    return {
        Servers = data.data,
        NextCursor = type(data.nextPageCursor) == "string"
            and data.nextPageCursor
            or nil,
    }
end

function Compatibility:TeleportToPublicServer(jobId)
    if type(jobId) ~= "string" or jobId == "" then
        return false, "Server id is unavailable"
    end
    if jobId == tostring(game.JobId) then
        return false, "This is already the current server"
    end

    local teleportService
    local serviceOk, service = pcall(function()
        return game:GetService("TeleportService")
    end)
    if serviceOk then
        teleportService = service
    end
    if not teleportService or not self.Player then
        return false, "Server joining is unavailable"
    end

    local teleportOk, teleportError = pcall(function()
        teleportService:TeleportToPlaceInstance(
            game.PlaceId,
            jobId,
            self.Player
        )
    end)
    if not teleportOk then
        return false, tostring(teleportError)
    end
    return true
end

