function Compatibility:TouchPart(touchingPart, targetPart, isCurrent)
    if not touchingPart or not touchingPart.Parent or not targetPart or not targetPart.Parent then
        return false, "Gateway touch parts are unavailable"
    end
    if type(isCurrent) == "function" and not isCurrent() then
        return false, "Gateway touch was cancelled"
    end
    local ok, touchFunction = pcall(function()
        return firetouchinterest
    end)
    if not ok or type(touchFunction) ~= "function" then
        return false, "This client cannot activate the map gateway touch trigger"
    end

    local began, beginError = pcall(touchFunction, touchingPart, targetPart, 0)
    if not began then
        return false, "Gateway touch could not begin: " .. tostring(beginError)
    end
    task.wait(0.15)
    if type(isCurrent) == "function" and not isCurrent() then
        pcall(touchFunction, touchingPart, targetPart, 1)
        return false, "Gateway touch was cancelled"
    end
    local ended, endError = pcall(touchFunction, touchingPart, targetPart, 1)
    if not ended then
        return false, "Gateway touch could not finish: " .. tostring(endError)
    end
    return true
end

function Compatibility:HasOwnedInventoryItem(itemName)
    local now = os.clock()
    self.OwnedInventoryCache = self.OwnedInventoryCache or {}
    if now - (self.OwnedInventoryCacheAt or 0) < 1
        and self.OwnedInventoryCache[itemName] ~= nil
    then
        return self.OwnedInventoryCache[itemName]
    end

    local itemServiceModule = self.ReplicatedStorage:FindFirstChild("ItemReplicationService")
    local itemConfigModule = self.ReplicatedStorage:FindFirstChild("ItemConfig")
    if not itemServiceModule or not itemConfigModule then
        return false, "Inventory lookup modules are unavailable"
    end

    local serviceOk, itemService = pcall(require, itemServiceModule)
    local configOk, itemConfig = pcall(require, itemConfigModule)
    if not serviceOk or type(itemService) ~= "table"
        or not configOk or type(itemConfig) ~= "table"
    then
        return false, "Inventory lookup modules could not be loaded"
    end

    local keys = itemService.KEYS
    local quantityKey = type(keys) == "table" and keys.QUANTITY
    if quantityKey == nil or type(itemService.GetItems) ~= "function"
        or type(itemConfig.match) ~= "function"
    then
        return false, "Inventory lookup APIs are unavailable"
    end

    local scanOk, found = pcall(function()
        for _, item in itemService:GetItems(quantityKey) do
            if item and item.Value and item.Value > 0 then
                local matchOk, itemDefinition = pcall(function()
                    return itemConfig.match(item.ItemId):unwrap()
                end)
                if matchOk and itemDefinition and itemDefinition.Display then
                    local display = itemDefinition.Display
                    local storageKey = itemDefinition.Index
                        and itemDefinition.Index.StorageKey
                    local resolvedName = display.Category == "Blox Fruit"
                            and (storageKey or display.Name)
                        or (display.Name or storageKey)
                    if resolvedName == itemName then
                        return true
                    end
                end
            end
        end
        return false
    end)
    if not scanOk then
        return false, "Inventory scan failed: " .. tostring(found)
    end

    self.OwnedInventoryCache[itemName] = found == true
    self.OwnedInventoryCacheAt = now
    return found == true
end

function Compatibility:GetInventoryMaterialCount(materialName)
    if type(materialName) ~= "string" or materialName == "" then
        return nil, "Material name is invalid"
    end

    local now = os.clock()
    self.InventoryMaterialCountCache = self.InventoryMaterialCountCache or {}
    local cached = self.InventoryMaterialCountCache[materialName]
    if cached and now < cached.ExpiresAt then
        return cached.Count
    end

    local itemServiceModule = self.ReplicatedStorage:FindFirstChild("ItemReplicationService")
    local itemConfigModule = self.ReplicatedStorage:FindFirstChild("ItemConfig")
    if not itemServiceModule or not itemConfigModule then
        return nil, "Inventory lookup modules are unavailable"
    end

    local serviceOk, itemService = pcall(require, itemServiceModule)
    local configOk, itemConfig = pcall(require, itemConfigModule)
    local keys = serviceOk and type(itemService) == "table" and itemService.KEYS
    local quantityKey = type(keys) == "table" and keys.QUANTITY
    if not serviceOk or type(itemService) ~= "table"
        or not configOk or type(itemConfig) ~= "table"
        or quantityKey == nil
        or type(itemService.GetItems) ~= "function"
        or type(itemConfig.match) ~= "function"
    then
        return nil, "Inventory lookup APIs are unavailable"
    end

    local scanOk, count = pcall(function()
        local total = 0
        for _, item in itemService:GetItems(quantityKey) do
            if item and tonumber(item.Value) and tonumber(item.Value) > 0 then
                local matchOk, itemDefinition = pcall(function()
                    return itemConfig.match(item.ItemId):unwrap()
                end)
                if matchOk and itemDefinition then
                    local display = itemDefinition.Display
                    local storageKey = itemDefinition.Index
                        and itemDefinition.Index.StorageKey
                    local debugLabel = itemDefinition.Index
                        and itemDefinition.Index.DebugLabel
                    local resolvedName = display
                        and (display.Name or storageKey)
                        or storageKey
                    if type(debugLabel) == "string" then
                        resolvedName = debugLabel:match("^(.-)%s*%[") or resolvedName
                    end
                    if resolvedName == materialName then
                        total += tonumber(item.Value)
                    end
                end
            end
        end
        return total
    end)
    if not scanOk then
        return nil, "Inventory material scan failed: " .. tostring(count)
    end

    self.InventoryMaterialCountCache[materialName] = {
        Count = count,
        ExpiresAt = now + 1,
    }
    return count
end

function Compatibility:GetUnlockedTitleCheck(titleName)
    if type(titleName) ~= "string" or titleName == "" then
        return nil, "title name is unavailable", false
    end

    local now = os.clock()
    self.TitleOwnershipCache = self.TitleOwnershipCache or {}
    local cache = self.TitleOwnershipCache[titleName]
    if cache and now < cache.ExpiresAt then
        return cache.Value, cache.Reason, false
    end

    local pending = self.TitleOwnershipPending
        and self.TitleOwnershipPending[titleName] == true
    return nil, pending and "title check pending" or "title state is unknown", pending
end

function Compatibility:BeginUnlockedTitleCheck(titleName)
    local state, reason, pending = self:GetUnlockedTitleCheck(titleName)
    if type(state) == "boolean" or pending then
        return state, reason, pending
    end

    local now = os.clock()
    local cache = self.TitleOwnershipCache and self.TitleOwnershipCache[titleName]
    if cache and now < cache.ExpiresAt then
        return nil, reason, false
    end

    self.TitleOwnershipPending = self.TitleOwnershipPending or {}
    self.TitleOwnershipPending[titleName] = true
    task.spawn(function()
        pcall(self.HasUnlockedTitle, self, titleName)
        if self.TitleOwnershipPending then
            self.TitleOwnershipPending[titleName] = nil
        end
    end)
    return nil, "title check pending", true
end

function Compatibility:HasUnlockedTitle(titleName)
    if type(titleName) ~= "string" or titleName == "" then
        return nil, "title name is unavailable"
    end

    local now = os.clock()
    self.TitleOwnershipCache = self.TitleOwnershipCache or {}
    local targetLower = string.lower(titleName)
    local cache = self.TitleOwnershipCache[titleName]
    if cache and now < cache.ExpiresAt then
        return cache.Value, cache.Reason
    end

    local function getMenuParts()
        local playerGui = self.Player and self.Player:FindFirstChildOfClass("PlayerGui")
        local titlesMenu = playerGui and playerGui:FindFirstChild("TitlesMenu")
        local root = titlesMenu and titlesMenu:FindFirstChild("ROOT")
        local frame = root and root:FindFirstChild("Frame")
        local content = frame and frame:FindFirstChild("content")
        local list = content and content:FindFirstChild("scrollingFrame")
        return titlesMenu, frame, list
    end

    local function readTitleState()
        local titlesMenu, frame, list = getMenuParts()
        if not titlesMenu then
            return nil, "TitlesMenu is unavailable", titlesMenu, frame, list
        end
        if not list then
            return nil, "title list is not populated", titlesMenu, frame, list
        end

        local row = list:FindFirstChild(titleName)
        if not row then
            for _, child in ipairs(list:GetChildren()) do
                if string.lower(tostring(child.Name)) == targetLower then
                    row = child
                    break
                end
            end
        end
        if not row or not row:IsA("GuiObject") then
            return nil, "title row is not present in the loaded list", titlesMenu, frame, list
        end
        if not row.Visible then
            return nil, "title row is hidden in the loaded list", titlesMenu, frame, list
        end

        local titleLabel = row:FindFirstChild("titleName", true)
        local titleText = titleLabel and titleLabel:IsA("TextLabel")
                and tostring(titleLabel.Text)
            or ""
        local titleTextLower = string.lower(titleText)
        local lockedImage = row:FindFirstChild("lockedImage", true)
        local isLocked = string.find(titleTextLower, "(locked)", 1, true) ~= nil
        if lockedImage and lockedImage:IsA("GuiObject") and lockedImage.Visible then
            isLocked = true
        end
        if isLocked then
            return false, "title row is marked locked", titlesMenu, frame, list
        end
        if titleTextLower ~= ""
            and string.find(titleTextLower, targetLower, 1, true)
        then
            return true, "unlocked title row is visible", titlesMenu, frame, list
        end
        return nil, "title row has no readable unlocked/locked marker", titlesMenu, frame, list
    end

    local function safeReadTitleState()
        local readOk, state, reason, titlesMenu, frame, list = pcall(readTitleState)
        if not readOk then
            return nil, "title UI scan failed: " .. tostring(state), nil, nil, nil
        end
        return state, reason, titlesMenu, frame, list
    end

    local state, reason, titlesMenu, frame = safeReadTitleState()
    local menuIsVisible = false
    pcall(function()
        menuIsVisible = titlesMenu.Enabled == true and frame and frame.Visible == true
    end)
    if state == true or (state == false and menuIsVisible) then
        self.TitleOwnershipCache[titleName] = {
            Value = state,
            Reason = reason,
            At = now,
            ExpiresAt = state == true
                    and math.huge
                or state == false
                    and now + TITLE_STATE_CACHE_TTL
                or now + TITLE_STATE_UNKNOWN_CACHE_TTL,
        }
        return state, reason
    end

    local openedForProbe = false
    local originalEnabled
    if titlesMenu and titlesMenu:IsA("LayerCollector") then
        originalEnabled = titlesMenu.Enabled
    end

    local frameConnections = {}
    local probeConnections = {}
    local watchedFrames = {}
    local probeFinished = false
    local lastCloseActivationAt = -math.huge
    local function activateMenuClose(activeFrame)
        if os.clock() - lastCloseActivationAt < 0.2 then
            return
        end
        lastCloseActivationAt = os.clock()
        pcall(function()
            if not activeFrame then
                local _, currentFrame = getMenuParts()
                activeFrame = currentFrame
            end
            local titleBar = activeFrame and activeFrame:FindFirstChild("title", true)
            local closeButton = titleBar and titleBar:FindFirstChild("close", true)
            if closeButton and closeButton:IsA("GuiButton") then
                closeButton:Activate()
            end
        end)
    end
    local function suppressProbeMenu(activateClose)
        pcall(function()
            local _, activeFrame = getMenuParts()
            if activeFrame and activeFrame:IsA("GuiObject") then
                if activateClose and activeFrame.Visible then
                    activateMenuClose(activeFrame)
                end
                activeFrame.Visible = false
            end
        end)
    end
    local function watchFrame(activeFrame)
        if not activeFrame or not activeFrame:IsA("GuiObject") or watchedFrames[activeFrame] then
            return
        end
        watchedFrames[activeFrame] = true
        local connectOk, connection = pcall(function()
            return activeFrame:GetPropertyChangedSignal("Visible"):Connect(function()
                pcall(function()
                    if openedForProbe and activeFrame.Visible then
                        if probeFinished then
                            activateMenuClose(activeFrame)
                        end
                        activeFrame.Visible = false
                    end
                end)
            end)
        end)
        if connectOk and connection then
            table.insert(frameConnections, connection)
        end
        if openedForProbe and activeFrame.Visible then
            activeFrame.Visible = false
        end
    end

    if not menuIsVisible then
        local openEvent = titlesMenu and titlesMenu:FindFirstChild("Open")
        if not openEvent or not openEvent:IsA("BindableEvent") then
            reason = "TitlesMenu.Open is unavailable"
            state = nil
        else
            if frame then
                watchFrame(frame)
            end
            local descendantConnection
            if titlesMenu then
                descendantConnection = titlesMenu.DescendantAdded:Connect(function(instance)
                    if instance.Name == "Frame"
                        and instance.Parent
                        and instance.Parent.Name == "ROOT"
                    then
                        pcall(watchFrame, instance)
                    end
                end)
            end
            if descendantConnection then
                table.insert(probeConnections, descendantConnection)
            end
            openedForProbe = true
            local fired, fireError = pcall(function()
                openEvent:Fire()
            end)
            if fired then
                task.wait(0.05)
                suppressProbeMenu()
            else
                openedForProbe = false
                state = nil
                reason = "TitlesMenu.Open failed: " .. tostring(fireError)
            end
        end
    end

    local function waitForTitleState()
        local deadline = os.clock() + TITLE_MENU_PROBE_TIMEOUT
        local lockedSeenAt
        repeat
            state, reason = safeReadTitleState()
            if state == true or (state == false and menuIsVisible) then
                break
            end
            if state == false then
                lockedSeenAt = lockedSeenAt or os.clock()
                if os.clock() - lockedSeenAt >= TITLE_LOCKED_CONFIRMATION_DELAY then
                    break
                end
            else
                lockedSeenAt = nil
            end
            if not openedForProbe and not menuIsVisible then
                break
            end
            if openedForProbe then
                suppressProbeMenu()
            end
            if os.clock() >= deadline then
                reason = "title list did not populate within "
                    .. tostring(TITLE_MENU_PROBE_TIMEOUT)
                    .. " seconds"
                break
            end
            task.wait(TITLE_MENU_PROBE_INTERVAL)
        until false
        return state, reason
    end
    local probeOk, probeState, probeReason = pcall(waitForTitleState)
    if probeOk then
        state, reason = probeState, probeReason
    else
        state = nil
        reason = "title menu probe failed: " .. tostring(probeState)
    end

    for _, connection in ipairs(probeConnections) do
        pcall(function()
            if connection and connection.Connected then
                connection:Disconnect()
            end
        end)
    end
    if openedForProbe then
        probeFinished = true
        activateMenuClose(frame)
        suppressProbeMenu()
        pcall(function()
            if titlesMenu and originalEnabled ~= nil then
                titlesMenu.Enabled = originalEnabled
            end
        end)
        task.spawn(function()
            local deadline = os.clock() + TITLE_MENU_CLOSE_GUARD_DURATION
            repeat
                suppressProbeMenu(true)
                if titlesMenu and originalEnabled ~= nil then
                    pcall(function()
                        if titlesMenu.Enabled ~= originalEnabled then
                            titlesMenu.Enabled = originalEnabled
                        end
                    end)
                end
                task.wait(0.05)
            until os.clock() >= deadline
            openedForProbe = false
            for _, connection in ipairs(frameConnections) do
                pcall(function()
                    if connection and connection.Connected then
                        connection:Disconnect()
                    end
                end)
            end
        end)
    else
        for _, connection in ipairs(frameConnections) do
            pcall(function()
                if connection and connection.Connected then
                    connection:Disconnect()
                end
            end)
        end
    end

    now = os.clock()
    self.TitleOwnershipCache[titleName] = {
        Value = state,
        Reason = reason,
        At = now,
        ExpiresAt = state == true
                and math.huge
            or state == false
                and now + TITLE_STATE_CACHE_TTL
            or now + TITLE_STATE_UNKNOWN_CACHE_TTL,
    }
    return state, reason
end

function Compatibility:BuildTitleAccessDiagnosticReport()
    local targetTitle = "Liberator of the Sky"
    local targetLower = string.lower(targetTitle)
    local lines = {
        "===== [TitleAccessDiagnostic] REPORT BEGIN =====",
        "Target title: " .. targetTitle,
        "Purpose: locate title ownership data; no remotes are invoked",
    }
    local matchCount = 0
    local scanLimit = 3000
    local matchLimit = 30

    local function addMatch(sourceName, instance, valueDescription)
        if matchCount >= matchLimit then
            return
        end
        local path = "unknown path"
        pcall(function()
            path = instance:GetFullName()
        end)
        local className = "unknown class"
        pcall(function()
            className = instance.ClassName
        end)
        local visibility = ""
        pcall(function()
            if instance:IsA("GuiObject") then
                visibility = "; Visible=" .. tostring(instance.Visible)
            elseif instance:IsA("LayerCollector") then
                visibility = "; Enabled=" .. tostring(instance.Enabled)
            end
        end)
        lines[#lines + 1] = sourceName
            .. ": "
            .. path
            .. " ("
            .. className
            .. ")"
            .. (valueDescription and ("; value=" .. tostring(valueDescription)) or "")
            .. visibility
        matchCount += 1
    end

    local function scanRoot(sourceName, root, maxDescendants, includeTitleNames, includeAllText)
        if not root then
            lines[#lines + 1] = sourceName .. ": unavailable"
            return
        end
        local descendantsOk, descendants = pcall(root.GetDescendants, root)
        if not descendantsOk or type(descendants) ~= "table" then
            lines[#lines + 1] = sourceName .. ": descendants could not be read"
            return
        end
        local scanned = math.min(#descendants, tonumber(maxDescendants) or scanLimit)
        local relevantCount = 0
        for index = 1, scanned do
            local instance = descendants[index]
            local name = ""
            pcall(function()
                name = instance.Name
            end)
            local nameLower = string.lower(tostring(name))
            local valueText
            local isTextControl = false
            local valueOk = pcall(function()
                if instance:IsA("ValueBase") then
                    valueText = tostring(instance.Value)
                elseif instance:IsA("TextLabel")
                    or instance:IsA("TextButton")
                    or instance:IsA("TextBox")
                then
                    valueText = tostring(instance.Text)
                    isTextControl = true
                end
            end)
            if not valueOk then
                valueText = nil
            end
            local valueLower = type(valueText) == "string" and string.lower(valueText) or ""
            local exactTitleMatch = string.find(valueLower, targetLower, 1, true) ~= nil
            local exactTitleName = string.find(nameLower, targetLower, 1, true) ~= nil
            local titleNamed = includeTitleNames == true
                and string.find(nameLower, "title", 1, true) ~= nil
            local ownershipMarker = includeAllText == true
                and (
                    string.find(nameLower, "unlock", 1, true)
                    or string.find(nameLower, "owned", 1, true)
                    or string.find(nameLower, "claim", 1, true)
                    or string.find(nameLower, "equipped", 1, true)
                    or string.find(nameLower, "locked", 1, true)
                    or string.find(nameLower, "available", 1, true)
                )
            if titleNamed or exactTitleMatch or exactTitleName
                or (includeAllText == true and isTextControl)
                or ownershipMarker
            then
                relevantCount += 1
                addMatch(sourceName, instance, valueText)
            end

            local attributesOk, attributes = pcall(instance.GetAttributes, instance)
            if attributesOk and type(attributes) == "table" then
                for attributeName, attributeValue in pairs(attributes) do
                    local attributeNameLower = string.lower(tostring(attributeName))
                    local attributeText = tostring(attributeValue)
                    local attributeValueLower = string.lower(attributeText)
                    if (includeTitleNames == true
                            and string.find(attributeNameLower, "title", 1, true))
                        or string.find(attributeValueLower, targetLower, 1, true)
                    then
                        relevantCount += 1
                        addMatch(
                            sourceName .. " attribute " .. tostring(attributeName),
                            instance,
                            attributeText
                        )
                    end
                end
            end
        end
        lines[#lines + 1] = sourceName
            .. " scan: "
            .. tostring(scanned)
            .. " descendants; "
            .. tostring(relevantCount)
            .. " title-related matches"
            .. (#descendants > scanned and "; scan limit reached" or "")
    end

    local player = self.Player
    local playerData = player and player:FindFirstChild("Data")
    scanRoot("Player.Data", playerData, scanLimit, true, false)

    local playerGui = player and player:FindFirstChildOfClass("PlayerGui")
    local titlesMenu = playerGui and playerGui:FindFirstChild("TitlesMenu")
    local mainTitles = playerGui
        and playerGui:FindFirstChild("Main")
        and playerGui.Main:FindFirstChild("Titles")
    scanRoot("PlayerGui exact-title scan", playerGui, 10000, false, false)
    scanRoot("TitlesMenu", titlesMenu, 10000, true, true)
    local function describeGuiRoot(instance)
        if not instance then
            return "missing"
        end
        local state = instance.ClassName .. "; present"
        pcall(function()
            if instance:IsA("LayerCollector") then
                state ..= "; Enabled=" .. tostring(instance.Enabled)
            elseif instance:IsA("GuiObject") then
                state ..= "; Visible=" .. tostring(instance.Visible)
            end
        end)
        return state
    end
    lines[#lines + 1] = "TitlesMenu root: "
        .. describeGuiRoot(titlesMenu)
    lines[#lines + 1] = "Main.Titles root: "
        .. describeGuiRoot(mainTitles)

    local replicatedStorage = self.ReplicatedStorage
    local remoteCandidates = {}
    local moduleCandidates = {}
    if replicatedStorage then
        local descendantsOk, descendants = pcall(replicatedStorage.GetDescendants, replicatedStorage)
        if descendantsOk and type(descendants) == "table" then
            for index = 1, math.min(#descendants, scanLimit) do
                local instance = descendants[index]
                local nameLower = string.lower(tostring(instance.Name))
                if instance:IsA("RemoteEvent") or instance:IsA("RemoteFunction") then
                    if string.find(nameLower, "title", 1, true) then
                        remoteCandidates[#remoteCandidates + 1] = instance:GetFullName()
                    elseif instance.Name == "CommF_" then
                        remoteCandidates[#remoteCandidates + 1] =
                            instance:GetFullName() .. " (generic remote; not invoked)"
                    end
                elseif instance:IsA("ModuleScript")
                    and string.find(nameLower, "title", 1, true)
                then
                    moduleCandidates[#moduleCandidates + 1] = instance:GetFullName()
                end
            end
        end
    end
    lines[#lines + 1] = "Title-related remotes: "
        .. (#remoteCandidates > 0 and table.concat(remoteCandidates, ", ") or "none found")
    lines[#lines + 1] = "Title-related modules: "
        .. (#moduleCandidates > 0 and table.concat(moduleCandidates, ", ") or "none found")
    local remotesFolder = replicatedStorage and replicatedStorage:FindFirstChild("Remotes")
    local commF = remotesFolder and remotesFolder:FindFirstChild("CommF_")
    lines[#lines + 1] = "Generic CommF_ remote: "
        .. (commF and (commF.ClassName .. "; present; not invoked") or "missing")

    local npcFolder = self.Workspace and self.Workspace:FindFirstChild("NPCs")
    local titleNpcs = {}
    for _, npc in ipairs(npcFolder and npcFolder:GetChildren() or {}) do
        if string.find(string.lower(npc.Name), "title", 1, true) then
            titleNpcs[#titleNpcs + 1] = npc.Name
        end
    end
    lines[#lines + 1] = "Title-related Workspace.NPCs: "
        .. (#titleNpcs > 0 and table.concat(titleNpcs, ", ") or "none found")
    if matchCount == 0 then
        lines[#lines + 1] = "Exact title text not found in the scanned Player.Data or PlayerGui entries."
    end
    lines[#lines + 1] = "Note: name/value matches are evidence only; they do not prove unlocked status."
    lines[#lines + 1] = "===== [TitleAccessDiagnostic] REPORT END ====="
    return table.concat(lines, "\n")
end

function Compatibility:GetCombatDependencies()
    local modules = self.ReplicatedStorage:FindFirstChild("Modules")
    local netModule = modules and modules:FindFirstChild("Net")
    local mouseModule = self.ReplicatedStorage:FindFirstChild("Mouse")
    local combatUtilModule = modules and modules:FindFirstChild("CombatUtil")
    if not netModule or not mouseModule or not combatUtilModule then
        return nil, "BNN melee dependency modules are unavailable"
    end

    local registerAttack = netModule:WaitForChild("RE/RegisterAttack", 10)
    if not registerAttack then
        return nil, "Modules.Net.RE/RegisterAttack is unavailable"
    end

    local mouseOk, mouse = pcall(require, mouseModule)
    local combatOk, combatUtil = pcall(require, combatUtilModule)
    local netOk, net = pcall(require, netModule)
    if not mouseOk or not combatOk or not netOk then
        return nil, "BNN melee dependency modules failed to load"
    end

    local hitOk, registerHit = pcall(function()
        return net:RemoteEvent("RegisterHit", true)
    end)
    if not hitOk or not registerHit then
        return nil, "Modules.Net RegisterHit dependency is unavailable"
    end

    return {
        Mouse = mouse,
        CombatUtil = combatUtil,
        Net = net,
        RegisterAttack = registerAttack,
        RegisterHit = registerHit,
    }
end

function Compatibility:IsThirdSea()
    local mapName = self.Workspace:GetAttribute("MAP")
    return mapName == "Sea3"
        or game.PlaceId == 100117331123089
        or game.PlaceId == 7449423635
end

function Compatibility:IsFirstSea()
    local mapName = self.Workspace:GetAttribute("MAP")
    return mapName == "Sea1"
        or game.PlaceId == 2753915549
        or game.PlaceId == 85211729168715
end

function Compatibility:IsSecondSea()
    local mapName = self.Workspace:GetAttribute("MAP")
    return mapName == "Sea2"
        or game.PlaceId == 4442272183
        or game.PlaceId == 79091703265657
end

return Compatibility
-- END SOURCE: src/ReplicatedStorage/CustomHub/Compatibility.lua
end

__bundleFactories["CustomHub.SettingsPersistence"] = function()
-- BEGIN SOURCE: src/ReplicatedStorage/CustomHub/SettingsPersistence.lua
local SettingsPersistence = {}
SettingsPersistence.__index = SettingsPersistence

local SCHEMA_VERSION = 2
local SETTINGS_FOLDER = "CustomHub"
local SAVE_DEBOUNCE_SECONDS = 0.6
local SETTING_KINDS = {
    settingDropdown = true,
    settingSelect = true,
    settingSlider = true,
    settingToggle = true,
}

local function isFiniteNumber(value)
    return type(value) == "number"
        and value == value
        and value > -math.huge
        and value < math.huge
end

local function isSimpleString(value)
    return type(value) == "string"
        and #value > 0
        and #value <= 128
        and not value:find("[%c]")
end

local function optionValue(option)
    if type(option) == "string" then
        return option
    end
    if type(option) == "table" then
        return option.Value or option.value or option.Name or option.Label
    end
    return nil
end

local function containsOption(options, value)
    if type(options) ~= "table" then
        return nil
    end
    for _, option in ipairs(options) do
        if optionValue(option) == value then
            return true
        end
    end
    return false
end

local function deepEqual(left, right)
    if type(left) ~= type(right) then
        return false
    end
    if type(left) ~= "table" then
        return left == right
    end
    for key, value in pairs(left) do
        if not deepEqual(value, right[key]) then
            return false
        end
    end
    for key in pairs(right) do
        if left[key] == nil then
            return false
        end
    end
    return true
end

local function copyTable(value)
    if type(value) ~= "table" then
        return value
    end
    local result = {}
    for key, child in pairs(value) do
        result[key] = copyTable(child)
    end
    return result
end

local function validateHopSession(value)
    if type(value) ~= "table"
        or tonumber(value.PlaceId) == nil
        or tonumber(value.PlaceId) <= 0
        or type(value.ExpiresAt) ~= "number"
        or value.ExpiresAt <= os.time()
        or value.ExpiresAt > os.time() + 86400
        or type(value.Modes) ~= "table"
    then
        return nil
    end

    local modes = {
        EliteHunter = value.Modes.EliteHunter == true,
        Berry = value.Modes.Berry == true,
    }
    if not modes.EliteHunter and not modes.Berry then
        return nil
    end

    local visited = {}
    if type(value.Visited) == "table" then
        for _, jobId in ipairs(value.Visited) do
            if isSimpleString(jobId) then
                visited[#visited + 1] = jobId
                if #visited >= 300 then
                    break
                end
            end
        end
    end

    local session = {
        PlaceId = math.floor(tonumber(value.PlaceId)),
        ExpiresAt = math.floor(value.ExpiresAt),
        Modes = modes,
        Visited = visited,
    }
    if isSimpleString(value.PendingJobId) then
        session.PendingJobId = value.PendingJobId
    end
    if type(value.Cursor) == "string" and #value.Cursor <= 2048 then
        session.Cursor = value.Cursor
    end
    return session
end

function SettingsPersistence.new(config, compatibility)
    local self = setmetatable({
        Config = config,
        Compatibility = compatibility,
        State = nil,
        Storage = nil,
        Path = nil,
        InterfacePreferences = nil,
        Rules = {},
        LastSnapshot = nil,
        HopSession = nil,
        LastHopSession = nil,
        SaveGeneration = 0,
        Destroyed = false,
        ReadOnly = false,
        LoadedFromFile = false,
        LoadWarning = nil,
        LastSaveWarningAt = 0,
    }, SettingsPersistence)

    self:_BuildRules()
    self:_InitializeStorage()
    return self
end

function SettingsPersistence:_BuildRules()
    local config = self.Config or {}
    local pages = config.Pages
    if type(pages) ~= "table" then
        return
    end

    for _, page in pairs(pages) do
        for _, control in ipairs(type(page) == "table" and page.Controls or {}) do
            local kind = control.Kind
            local setting = control.Setting
            if SETTING_KINDS[kind] and type(setting) == "string" then
                local group = control.SettingsKey or "FarmSettings"
                if group == "FarmSettings"
                    or group == "StackFarmSettings"
                    or group == "TravelSettings"
                    or group == "StartupSettings"
                then
                    self.Rules[group] = self.Rules[group] or {}
                    self.Rules[group][setting] = control
                end
            end
        end
    end
end

function SettingsPersistence:_InitializeStorage()
    local compatibility = self.Compatibility
    local player = compatibility and compatibility.Player
    local userId = player and tonumber(player.UserId)
    if not userId or userId <= 0 or userId % 1 ~= 0 then
        self.LoadWarning = "Settings auto-save is unavailable for this player session."
        return
    end

    local storage, storageError = compatibility:GetLocalSettingsStorage()
    if not storage then
        self.LoadWarning = "Settings are session-only; local file storage is unavailable."
        self.StorageError = storageError
        return
    end

    self.Storage = storage
    self.Path = SETTINGS_FOLDER .. "/settings_" .. tostring(userId) .. ".json"
end

function SettingsPersistence:SetState(state)
    self.State = state
    local preferences = self.InterfacePreferences
    if state and type(preferences) == "table" then
        if type(preferences.UiSize) == "string" then
            state:SetUiSize(preferences.UiSize)
        end
        if type(preferences.Compact) == "boolean" then
            state:SetCompact(preferences.Compact)
        end
    end
    self.LastSnapshot = self:_Capture()
end

function SettingsPersistence:_ValidateSetting(control, value)
    if control.Kind == "settingToggle" then
        return type(value) == "boolean"
    end

    if control.Kind == "settingSlider" then
        if not isFiniteNumber(value) then
            return false
        end
        local minimum = tonumber(control.Min)
        local maximum = tonumber(control.Max)
        return minimum ~= nil and maximum ~= nil
            and value >= minimum and value <= maximum
    end

    if control.Kind == "settingDropdown" or control.Kind == "settingSelect" then
        if not isSimpleString(value) then
            return false
        end
        local optionResult = containsOption(control.Options, value)
        if optionResult == false then
            return false
        end
        return true
    end

    return false
end

function SettingsPersistence:_Capture()
    local snapshot = {
        SchemaVersion = SCHEMA_VERSION,
        Settings = {},
        Interface = {},
    }
    local config = self.Config or {}

    for group, rules in pairs(self.Rules) do
        local source = config[group]
        if type(source) == "table" then
            local savedGroup = {}
            for setting, control in pairs(rules) do
                local value = source[setting]
                if value ~= nil and self:_ValidateSetting(control, value) then
                    savedGroup[setting] = value
                end
            end
            snapshot.Settings[group] = savedGroup
        end
    end

    local state = self.State
    local stateValues = state and state:GetSnapshot()
    local defaults = config.Defaults or {}
    local uiSize = stateValues and stateValues.uiSize or defaults.UiSize
    local compact = stateValues and stateValues.compact
    if compact == nil then
        compact = defaults.Compact
    end
    if type(uiSize) == "string" then
        snapshot.Interface.UiSize = uiSize
    end
    if type(compact) == "boolean" then
        snapshot.Interface.Compact = compact
    end
    return snapshot
end

function SettingsPersistence:_ApplySavedSettings(data)
    local config = self.Config or {}
    local savedGroups = data.Settings
    if type(savedGroups) == "table" then
        for group, rules in pairs(self.Rules) do
            local savedGroup = savedGroups[group]
            local target = config[group]
            if type(savedGroup) == "table" and type(target) == "table" then
                for setting, control in pairs(rules) do
                    local value = savedGroup[setting]
                    if value ~= nil and self:_ValidateSetting(control, value) then
                        target[setting] = value
                    end
                end
            end
        end
    end

    local interface = data.Interface
    local defaults = config.Defaults
    local footprints = config.Layout and config.Layout.UiSizeFootprints
    if type(interface) == "table" and type(defaults) == "table" then
        self.InterfacePreferences = {}
        if type(interface.UiSize) == "string"
            and type(footprints) == "table"
            and type(footprints[interface.UiSize]) == "number"
        then
            self.InterfacePreferences.UiSize = interface.UiSize
        end
        if type(interface.Compact) == "boolean" then
            self.InterfacePreferences.Compact = interface.Compact
        end
    end
end

function SettingsPersistence:Load()
    if not self.Storage or not self.Path then
        self.LastSnapshot = self:_Capture()
        return false, self.LoadWarning
    end

    local fileExists
    if type(self.Storage.Exists) == "function" then
        local existsOk, exists = pcall(self.Storage.Exists, self.Path)
        if existsOk and type(exists) == "boolean" then
            fileExists = exists
        end
    end

    if fileExists == false then
        self.LastSnapshot = self:_Capture()
        return true
    end

    local readOk, content = pcall(self.Storage.Read, self.Path)
    if not readOk or type(content) ~= "string" or content == "" then
        self.LastSnapshot = self:_Capture()
        if fileExists == true then
            self.LoadWarning = "Saved settings could not be read; defaults are active."
        end
        return true
    end

    local decodeOk, data = pcall(function()
        return game:GetService("HttpService"):JSONDecode(content)
    end)
    if not decodeOk or type(data) ~= "table" then
        self.LoadWarning = "Saved settings are invalid; defaults are active."
        self.LastSnapshot = self:_Capture()
        return true
    end

    local version = tonumber(data.SchemaVersion) or 0
    if version > SCHEMA_VERSION then
        self.ReadOnly = true
        self.LoadWarning = "Saved settings are newer than this hub; auto-save is paused."
        self.LastSnapshot = self:_Capture()
        return true
    end

    self:_ApplySavedSettings(data)
    self.HopSession = validateHopSession(data.HopSession)
    self.LastHopSession = copyTable(self.HopSession)
    self.LoadedFromFile = true
    self.LastSnapshot = self:_Capture()
    return true
end

function SettingsPersistence:_ReportSaveError(message)
    local now = os.clock()
    if self.LastSaveWarningAt > 0 and now - self.LastSaveWarningAt < 30 then
        return
    end
    self.LastSaveWarningAt = now
    self.LoadWarning = "Settings auto-save failed; changes may not persist."
    if self.State then
        self.State:SetStatus(self.LoadWarning, "warning")
    end
end

function SettingsPersistence:Save(force)
    if self.Destroyed or self.ReadOnly then
        return false, "Settings persistence is paused"
    end
    if not self.Storage or not self.Path then
        return false, self.LoadWarning or "Local settings storage is unavailable"
    end

    local snapshot = self:_Capture()
    local hopSession = copyTable(self.HopSession)
    if not force
        and self.LastSnapshot
        and deepEqual(snapshot, self.LastSnapshot)
        and deepEqual(hopSession, self.LastHopSession)
    then
        return true
    end

    local document = copyTable(snapshot)
    if hopSession then
        document.HopSession = hopSession
    end
    local encodeOk, content = pcall(function()
        return game:GetService("HttpService"):JSONEncode(document)
    end)
    if not encodeOk or type(content) ~= "string" then
        self:_ReportSaveError("Could not encode settings")
        return false, tostring(content)
    end

    local writeOk, writeResult, writeError = pcall(self.Storage.Write, self.Path, content)
    if not writeOk or writeResult ~= true then
        local err = writeOk and writeError or writeResult
        self:_ReportSaveError(err)
        return false, tostring(err or "Local settings file could not be written")
    end

    self.LastSnapshot = snapshot
    self.LastHopSession = copyTable(hopSession)
    self.LoadWarning = nil
    return true
end

function SettingsPersistence:CanPersistHopSession()
    return not self.Destroyed
        and not self.ReadOnly
        and self.Storage ~= nil
        and self.Path ~= nil
end

function SettingsPersistence:GetHopSession()
    return copyTable(self.HopSession)
end

function SettingsPersistence:SetHopSession(session)
    if not self:CanPersistHopSession() then
        return false, self.LoadWarning or "Local settings storage is unavailable"
    end
    local validated = validateHopSession(session)
    if not validated then
        return false, "Hop session data is invalid or expired"
    end
    self.HopSession = validated
    return self:Save(true)
end

function SettingsPersistence:ClearHopSession()
    if not self:CanPersistHopSession() then
        self.HopSession = nil
        return false, self.LoadWarning or "Local settings storage is unavailable"
    end
    self.HopSession = nil
    return self:Save(true)
end

function SettingsPersistence:ScheduleSave()
    if self.Destroyed or self.ReadOnly or not self.Storage then
        return false
    end
    local snapshot = self:_Capture()
    if self.LastSnapshot and deepEqual(snapshot, self.LastSnapshot) then
        return true
    end

    self.SaveGeneration += 1
    local generation = self.SaveGeneration
    task.delay(SAVE_DEBOUNCE_SECONDS, function()
        if self.Destroyed or generation ~= self.SaveGeneration then
            return
        end
        self:Save()
    end)
    return true
end

function SettingsPersistence:Flush()
    self.SaveGeneration += 1
    if self.Destroyed or self.ReadOnly or not self.Storage then
        return false, self.LoadWarning or "Local settings storage is unavailable"
    end
    return self:Save()
end

function SettingsPersistence:GetStartupWarning()
    return self.LoadWarning
end

function SettingsPersistence:Destroy()
    self.SaveGeneration += 1
    self.Destroyed = true
end

return SettingsPersistence
-- END SOURCE: src/ReplicatedStorage/CustomHub/SettingsPersistence.lua
end

__bundleFactories["CustomHub.FeatureManager"] = function()
-- BEGIN SOURCE: src/ReplicatedStorage/CustomHub/FeatureManager.lua
local PlaceholderFeatures = __bundleLoad("CustomHub.Features.PlaceholderFeatures")
local MainFarm = __bundleLoad("CustomHub.Features.MainFarm")
local TeleportFeature = __bundleLoad("CustomHub.Features.TeleportFeature")
local StatusFeature = __bundleLoad("CustomHub.Features.StatusFeature")
local MovementService = __bundleLoad("CustomHub.Features.Farm.MovementService")
local TaskCoordinator = __bundleLoad("CustomHub.Features.TaskCoordinator")

local FeatureManager = {}
FeatureManager.__index = FeatureManager

function FeatureManager.new(state, compatibility, config, settingsPersistence)
    local movementService = MovementService.new(compatibility, function(message, kind)
        state:SetStatus(message, kind or "info")
    end)
    local taskCoordinator = TaskCoordinator.new()
    return setmetatable({
        State = state,
        Modules = { MainFarm, TeleportFeature, StatusFeature, PlaceholderFeatures },
        InitializedModules = {},
        Context = {
            State = state,
            Compatibility = compatibility,
            Config = config,
            SettingsPersistence = settingsPersistence,
            MovementService = movementService,
            TaskCoordinator = taskCoordinator,
            MainFarm = MainFarm,
            TeleportFeature = TeleportFeature,
        },
    }, FeatureManager)
end

function FeatureManager:_ScheduleSettingsSave()
    local persistence = self.Context and self.Context.SettingsPersistence
    if persistence then
        persistence:ScheduleSave()
    end
end

function FeatureManager:Initialize()
    for _, featureModule in ipairs(self.Modules) do
        local ok, result = pcall(featureModule.Initialize, featureModule, self.Context)
        if not ok or result == false then
            local message = not ok and result or "Feature module initialization declined"
            self.State:SetStatus("Feature initialization error: " .. tostring(message), "error")
            self:Cleanup()
            return false, tostring(message)
        end
        table.insert(self.InitializedModules, featureModule)
    end
    local mainFarm = self.Context and self.Context.MainFarm
    if mainFarm and type(mainFarm.ResumePendingHop) == "function" then
        local resumeOk, resumeResult, resumeError = pcall(
            mainFarm.ResumePendingHop,
            mainFarm
        )
        if not resumeOk or resumeResult == false and resumeError then
            self.State:SetStatus(
                "Server search could not resume: "
                    .. tostring(resumeOk and resumeError or resumeResult),
                "warning"
            )
        end
    end
    return true
end

function FeatureManager:Dispatch(actionId, payload)
    if actionId == "settings.team.select" then
        local startupSettings = self.Context.Config
            and self.Context.Config.StartupSettings
        if not startupSettings or (payload ~= "Marines" and payload ~= "Pirates") then
            self.State:SetStatus("Team selection setting is unavailable.", "error")
            return false, "Unsupported team"
        end
        startupSettings.Team = payload
        self:_ScheduleSettingsSave()
        local compatibility = self.Context.Compatibility
        if compatibility then
            compatibility:SelectTeamIfPrompted(payload, 0.2)
        end
        self.State:SetStatus("Team to auto-select: " .. payload, "success")
        return true
    end

    if actionId == "settings.uiSize.select" then
        local layout = self.Context.Config and self.Context.Config.Layout
        local footprints = layout and layout.UiSizeFootprints
        if type(footprints) ~= "table"
            or type(payload) ~= "string"
            or type(footprints[payload]) ~= "number" then
            self.State:SetStatus("UI size setting is unavailable.", "error")
            return false, "Unsupported UI size"
        end
        self.State:SetUiSize(payload)
        self:_ScheduleSettingsSave()
        self.State:SetStatus("UI size: " .. payload .. ".", "success")
        return true
    end

    if actionId == "settings.compact" then
        self.State:SetCompact(payload == true)
        self:_ScheduleSettingsSave()
        self.State:SetStatus(
            "Compact layout " .. (payload and "enabled." or "disabled.") .. " (UI only).",
            "success"
        )
        return true
    end

    if actionId == "settings.reset" then
        self.State:ResetPresentation()
        self:_ScheduleSettingsSave()
        return true
    end

    if actionId == "farm.weaponCategory.select" then
        local farmSettings = self.Context.Config and self.Context.Config.FarmSettings
        local categories = farmSettings and farmSettings.WeaponCategories
        local selectedCategory
        if type(categories) == "table" and type(payload) == "string" then
            for _, category in ipairs(categories) do
                if category == payload then
                    selectedCategory = category
                    break
                end
            end
        end
        if not selectedCategory then
            self.State:SetStatus("Weapon category settings are unavailable.", "error")
            return false, "Unsupported weapon category"
        end

        farmSettings.WeaponCategory = selectedCategory
        self:_ScheduleSettingsSave()
        self.State:SetStatus(
            "Farm weapon: " .. tostring(farmSettings.WeaponCategory),
            "success"
        )
        return true
    end

    for _, featureModule in ipairs(self.Modules) do
        local ok, handled = pcall(
            featureModule.Handle,
            featureModule,
            actionId,
            payload,
            self.Context
        )
        if not ok then
            self.State:SetStatus("Action error: " .. tostring(handled), "error")
            return false, tostring(handled)
        end
        if handled then
            self:_ScheduleSettingsSave()
            return true
        end
    end

    local message = "No UI-shell action registered for " .. tostring(actionId)
    self.State:SetStatus(message, "error")
    return false, message
end

function FeatureManager:Cleanup()
    for index = #self.InitializedModules, 1, -1 do
        local featureModule = self.InitializedModules[index]
        local ok, err = pcall(featureModule.Cleanup, featureModule, self.Context)
        if not ok then
            self.State:SetStatus("Feature cleanup error: " .. tostring(err), "error")
        end
        self.InitializedModules[index] = nil
    end
    if self.Context and self.Context.TaskCoordinator then
        self.Context.TaskCoordinator:Cleanup()
    end
end

return FeatureManager
-- END SOURCE: src/ReplicatedStorage/CustomHub/FeatureManager.lua
end

__bundleFactories["CustomHub.UI"] = function()
-- BEGIN SOURCE: src/ReplicatedStorage/CustomHub/UI.lua
local UI = {}
UI.__index = UI

local UserInputService = game:GetService("UserInputService")
local TweenService = game:GetService("TweenService")
local MINIMIZE_BUTTON_WIDTH = 26
local HEADER_BUTTON_GAP = 5
local RESTORE_BUTTON_SIZE = Vector2.new(56, 56)
local RESTORE_DRAG_THRESHOLD = 8
local WINDOW_VISIBLE_GRIP_WIDTH = 128
local WINDOW_VISIBLE_GRIP_HEIGHT = 24
local HEADER_HEIGHT = 34
local FOOTER_HEIGHT = 24

local function create(className, properties, parent)
    local instance = Instance.new(className)
    for property, value in pairs(properties) do
        instance[property] = value
    end
    if className == "TextLabel" or className == "TextButton" or className == "TextBox" then
        instance.AutoLocalize = false
    end
    instance.Parent = parent
    return instance
end

local function addCorner(parent, radius)
    create("UICorner", {
        CornerRadius = UDim.new(0, radius or 4),
    }, parent)
end

local function displayTabName(tabName)
    return tabName == "Farm" and "Farming"
        or tabName == "StatusServer" and "Server Status"
        or tabName
end

local function normalizeSearchText(text)
    return string.lower((tostring(text or ""):match("^%s*(.-)%s*$") or ""))
end

local function clampDragPosition(origin, delta, viewport, size)
    local halfX = math.min(size.X / 2, viewport.X / 2)
    local halfY = math.min(size.Y / 2, viewport.Y / 2)
    local startCenterX = viewport.X * origin.X.Scale + origin.X.Offset
    local startCenterY = viewport.Y * origin.Y.Scale + origin.Y.Offset
    local centerX = math.clamp(
        startCenterX + delta.X,
        halfX,
        math.max(halfX, viewport.X - halfX)
    )
    local centerY = math.clamp(
        startCenterY + delta.Y,
        halfY,
        math.max(halfY, viewport.Y - halfY)
    )
    return UDim2.new(
        origin.X.Scale,
        centerX - viewport.X * origin.X.Scale,
        origin.Y.Scale,
        centerY - viewport.Y * origin.Y.Scale
    )
end

local function clampWindowDragPosition(origin, delta, viewport, size, headerHeight)
    local headerExtent = headerHeight or HEADER_HEIGHT
    local visibleGripWidth = math.min(
        WINDOW_VISIBLE_GRIP_WIDTH,
        size.X,
        viewport.X / 2
    )
    local visibleHeaderHeight = math.min(
        WINDOW_VISIBLE_GRIP_HEIGHT,
        headerExtent,
        viewport.Y / 2
    )
    local halfX = size.X / 2
    local halfY = size.Y / 2
    local startCenterX = viewport.X * origin.X.Scale + origin.X.Offset
    local startCenterY = viewport.Y * origin.Y.Scale + origin.Y.Offset
    local centerX = math.clamp(
        startCenterX + delta.X,
        visibleGripWidth - halfX,
        viewport.X - visibleGripWidth + halfX
    )
    local minCenterY = visibleHeaderHeight - headerExtent + halfY
    local centerY = math.clamp(
        startCenterY + delta.Y,
        minCenterY,
        math.max(minCenterY, viewport.Y - visibleHeaderHeight + halfY)
    )

    return UDim2.new(
        origin.X.Scale,
        centerX - viewport.X * origin.X.Scale,
        origin.Y.Scale,
        centerY - viewport.Y * origin.Y.Scale
    )
end

local function disconnectAll(connections)
    for index = #connections, 1, -1 do
        local connection = connections[index]
        if connection and connection.Connected then
            connection:Disconnect()
        end
        connections[index] = nil
    end
end

function UI.new(playerGui, state, compatibility, config, dispatch, onClose)
    local self = setmetatable({
        PlayerGui = playerGui,
