local function distance(first, second)
    return (first - second).Magnitude
end

local function repeatsGatewayArea(position, visitedPositions)
    for _, visitedPosition in ipairs(visitedPositions) do
        if typeof(visitedPosition) == "Vector3"
            and distance(position, visitedPosition) <= ROUTE_LOCATION_REPEAT_DISTANCE
        then
            return true
        end
    end
    return false
end

local function formatPosition(position)
    if typeof(position) ~= "Vector3" then
        return "n/a"
    end
    return string.format("(%.1f, %.1f, %.1f)", position.X, position.Y, position.Z)
end

local function formatScalar(value, limit)
    local text = tostring(value):gsub("[%c]", " ")
    limit = limit or 120
    if #text > limit then
        text = string.sub(text, 1, limit) .. "..."
    end
    return text
end

local function getNoAccessCacheKey(compatibility, source)
    local playerId = compatibility
            and compatibility.Player
            and compatibility.Player.UserId
        or nil
    if playerId == nil or not source.Requires or not source.RequiresTitle then
        return nil
    end
    return table.concat({
        tostring(playerId),
        source.Requires,
        source.RequiresTitle,
    }, "|")
end

function MapGatewayService.new(compatibility)
    return setmetatable({
        Compatibility = compatibility,
        FailedUntil = {},
        LastFailures = {},
        TikiNoAccessCache = {},
        LastDiagnostic = nil,
    }, MapGatewayService)
end

function MapGatewayService:_CurrentSeaIndex()
    local compatibility = self.Compatibility
    local found
    local count = 0
    for index, method in ipairs({ "IsFirstSea", "IsSecondSea", "IsThirdSea" }) do
        local check = compatibility and compatibility[method]
        if type(check) == "function" then
            local ok, result = pcall(check, compatibility)
            if ok and result == true then
                found = index
                count += 1
            end
        end
    end
    return count == 1 and found or nil
end

function MapGatewayService:_ResolveStand(route)
    if route.Stand then
        return route.Stand
    end
    if not route.Part then
        return nil
    end

    local workspace = self.Compatibility and self.Compatibility.Workspace
    local instance = workspace and workspace:FindFirstChild(route.Part, true)
    if not instance then
        return nil
    end
    if instance:IsA("BasePart") then
        return instance.Position
    elseif instance:IsA("Model") then
        return instance:GetPivot().Position
    end
    return nil
end

function MapGatewayService:_ResolveTouchTarget(route)
    local compatibility = self.Compatibility
    if not compatibility or not compatibility.CanSimulateTouch
        or not compatibility:CanSimulateTouch()
    then
        return nil, "touch simulation is unavailable on this client"
    end
    local workspace = compatibility.Workspace
    local mapRoot = workspace and workspace:FindFirstChild("Map")
    local map = mapRoot and mapRoot:FindFirstChild(route.Map or "Boat Castle", true)
    local trigger = map and map:FindFirstChild(route.Touch, true)
    local collectionService = compatibility.CollectionService
    if not trigger then
        return nil, "gateway trigger is not loaded"
    end
    if not collectionService then
        return nil, "CollectionService is unavailable"
    end
    local tagOk, tagged = pcall(collectionService.HasTag, collectionService, trigger, "BoatCastleTeleporter")
    if not tagOk or tagged ~= true then
        return nil, "gateway trigger is not tagged BoatCastleTeleporter"
    end
    local hitbox = trigger:FindFirstChild("Hitbox", true)
    if not hitbox or not hitbox:IsA("BasePart") then
        return nil, "gateway trigger Hitbox is missing or not a BasePart"
    end
    return hitbox, nil
end

function MapGatewayService:_GetAvailableRoutes(seaIndex, currentPosition, destination)
    local compatibility = self.Compatibility
    local now = os.clock()
    local routes = {}
    local candidates = {}
    self.TikiNoAccessCache = self.TikiNoAccessCache or {}
    local diagnostic = self.LastDiagnostic
    if diagnostic then
        diagnostic.Candidates = candidates
    end

    local function estimateTitleRouteCost(source)
        local estimateRoutes = {}
        for _, route in ipairs(ROUTES_BY_SEA[seaIndex] or {}) do
            local includeRoute = route.Name == source.Name
            if not includeRoute and not route.RequiresTitle then
                includeRoute = true
                if route.Requires then
                    local checkOk, owned = pcall(
                        compatibility.HasOwnedInventoryItem,
                        compatibility,
                        route.Requires
                    )
                    includeRoute = checkOk and owned == true
                end
            end

            if includeRoute and typeof(route.Destination) == "Vector3" then
                local stand = route.Name == source.Name
                        and source.Stand
                    or self:_ResolveStand(route)
                if typeof(stand) == "Vector3" then
                    table.insert(estimateRoutes, {
                        Name = route.Name,
                        Stand = stand,
                        Destination = route.Destination,
                    })
                end
            end
        end

        local function findBestTitlePath(position, remainingHops, used, titleRouteUsed, visited)
            local bestCost = titleRouteUsed and distance(position, destination) or math.huge
            if remainingHops <= 0 then
                return bestCost
            end

            for _, route in ipairs(estimateRoutes) do
                if not used[route.Name]
                    and not repeatsGatewayArea(route.Destination, visited)
                then
                    used[route.Name] = true
                    table.insert(visited, route.Destination)
                    local includesTitleRoute =
                        titleRouteUsed or route.Name == source.Name
                    local remainingCost = findBestTitlePath(
                        route.Destination,
                        remainingHops - 1,
                        used,
                        includesTitleRoute,
                        visited
                    )
                    table.remove(visited)
                    used[route.Name] = nil
                    local routeCost = distance(position, route.Stand) + remainingCost
                    if routeCost < bestCost then
                        bestCost = routeCost
                    end
                end
            end
            return bestCost
        end

        return findBestTitlePath(
            currentPosition,
            MAX_ROUTE_HOPS,
            {},
            false,
            { currentPosition }
        )
    end

    for _, source in ipairs(ROUTES_BY_SEA[seaIndex] or {}) do
        local candidate = {
            Name = source.Name,
            Requirement = source.Requires,
            FallbackTitle = source.RequiresTitle,
            Activation = source.Touch and "touch" or "requestEntrance",
            Eligible = false,
        }
        local lastFailure = self.LastFailures[source.Name]
        if lastFailure then
            candidate.PreviousFailure = lastFailure.Reason
            candidate.PreviousFailureAge = math.max(0, now - lastFailure.At)
            local attempt = lastFailure.Attempt
            if attempt then
                candidate.PreviousFailurePhase = attempt.Phase
                candidate.PreviousFailureCallStatus = attempt.RemoteCallStatus
                candidate.PreviousFailureDetail = attempt.Failure
                candidate.PreviousFailureActivationFailure = attempt.ActivationFailure
                candidate.PreviousFailureDisplacement = attempt.Displacement
            end
        end
        local failedUntil = self.FailedUntil[source.Name] or 0
        if now < failedUntil then
            candidate.Reason = "temporarily skipped after a previous failure"
            candidate.CooldownRemaining = math.max(0, failedUntil - now)
        else
            local available = true
            if source.Requires then
                local checkOk, owned, inventoryError = pcall(
                    compatibility.HasOwnedInventoryItem,
                    compatibility,
                    source.Requires
                )
                available = checkOk and owned == true
                candidate.ItemRequirementOwned = available
                local accessCacheKey = getNoAccessCacheKey(compatibility, source)
                if available then
                    candidate.AccessBy = source.Requires
                    if accessCacheKey then
                        self.TikiNoAccessCache[accessCacheKey] = nil
                    end
                elseif source.RequiresTitle then
                    local titleRouteCost = estimateTitleRouteCost(source)
                    local directCost = distance(currentPosition, destination)
                    local titleRouteSavings = directCost - titleRouteCost
                    candidate.TitleRouteCost = titleRouteCost
                    candidate.TitleRouteSavings = titleRouteSavings
                    if titleRouteSavings >= MINIMUM_DISTANCE_SAVED then
                        local cachedNoAccess = accessCacheKey
                                and self.TikiNoAccessCache[accessCacheKey]
                            or nil
                        if cachedNoAccess and now >= cachedNoAccess.ExpiresAt then
                            self.TikiNoAccessCache[accessCacheKey] = nil
                            cachedNoAccess = nil
                        end
                        if cachedNoAccess and checkOk and owned == false
                            and inventoryError == nil
                        then
                            candidate.TitleRequirementOwned = false
                            candidate.ConfirmedNoAccessCached = true
                            candidate.NoAccessCacheRemaining =
                                math.max(0, cachedNoAccess.ExpiresAt - now)
                            candidate.Reason =
                                "no Feathered Visage or title access confirmed recently"
                        else
                            local titleCheckOk
                            local titleOwned
                            local titleError
                            local titlePending = false
                            local titleCheckIsAsync = false
                            if type(compatibility.BeginUnlockedTitleCheck) == "function" then
                                titleCheckIsAsync = true
                                local beginOk
                                beginOk, titleOwned, titleError, titlePending = pcall(
                                    compatibility.BeginUnlockedTitleCheck,
                                    compatibility,
                                    source.RequiresTitle
                                )
                                titleCheckOk = beginOk
                            else
                                titleCheckOk, titleOwned, titleError = pcall(
                                    compatibility.HasUnlockedTitle,
                                    compatibility,
                                    source.RequiresTitle
                                )
                            end
                            if titleCheckOk and type(titleOwned) == "boolean" then
                                candidate.TitleRequirementOwned = titleOwned
                            end
                            candidate.TitleCheckPending = titleCheckOk
                                and (
                                    titleCheckIsAsync
                                        and titlePending == true
                                    or not titleCheckIsAsync
                                        and titleOwned == nil
                                )
                            if titleCheckOk and titleOwned == true then
                                available = true
                                candidate.AccessBy = source.RequiresTitle
                                if accessCacheKey then
                                    self.TikiNoAccessCache[accessCacheKey] = nil
                                end
                            elseif candidate.TitleCheckPending then
                                available = true
                                candidate.ProvisionalTitleAccess = true
                                candidate.Reason = "title access is being checked"
                            else
                                if checkOk and owned == false and inventoryError == nil
                                    and titleCheckOk and titleOwned == false
                                    and accessCacheKey
                                then
                                    local expiresAt =
                                        os.clock() + CONFIRMED_NO_TIKI_ACCESS_CACHE_TTL
                                    self.TikiNoAccessCache[accessCacheKey] = {
                                        ExpiresAt = expiresAt,
                                    }
                                    candidate.ConfirmedNoAccessCached = true
                                    candidate.NoAccessCacheRemaining =
                                        CONFIRMED_NO_TIKI_ACCESS_CACHE_TTL
                                    candidate.Reason =
                                        "no Feathered Visage or title access confirmed recently"
                                else
                                    local itemReason = checkOk
                                            and (inventoryError
                                                or "required item not found in inventory")
                                        or ("inventory check failed: " .. formatScalar(owned))
                                    local titleReason = titleCheckOk
                                            and (titleError
                                                or (titleOwned == false
                                                    and "title is locked"
                                                    or "title state is unknown"))
                                        or ("title check failed: " .. formatScalar(titleOwned))
                                    candidate.Reason = itemReason .. "; " .. titleReason
                                end
                            end
                        end
                    else
                        candidate.Reason =
                            "required item not found; title lookup skipped because this gateway is not shorter"
                    end
                else
                    candidate.Reason = checkOk
                            and (inventoryError or "required item not found in inventory")
                        or ("inventory check failed: " .. formatScalar(owned))
                end
            end
            candidate.RequirementOwned =
                available and candidate.ProvisionalTitleAccess ~= true

            local stand = available and self:_ResolveStand(source) or nil
            if available and typeof(stand) ~= "Vector3" then
                available = false
                candidate.Reason = "gateway stand position is not loaded"
            end
            local touchTarget
            if available and source.Touch then
                local touchReason
                touchTarget, touchReason = self:_ResolveTouchTarget(source)
                if touchTarget then
                    candidate.TouchTriggerLoaded = true
                elseif touchReason == "gateway trigger is not loaded" then
                    candidate.TouchTriggerLoaded = false
                    candidate.Reason = "trigger lookup deferred until gateway stand is reached"
                else
                    available = false
                    candidate.Reason = touchReason
                end
            end

            candidate.Eligible = available
            if available then
                candidate.Stand = stand
                candidate.Destination = source.Destination
                if diagnostic and typeof(diagnostic.CurrentPosition) == "Vector3" then
                    candidate.StandDistance = distance(diagnostic.CurrentPosition, stand)
                end
                local route = table.clone(source)
                route.Stand = stand
                route.TouchTarget = touchTarget
                route.ProvisionalTitleAccess =
                    candidate.ProvisionalTitleAccess == true
                table.insert(routes, route)
            end
        end
        table.insert(candidates, candidate)
    end
    return routes
end

function MapGatewayService:HasPendingTitleChecks()
    for _, candidate in ipairs(self.LastDiagnostic and self.LastDiagnostic.Candidates or {}) do
        if candidate.TitleCheckPending then
            return true
        end
    end
    return false
end

function MapGatewayService:_RememberConfirmedNoAccess(route)
    if not route or not route.Requires or not route.RequiresTitle then
        return false
    end
    local compatibility = self.Compatibility
    local key = getNoAccessCacheKey(compatibility, route)
    if not key then
        return false
    end
    local checkOk, owned, inventoryError = pcall(
        compatibility.HasOwnedInventoryItem,
        compatibility,
        route.Requires
    )
    if not checkOk or owned ~= false or inventoryError ~= nil then
        return false
    end
    self.TikiNoAccessCache = self.TikiNoAccessCache or {}
    self.TikiNoAccessCache[key] = {
        ExpiresAt = os.clock() + CONFIRMED_NO_TIKI_ACCESS_CACHE_TTL,
    }
    return true
end

function MapGatewayService:GetTitleAccessState(route)
    local titleRoute = route and (
        route.ProvisionalTitleAccess == true and route
            or route.PlanTitleAccessRoute
    )
    if not titleRoute then
        return true, "route access is already confirmed", false
    end
    local compatibility = self.Compatibility
    if not compatibility or type(compatibility.GetUnlockedTitleCheck) ~= "function" then
        return nil, "title access status is unavailable", false
    end
    local ok, state, reason, pending = pcall(
        compatibility.GetUnlockedTitleCheck,
        compatibility,
        titleRoute.RequiresTitle
    )
    if not ok then
        return nil, tostring(state), false
    end
    return state, reason, pending == true
end

function MapGatewayService:ShouldAbortForUnconfirmedTitle(route)
    if not route
        or (route.ProvisionalTitleAccess ~= true and not route.PlanTitleAccessRoute)
    then
        return false
    end
    local state, reason, pending = self:GetTitleAccessState(route)
    if state == true or pending then
        return false
    end
    if state == false then
        self:_RememberConfirmedNoAccess(
            route.ProvisionalTitleAccess == true and route
                or route.PlanTitleAccessRoute
        )
    end
    return true, reason or "title access could not be confirmed"
end

function MapGatewayService:WaitForTitleAccess(route, timeout, isCurrent)
    if not route
        or (route.ProvisionalTitleAccess ~= true and not route.PlanTitleAccessRoute)
    then
        return true
    end
    local deadline = os.clock() + math.max(0, tonumber(timeout) or 0)
    repeat
        if type(isCurrent) == "function" and not isCurrent() then
            return false, "Travel was cancelled"
        end
        local state, reason, pending = self:GetTitleAccessState(route)
        if state == true then
            return true
        end
        if state == false then
            self:_RememberConfirmedNoAccess(
                route.ProvisionalTitleAccess == true and route
                    or route.PlanTitleAccessRoute
            )
            return false, reason or "title access could not be confirmed"
        end
        if not pending then
            return false, reason or "title access could not be confirmed"
        end
        if os.clock() >= deadline then
            break
        end
        task.wait(0.05)
    until false
    return false, "title access check timed out"
end

function MapGatewayService:FindPlan(
    destination,
    currentPosition,
    destinationLabel,
    excludedRoutes,
    visitedPositions
)
    excludedRoutes = type(excludedRoutes) == "table" and excludedRoutes or {}
    visitedPositions = type(visitedPositions) == "table" and visitedPositions or {}
    self.LastDiagnostic = {
        At = os.clock(),
        DestinationLabel = destinationLabel,
        Destination = destination,
        CurrentPosition = currentPosition,
        Phase = "checking available gateways",
    }
    local diagnostic = self.LastDiagnostic
    if typeof(destination) ~= "Vector3" or typeof(currentPosition) ~= "Vector3" then
        diagnostic.Phase = "direct travel: positions unavailable"
        diagnostic.Reason = "Travel positions are unavailable"
        return {}, "Travel positions are unavailable"
    end
    local seaIndex = self:_CurrentSeaIndex()
    if not seaIndex then
        diagnostic.Phase = "direct travel: current sea unavailable"
        diagnostic.Reason = "Current sea is unavailable"
        return {}, "Current sea is unavailable"
    end
    diagnostic.Sea = SEA_LABELS[seaIndex]

    local routes = self:_GetAvailableRoutes(seaIndex, currentPosition, destination)
    local function findBest(position, remainingHops, used, visited)
        local bestCost = distance(position, destination)
        local bestPath = {}
        if remainingHops <= 0 then
            return bestCost, bestPath
        end

        for _, route in ipairs(routes) do
            if not used[route.Name]
                and not repeatsGatewayArea(route.Destination, visited)
            then
                used[route.Name] = true
                table.insert(visited, route.Destination)
                local remainingCost, remainingPath =
                    findBest(route.Destination, remainingHops - 1, used, visited)
                table.remove(visited)
                used[route.Name] = nil
                local routeCost = distance(position, route.Stand) + remainingCost
                if routeCost < bestCost then
                    bestCost = routeCost
                    bestPath = { route }
                    for _, nextRoute in ipairs(remainingPath) do
                        table.insert(bestPath, nextRoute)
                    end
                end
            end
        end
        return bestCost, bestPath
    end

    local directDistance = distance(currentPosition, destination)
    local excluded = {}
    for routeName, isExcluded in pairs(excludedRoutes) do
        if isExcluded then
            excluded[routeName] = true
        end
    end
    local visited = { currentPosition }
    for _, position in ipairs(visitedPositions) do
        if typeof(position) == "Vector3" then
            table.insert(visited, position)
        end
    end
    local plannedCost, plan =
        findBest(currentPosition, MAX_ROUTE_HOPS, excluded, visited)
    diagnostic.DirectDistance = directDistance
    diagnostic.PlannedDistance = plannedCost
    diagnostic.DistanceSaved = directDistance - plannedCost
    diagnostic.MinimumDistanceSaved = MINIMUM_DISTANCE_SAVED
    if #plan == 0 or directDistance - plannedCost < MINIMUM_DISTANCE_SAVED then
        diagnostic.Phase = "direct travel: no qualifying gateway route"
        diagnostic.Reason = self:HasPendingTitleChecks()
                and "Title access is still being checked"
            or #plan == 0
                and "No available route produced a shorter path"
            or "Best gateway route saves less than the required distance"
        return {}, nil
    end
    diagnostic.SelectedRoutes = {}
    for _, route in ipairs(plan) do
        table.insert(diagnostic.SelectedRoutes, route.Name)
        if route.ProvisionalTitleAccess == true
            and not plan[1].PlanTitleAccessRoute
        then
            plan[1].PlanTitleAccessRoute = route
        end
    end
    diagnostic.Phase = "gateway route selected"
    return plan, nil
end

function MapGatewayService:EstimateTravelDistance(destination, currentPosition)
    if typeof(destination) ~= "Vector3" or typeof(currentPosition) ~= "Vector3" then
        return nil, "Travel positions are unavailable"
    end

    local previousDiagnostic = self.LastDiagnostic
    local ok, plan = pcall(
        self.FindPlan,
        self,
        destination,
        currentPosition,
        "route estimate"
    )
    local estimateDiagnostic = self.LastDiagnostic
    self.LastDiagnostic = previousDiagnostic

    if not ok then
        return (destination - currentPosition).Magnitude, tostring(plan)
    end
    local plannedDistance = estimateDiagnostic
        and tonumber(estimateDiagnostic.PlannedDistance)
    local selectedRoutes = estimateDiagnostic and estimateDiagnostic.SelectedRoutes
    if plannedDistance and type(selectedRoutes) == "table" and #selectedRoutes > 0 then
        return plannedDistance
    end
    return (destination - currentPosition).Magnitude
end

function MapGatewayService:RecordTravelPhase(phase, route, details)
    local diagnostic = self.LastDiagnostic
    if not diagnostic then
        return
    end
    diagnostic.Phase = phase
    diagnostic.UpdatedAt = os.clock()
    if route then
        diagnostic.CurrentRoute = route.Name
        diagnostic.Activation = route.Touch and "touch" or "requestEntrance"
        if not diagnostic.LastAttempt or diagnostic.LastAttempt.Route ~= route.Name then
            diagnostic.LastAttempt = {}
        end
        diagnostic.LastAttempt.Route = route.Name
        diagnostic.LastAttempt.Activation = diagnostic.Activation
        diagnostic.LastAttempt.Phase = phase
        diagnostic.LastAttempt.UpdatedAt = os.clock()
    elseif diagnostic.LastAttempt then
        diagnostic.LastAttempt.Phase = phase
        diagnostic.LastAttempt.UpdatedAt = os.clock()
    end
    if type(details) == "table" then
        for key, value in pairs(details) do
            diagnostic[key] = value
            if diagnostic.LastAttempt and key ~= "CurrentPosition" then
                diagnostic.LastAttempt[key] = value
            end
        end
    end
end

function MapGatewayService:MarkFailed(route, reason, cooldown)
    if route and route.Name then
        local now = os.clock()
        local diagnostic = self.LastDiagnostic
        local attempt
        if diagnostic and diagnostic.LastAttempt
            and diagnostic.LastAttempt.Route == route.Name
        then
            attempt = table.clone(diagnostic.LastAttempt)
        end
        self.FailedUntil[route.Name] = now
            + (tonumber(cooldown) or FAILED_ROUTE_COOLDOWN)
        self.LastFailures[route.Name] = {
            At = now,
            Reason = formatScalar(reason or "Gateway attempt failed"),
            Attempt = attempt,
        }
    end
end

function MapGatewayService:MarkApproachFailed(route, reason)
    self:MarkFailed(route, reason, FAILED_APPROACH_COOLDOWN)
end

function MapGatewayService:Use(route, isCurrent)
    local compatibility = self.Compatibility
    local diagnostic = self.LastDiagnostic
    isCurrent = isCurrent or function()
        return true
    end
    if not route or not isCurrent() then
        self:RecordTravelPhase("gateway activation cancelled", route, {
            Failure = "Travel was cancelled",
        })
        return false, "Travel was cancelled"
    end

    local character, _, root = compatibility:GetCharacterParts()
    if not character or not root then
        self:RecordTravelPhase("gateway activation failed", route, {
            Failure = "Character is unavailable",
        })
        return false, "Character is unavailable"
    end

    if typeof(route.Stand) ~= "Vector3" then
        local failure = "Gateway stand position is unavailable"
        self:RecordTravelPhase("gateway stand unavailable", route, {
            Failure = failure,
        })
        return false, failure, "approach"
    end
    local standDistance = distance(root.Position, route.Stand)
    if standDistance > GATEWAY_STAND_ACCEPTANCE then
        local failure = "Character is not close enough to the gateway pad"
        self:RecordTravelPhase("gateway stand not reached", route, {
            DistanceAtStand = standDistance,
            Failure = failure,
        })
        return false, failure, "approach"
    end
    pcall(function()
        if standDistance > GATEWAY_STAND_ALIGNMENT then
            root.CFrame = CFrame.new(route.Stand)
        end
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
    end)

    local activationStartPosition = root.Position
    self:RecordTravelPhase("activating gateway", route, {
        PositionBeforeActivation = root.Position,
        RemoteCallCount = 0,
        RemoteCallStatus = "not started",
        ActivationFailure = nil,
    })
    local remote
    local remoteCallPending = false
    local remoteCallCount = 0
    local lastRemoteCallAt = -math.huge
    local function alignAtStand(currentRoot)
        local offset = distance(currentRoot.Position, route.Stand)
        if offset > GATEWAY_STAND_ALIGNMENT
            and offset <= GATEWAY_ARRIVAL_RADIUS
        then
            currentRoot.CFrame = CFrame.new(route.Stand)
        end
        currentRoot.AssemblyLinearVelocity = Vector3.zero
        currentRoot.AssemblyAngularVelocity = Vector3.zero
    end
    local function invokeEntrance()
        if remoteCallPending or not isCurrent() then
            return
        end
        local currentCharacter, _, currentRoot = compatibility:GetCharacterParts()
        if currentCharacter ~= character or not currentRoot then
            return
        end
        if distance(currentRoot.Position, route.Stand) <= GATEWAY_ARRIVAL_RADIUS then
            pcall(alignAtStand, currentRoot)
        end
        remoteCallPending = true
        remoteCallCount += 1
        lastRemoteCallAt = os.clock()
        if diagnostic and diagnostic.LastAttempt
            and diagnostic.LastAttempt.Route == route.Name
        then
            diagnostic.LastAttempt.RemoteCallCount = remoteCallCount
            diagnostic.LastAttempt.RemoteCallStatus = "in progress"
        end
        task.spawn(function()
            if not isCurrent() then
                remoteCallPending = false
                return
            end
            local ok, result = pcall(function()
                return remote:InvokeServer(
                    "requestEntrance",
                    route.Argument or route.Destination
                )
            end)
            remoteCallPending = false
            if diagnostic and diagnostic.LastAttempt
                and diagnostic.LastAttempt.Route == route.Name
            then
                diagnostic.LastAttempt.RemoteCallStatus = ok
                        and "InvokeServer returned"
                    or "InvokeServer errored"
                diagnostic.LastAttempt.RemoteResultType = type(result)
                if type(result) == "string" or type(result) == "number"
                    or type(result) == "boolean"
                then
                    diagnostic.LastAttempt.RemoteResultSummary = formatScalar(result, 100)
                end
                if ok then
                    diagnostic.LastAttempt.ActivationFailure = nil
                else
                    diagnostic.LastAttempt.ActivationFailure = formatScalar(result)
                end
            end
        end)
    end

    if route.Touch then
        local touchTarget
        local touchResolveError
        local touchLoadAttempts = 0
        local deadline = os.clock() + GATEWAY_TOUCH_LOAD_TIMEOUT
        repeat
            touchLoadAttempts += 1
            touchTarget, touchResolveError = self:_ResolveTouchTarget(route)
            if touchTarget
                or touchResolveError ~= "gateway trigger is not loaded"
                or not isCurrent()
                or os.clock() >= deadline
            then
                break
            end
            task.wait(0.1)
        until false
        if not touchTarget then
            local failure = isCurrent()
                    and (touchResolveError or "gateway trigger did not load at the stand")
                or "Travel was cancelled"
            self:RecordTravelPhase("gateway touch trigger unavailable at stand", route, {
                Failure = failure,
                TouchTriggerStatus = "not loaded",
                TouchTriggerLoadAttempts = touchLoadAttempts,
            })
            return false, failure
        end

        route.TouchTarget = touchTarget
        self:RecordTravelPhase("gateway touch trigger loaded", route, {
            TouchTriggerStatus = "loaded at gateway stand",
            TouchTriggerLoadAttempts = touchLoadAttempts,
        })
        local touchOk, touchError = compatibility:TouchPart(root, touchTarget, isCurrent)
        if diagnostic and diagnostic.LastAttempt then
            diagnostic.LastAttempt.RemoteCallStatus = touchOk
                    and "touch event completed"
                or "touch event failed"
            diagnostic.LastAttempt.TouchTriggerStatus = "loaded at gateway stand"
            diagnostic.LastAttempt.TouchTriggerLoadAttempts = touchLoadAttempts
            if not touchOk then
                diagnostic.LastAttempt.ActivationFailure = touchError
            end
        end
        if not touchOk then
            self:RecordTravelPhase("gateway touch failed", route, {
                Failure = touchError,
            })
            return false, touchError
        end
    else
        local remoteError
        remote, remoteError = compatibility:GetCommF()
        if not remote then
            self:RecordTravelPhase("gateway remote unavailable", route, {
                Failure = remoteError,
                RemoteCallStatus = "not started",
            })
            return false, remoteError
        end
    end

    local deadline = os.clock() + GATEWAY_ACTIVATION_TIMEOUT
    if remote then
        invokeEntrance()
    end
    while isCurrent() and os.clock() < deadline do
        local currentCharacter, _, currentRoot = compatibility:GetCharacterParts()
        if currentCharacter ~= character or not currentRoot then
            self:RecordTravelPhase("character changed during gateway activation", route, {
                PositionAfterActivation = currentRoot and currentRoot.Position or nil,
                Failure = "Character changed during gateway travel",
            })
            return false, "Character changed during gateway travel"
        end
        if diagnostic and diagnostic.LastAttempt
            and diagnostic.LastAttempt.Route == route.Name
        then
            diagnostic.LastAttempt.PositionAfterActivation = currentRoot.Position
            diagnostic.LastAttempt.DistanceAfterActivation =
                distance(currentRoot.Position, route.Destination)
            diagnostic.LastAttempt.ActivationDisplacement = distance(
                activationStartPosition,
                currentRoot.Position
            )
            diagnostic.LastAttempt.Displacement = distance(
                diagnostic.LastAttempt.PositionBeforeActivation or root.Position,
                currentRoot.Position
            )
        end
        local destinationDistance = distance(currentRoot.Position, route.Destination)
        local activationDisplacement = distance(
            activationStartPosition,
            currentRoot.Position
        )
        if destinationDistance <= GATEWAY_ARRIVAL_RADIUS
            and activationDisplacement >= 200
        then
            self.FailedUntil[route.Name] = nil
            self.LastFailures[route.Name] = nil
            self:RecordTravelPhase("gateway arrival confirmed", route, {
                PositionAfterActivation = currentRoot.Position,
                DistanceAfterActivation = destinationDistance,
                ActivationDisplacement = activationDisplacement,
            })
            return true
        end
        if remote and distance(currentRoot.Position, route.Stand) <= GATEWAY_ARRIVAL_RADIUS then
            pcall(alignAtStand, currentRoot)
        end
        if remote and not remoteCallPending
            and os.clock() - lastRemoteCallAt >= REMOTE_RETRY_INTERVAL
        then
            invokeEntrance()
        end
        task.wait(0.1)
    end
    if not isCurrent() then
        self:RecordTravelPhase("gateway activation cancelled", route, {
            Failure = "Travel was cancelled",
        })
        return false, "Travel was cancelled"
    end
    local _, _, finalRoot = compatibility:GetCharacterParts()
    self:RecordTravelPhase("arrival was not confirmed before timeout", route, {
        PositionAfterActivation = finalRoot and finalRoot.Position or nil,
        DistanceAfterActivation = finalRoot
                and distance(finalRoot.Position, route.Destination)
            or nil,
        Failure = "Gateway did not confirm arrival within "
            .. tostring(GATEWAY_ACTIVATION_TIMEOUT)
            .. " seconds",
    })
    return false, "Gateway did not confirm arrival"
end

function MapGatewayService:BuildDiagnosticReport()
    local diagnostic = self.LastDiagnostic
    if type(diagnostic) ~= "table" then
        return nil
    end

    local age = math.max(0, os.clock() - (diagnostic.At or os.clock()))
    if age > 600 then
        return nil
    end
    local lines = {
        "===== [GatewayDiagnostic] REPORT BEGIN =====",
        "Age: " .. string.format("%.2f", age) .. " seconds",
        "Sea: " .. tostring(diagnostic.Sea or "unknown"),
        "Destination: " .. tostring(diagnostic.DestinationLabel or "unknown")
            .. " at " .. formatPosition(diagnostic.Destination),
        "Phase: " .. tostring(diagnostic.Phase or "unknown"),
    }
    if diagnostic.CurrentPosition then
        table.insert(lines, "Start position: " .. formatPosition(diagnostic.CurrentPosition))
    end
    if type(diagnostic.DirectDistance) == "number" then
        table.insert(
            lines,
            "Route distances: direct="
                .. string.format("%.1f", diagnostic.DirectDistance)
                .. "; planned="
                .. string.format("%.1f", diagnostic.PlannedDistance or 0)
                .. "; saved="
                .. string.format("%.1f", diagnostic.DistanceSaved or 0)
                .. "; minimum="
                .. tostring(diagnostic.MinimumDistanceSaved or MINIMUM_DISTANCE_SAVED)
        )
    end
    if diagnostic.Reason then
        table.insert(lines, "Planner reason: " .. formatScalar(diagnostic.Reason))
    end
    if type(diagnostic.SelectedRoutes) == "table" then
        table.insert(
            lines,
            "Selected route(s): "
                .. (#diagnostic.SelectedRoutes > 0
                    and table.concat(diagnostic.SelectedRoutes, " -> ")
                    or "none")
        )
    end

    for _, candidate in ipairs(diagnostic.Candidates or {}) do
        table.insert(
            lines,
            "Candidate "
                .. tostring(candidate.Name)
                .. ": eligible="
                .. tostring(candidate.Eligible)
        .. "; activation="
        .. tostring(candidate.Activation)
                .. "; requirement="
                .. tostring(candidate.Requirement or "none")
                .. "; owned="
                .. (candidate.RequirementOwned == nil
                    and "n/a"
                    or tostring(candidate.RequirementOwned))
                .. (candidate.ItemRequirementOwned ~= nil
                    and ("; item_owned=" .. tostring(candidate.ItemRequirementOwned))
                    or "")
                .. (candidate.FallbackTitle
                    and ("; fallback_title=" .. tostring(candidate.FallbackTitle))
                    or "")
                .. (candidate.TitleCheckPending and "; title_pending=true" or "")
                .. (candidate.FallbackTitle
                    and (
                        "; title_owned="
                            .. (candidate.TitleRequirementOwned == nil
                                and "unknown"
                                or tostring(candidate.TitleRequirementOwned))
                    )
                    or "")
                .. (candidate.ConfirmedNoAccessCached
                    and "; no_access_cached=true"
                    or "")
                .. (type(candidate.NoAccessCacheRemaining) == "number"
                    and ("; no_access_cache_remaining="
                        .. string.format("%.1f", candidate.NoAccessCacheRemaining))
                    or "")
                .. (candidate.AccessBy and ("; access_by=" .. tostring(candidate.AccessBy)) or "")
                .. (candidate.TouchTriggerLoaded ~= nil
                    and ("; trigger_loaded=" .. tostring(candidate.TouchTriggerLoaded))
                    or "")
                .. "; reason="
                .. formatScalar(candidate.Reason or "available")
                .. (type(candidate.StandDistance) == "number"
                    and ("; start_to_pad=" .. string.format("%.1f", candidate.StandDistance))
                    or "")
                .. (type(candidate.TitleRouteSavings) == "number"
                    and ("; title_route_saved="
                        .. string.format("%.1f", candidate.TitleRouteSavings))
                    or "")
                .. (type(candidate.CooldownRemaining) == "number"
                    and ("; cooldown=" .. string.format("%.1f", candidate.CooldownRemaining))
                    or "")
                .. (candidate.PreviousFailure
                    and ("; last_failure=" .. formatScalar(candidate.PreviousFailure))
                    or "")
                .. (candidate.PreviousFailurePhase
                    and ("; last_failure_phase="
                        .. formatScalar(candidate.PreviousFailurePhase))
                    or "")
                .. (candidate.PreviousFailureCallStatus
                    and ("; last_call_status="
                        .. formatScalar(candidate.PreviousFailureCallStatus))
                    or "")
                .. (candidate.PreviousFailureDetail
                    and ("; last_attempt_failure="
                        .. formatScalar(candidate.PreviousFailureDetail))
                    or "")
                .. (candidate.PreviousFailureActivationFailure
                    and ("; last_activation_error="
                        .. formatScalar(candidate.PreviousFailureActivationFailure))
                    or "")
                .. (type(candidate.PreviousFailureDisplacement) == "number"
                    and ("; last_displacement="
                        .. string.format("%.1f", candidate.PreviousFailureDisplacement))
                    or "")
                .. (type(candidate.PreviousFailureAge) == "number"
                    and ("; last_failure_age="
                        .. string.format("%.1f", candidate.PreviousFailureAge))
                    or "")
        )
    end

    local attempt = diagnostic.LastAttempt
    if attempt then
        table.insert(
            lines,
            "Last attempt: route="
                .. tostring(attempt.Route)
                .. "; type="
                .. tostring(attempt.Activation)
                .. "; phase="
                .. tostring(attempt.Phase)
                .. "; call_count="
                .. tostring(attempt.RemoteCallCount or 0)
                .. "; call_status="
                .. tostring(attempt.RemoteCallStatus or "n/a")
                .. (attempt.TouchTriggerStatus
                    and ("; touch_trigger=" .. tostring(attempt.TouchTriggerStatus))
                    or "")
                .. (type(attempt.TouchTriggerLoadAttempts) == "number"
                    and ("; touch_load_attempts=" .. tostring(attempt.TouchTriggerLoadAttempts))
                    or "")
        )
        if attempt.RemoteResultType then
            table.insert(
                lines,
                "Remote result: type="
                    .. tostring(attempt.RemoteResultType)
                    .. "; summary="
                    .. tostring(attempt.RemoteResultSummary or "<not scalar>")
            )
        end
        if attempt.PositionBeforeApproach or attempt.PositionAfterApproach
            or type(attempt.DistanceToStand) == "number"
            or type(attempt.DistanceAtStand) == "number"
        then
            table.insert(
                lines,
                "Approach positions: before="
                    .. formatPosition(attempt.PositionBeforeApproach)
                    .. "; after="
                    .. formatPosition(attempt.PositionAfterApproach)
                    .. "; start_to_pad="
                    .. (type(attempt.DistanceToStand) == "number"
                        and string.format("%.1f", attempt.DistanceToStand)
                        or "n/a")
                    .. "; at_pad_distance="
                    .. (type(attempt.DistanceAtStand) == "number"
                        and string.format("%.1f", attempt.DistanceAtStand)
                        or "n/a")
                    .. "; before_alignment="
                    .. (type(attempt.DistanceBeforeAlignment) == "number"
                        and string.format("%.1f", attempt.DistanceBeforeAlignment)
                        or "n/a")
            )
        end
        if attempt.PositionBeforeActivation then
            table.insert(
                lines,
                "Activation positions: before="
                    .. formatPosition(attempt.PositionBeforeActivation)
                    .. "; after="
                    .. formatPosition(attempt.PositionAfterActivation)
                    .. "; distance_after="
                    .. (type(attempt.DistanceAfterActivation) == "number"
                        and string.format("%.1f", attempt.DistanceAfterActivation)
                        or "n/a")
                    .. "; displacement="
                    .. (type(attempt.Displacement) == "number"
                        and string.format("%.1f", attempt.Displacement)
                        or "n/a")
                    .. "; activation_displacement="
                    .. (type(attempt.ActivationDisplacement) == "number"
                        and string.format("%.1f", attempt.ActivationDisplacement)
                        or "n/a")
            )
        end
        if attempt.Failure then
            table.insert(lines, "Attempt failure: " .. formatScalar(attempt.Failure))
        end
    end

    if diagnostic.Failure then
        table.insert(lines, "Travel note: " .. formatScalar(diagnostic.Failure))
    end
    table.insert(lines, "===== [GatewayDiagnostic] REPORT END =====")
    return table.concat(lines, "\n")
end

return MapGatewayService
-- END SOURCE: src/ReplicatedStorage/CustomHub/Features/MapGatewayService.lua
end

__bundleFactories["CustomHub.Features.TeleportFeature"] = function()
-- BEGIN SOURCE: src/ReplicatedStorage/CustomHub/Features/TeleportFeature.lua
local MapGatewayService = __bundleLoad("CustomHub.Features.MapGatewayService")

local TeleportFeature = {
    Context = nil,
    MovementService = nil,
    GatewayService = nil,
    ActiveTravel = nil,
    ActiveFarmTravel = nil,
    Generation = 0,
    FarmTravelGeneration = 0,
    LastFarmGatewayPlanCheck = nil,
    CharacterRemovingConnection = nil,
}

local MAX_STALL_RETRIES = 2
local STALL_RETRY_DELAY = 1.1
local MAX_TRAVEL_TIMEOUT = 150
local MAX_GATEWAY_ATTEMPTS = 4
local TITLE_ACCESS_RECHECK_WINDOW = 6
local NPC_DIAGNOSTIC_TARGETS = {
    { Label = "Titles Specialist", Names = { "Titles Specialist" } },
    { Label = "Awakenings Expert", Names = { "Awakenings Expert", "Awakening Expert" } },
    { Label = "Blox Fruits Gacha", Names = { "Blox Fruit Gacha", "Blox Fruits Gacha" } },
}

local function disconnect(connection)
    if connection then
        pcall(function()
            connection:Disconnect()
        end)
    end
end

local function currentSeaIndex(compatibility)
    local checks = {
        { Index = 1, Method = "IsFirstSea" },
        { Index = 2, Method = "IsSecondSea" },
        { Index = 3, Method = "IsThirdSea" },
    }
    local found
    local count = 0
    for _, sea in ipairs(checks) do
        local check = compatibility and compatibility[sea.Method]
        if type(check) == "function" then
            local ok, result = pcall(check, compatibility)
            if ok and result == true then
                found = sea.Index
                count += 1
            end
        end
    end
    return count == 1 and found or nil
end

function TeleportFeature:_SetStatus(message, kind, playerMessage)
    if self.Context and self.Context.State then
        self.Context.State:SetStatus(message, kind or "info", playerMessage)
    end
end

function TeleportFeature:_SetFeatureEnabled(actionId, enabled)
    local state = self.Context and self.Context.State
    if state and actionId then
        state:SetFeatureEnabled(actionId, enabled)
    end
end

function TeleportFeature:IsTraveling()
    return self.ActiveTravel ~= nil
end

function TeleportFeature:_GetSelectedIsland()
    local compatibility = self.Context and self.Context.Compatibility
    local config = self.Context and self.Context.Config
    local seaIndex = currentSeaIndex(compatibility)
    if not seaIndex then
        return nil, "Could not identify the current sea"
    end

    local selected = config and config.TravelSettings and config.TravelSettings.Island
    if type(selected) ~= "string" then
        return nil, "Select an island first"
    end
    for _, destination in ipairs((config.TravelDestinations or {})[seaIndex] or {}) do
        if destination.Name == selected then
            return destination
        end
    end
    return nil, "That island is unavailable in this sea"
end

function TeleportFeature:_FindNpcRoot(name)
    local compatibility = self.Context and self.Context.Compatibility
    local workspace = compatibility and compatibility.Workspace
    local replicatedStorage = compatibility and compatibility.ReplicatedStorage
    local sources = {
        {
            Folder = workspace and workspace:FindFirstChild("NPCs"),
            IsLive = true,
            Priority = 0,
        },
        {
            Folder = replicatedStorage and replicatedStorage:FindFirstChild("NPCs"),
            IsLive = false,
            Priority = 1,
        },
    }

    local _, _, playerRoot = compatibility:GetCharacterParts()
    local selectedRoot
    local selectedPriority = math.huge
    local nearestDistance = math.huge
    for _, source in ipairs(sources) do
        for _, npc in ipairs(source.Folder and source.Folder:GetChildren() or {}) do
            if npc:IsA("Model") and npc.Name == name then
                local root = npc:FindFirstChild("HumanoidRootPart") or npc.PrimaryPart
                local humanoid = source.IsLive and npc:FindFirstChildOfClass("Humanoid")
                local templateInSea = source.IsLive
                    or self.Context.Config.IsTravelNpcPositionInCurrentSea(
                        compatibility,
                        root and root.Position
                    )
                if root and root:IsA("BasePart")
                    and (not humanoid or humanoid.Health > 0)
                    and templateInSea
                then
                    local distance = playerRoot and (root.Position - playerRoot.Position).Magnitude or 0
                    if source.Priority < selectedPriority
                        or source.Priority == selectedPriority and distance < nearestDistance
                    then
                        selectedRoot = root
                        selectedPriority = source.Priority
                        nearestDistance = distance
                    end
                end
            end
        end
    end
    if not selectedRoot and type(compatibility.GetNpcModelsByName) == "function" then
        local models = compatibility:GetNpcModelsByName(name)
        for _, npc in ipairs(type(models) == "table" and models or {}) do
            local root = npc:FindFirstChild("HumanoidRootPart") or npc.PrimaryPart
            local humanoid = npc:IsDescendantOf(workspace)
                and npc:FindFirstChildOfClass("Humanoid")
            local safePosition = root
                and root:IsA("BasePart")
                and self.Context.Config.IsTravelNpcPositionInCurrentSea(
                    compatibility,
                    root.Position
                )
            if safePosition and (not humanoid or humanoid.Health > 0) then
                local distance = playerRoot and (root.Position - playerRoot.Position).Magnitude or 0
                if distance < nearestDistance then
                    selectedRoot = root
                    nearestDistance = distance
                end
            end
        end
    end
    if not selectedRoot then
        return nil, "The selected NPC has no usable live or template position"
    end
    return selectedRoot
end

function TeleportFeature:_GetNpcDestination()
    local compatibility = self.Context and self.Context.Compatibility
    if not currentSeaIndex(compatibility) then
        return nil, "Could not identify the current sea"
    end
    local selected = self.Context.Config.TravelSettings.Npc
    if type(selected) ~= "string" then
        return nil, "Select an NPC first"
    end
    local root, rootError = self:_FindNpcRoot(selected)
    if not root then
        return nil, rootError
    end
    return root.CFrame * CFrame.new(0, 0, -4)
end

function TeleportFeature:_ResolveIslandCFrame(destination)
    if destination.Position then
        if destination.ExactPosition == true then
            return CFrame.new(destination.Position)
        end
        return CFrame.new(destination.Position + Vector3.new(0, 18, 0))
    end
    if destination.LocationName then
        local workspace = self.Context.Compatibility.Workspace
        local worldOrigin = workspace:FindFirstChild("_WorldOrigin")
        local locations = worldOrigin and worldOrigin:FindFirstChild("Locations")
        local location = locations and locations:FindFirstChild(destination.LocationName)
        if location and location:IsA("BasePart") then
            return location.CFrame + Vector3.new(0, 18, 0)
        elseif location and location:IsA("Model") then
            return location:GetPivot() + Vector3.new(0, 18, 0)
        end
        return nil, "The selected location is not currently available"
    end
    return nil, "The selected island has no usable destination"
end

function TeleportFeature:_IsTravelCurrent(request, character)
    local context = self.Context
    local compatibility = context and context.Compatibility
    local mainFarm = context and context.MainFarm
    if request.IsFarmTask == true then
        local isCurrentOk, taskIsCurrent = pcall(request.IsCurrent)
        return self.ActiveFarmTravel == request
            and self.FarmTravelGeneration == request.Generation
            and compatibility
            and compatibility.Player
            and compatibility.Player.Character == character
            and mainFarm
            and mainFarm.Running
            and isCurrentOk
            and taskIsCurrent == true
    end
    return self.ActiveTravel == request
        and self.Generation == request.Generation
        and compatibility
        and compatibility.Player
        and compatibility.Player.Character == character
        and not (mainFarm and mainFarm.Running)
end

function TeleportFeature:_StopMovementSession()
    local movement = self.MovementService
    if movement and type(movement._StopMovement) == "function" then
        movement:_StopMovement()
    end
end

function TeleportFeature:_MoveAndWait(request, character, destination, shouldAbort)
    local compatibility = self.Context.Compatibility
    local _, _, startRoot = compatibility:GetCharacterParts()
    if not startRoot then
        return false, "Character is unavailable"
    end

    local lastStallAt = self.MovementService.LastStallAt
    local routeRequestsBefore = table.clone(self.MovementService.LastRouteRequest or {})
    local startDistance = (destination.Position - startRoot.Position).Magnitude
    local function startMovement()
        return pcall(function()
            return self.MovementService:MoveTo(destination, {
                Speed = 190,
                Threshold = 8,
                IsCurrent = function()
                    return self:_IsTravelCurrent(request, character)
                end,
            })
        end)
    end
    local moveCallOk, moved, moveResult = startMovement()
    if not moveCallOk then
        self:_StopMovementSession()
        return false, tostring(moved)
    end
    if not moved then
        return false, tostring(moveResult)
    end
    if moveResult == "arrived" then
        return true
    end

    local deadline = os.clock()
        + math.max(20, math.min(MAX_TRAVEL_TIMEOUT, startDistance / 120 + 15))
    local stallRetries = 0
    while self:_IsTravelCurrent(request, character) do
        if not self:_IsTravelCurrent(request, character) then
            return false, "Travel was interrupted"
        end
        if type(shouldAbort) == "function" then
            local abortCheckOk, shouldStop, abortReason = pcall(shouldAbort)
            if abortCheckOk and shouldStop == true then
                self:_StopMovementSession()
                return false,
                    tostring(abortReason or "Route access could not be confirmed"),
                    "title_access"
            end
        end
        local currentCharacter, _, currentRoot = compatibility:GetCharacterParts()
        if currentCharacter ~= character or not currentRoot then
            return false, "Character changed during travel"
        end
        local remaining = (destination.Position - currentRoot.Position).Magnitude
        if not self.MovementService.Active then
            if remaining <= 14 then
                return true
            end
            if self.MovementService.LastStallAt ~= lastStallAt then
                stallRetries += 1
                if stallRetries > MAX_STALL_RETRIES then
                    return false,
                        "Movement stalled after "
                            .. tostring(MAX_STALL_RETRIES)
                            .. " waypoint recovery attempts"
                end

                lastStallAt = self.MovementService.LastStallAt
                self:_SetStatus(
                    "Movement stalled; retrying the same waypoint ("
                        .. tostring(stallRetries)
                        .. "/"
                        .. tostring(MAX_STALL_RETRIES)
                        .. ").",
                    "warning"
                )
                task.wait(STALL_RETRY_DELAY)
                if not self:_IsTravelCurrent(request, character) then
                    return false, "Travel was interrupted"
                end

                local retryCallOk, retryMoved, retryResult = startMovement()
                if not retryCallOk then
                    self:_StopMovementSession()
                    return false, tostring(retryMoved)
                end
                if not retryMoved then
                    return false, tostring(retryResult)
                end
                if retryResult == "arrived" then
                    return true
                end
                continue
            end

            local routeTransitionStarted = false
            for routeName, requestedAt in pairs(self.MovementService.LastRouteRequest or {}) do
                if requestedAt > (routeRequestsBefore[routeName] or 0) then
                    routeTransitionStarted = true
                    break
                end
            end
            if routeTransitionStarted then
                local transitionDeadline = os.clock() + 8
                while self:_IsTravelCurrent(request, character)
                    and os.clock() < transitionDeadline
                do
                    local transitionCharacter, _, transitionRoot =
                        compatibility:GetCharacterParts()
                    if transitionCharacter ~= character or not transitionRoot then
                        return false, "Character changed during map transition"
                    end
                    if (destination.Position - transitionRoot.Position).Magnitude <= 14 then
                        return true
                    end
                    if (transitionRoot.Position - startRoot.Position).Magnitude >= 200 then
                        return false, "Map transition completed; continue toward the destination"
                    end
                    task.wait(0.1)
                end
                if not self:_IsTravelCurrent(request, character) then
                    return false, "Travel was interrupted"
                end
                return false, "Map transition did not reach the destination"
            end
            self:_StopMovementSession()
            return false, "Movement stopped before reaching the waypoint"
        end
        if os.clock() >= deadline then
            self:_StopMovementSession()
            return false, "Movement timed out before reaching the waypoint"
        end
        task.wait(0.1)
    end
    return false, "Travel was cancelled"
end

function TeleportFeature:_RunDirectTravel(request, character, waitBeforeRetry, destination, finishRequestOnArrival)
    destination = destination or request.Destination
    local retries = 0
    while self:_IsTravelCurrent(request, character) do
        if waitBeforeRetry or retries > 0 then
            task.wait(STALL_RETRY_DELAY)
            waitBeforeRetry = false
            if not self:_IsTravelCurrent(request, character) then
                return false, "Travel was interrupted"
            end
        end

        local arrived, reason = self:_MoveAndWait(request, character, destination)
        if arrived then
            if self.GatewayService then
                self.GatewayService:RecordTravelPhase(
                    finishRequestOnArrival == false
                        and "special transport staging reached"
                        or "destination reached"
                )
            end
            if finishRequestOnArrival ~= false then
                self:_FinishTravel(request, "Arrived at " .. request.Label .. ".", "success")
            end
            return true
        end
        if not self:_IsTravelCurrent(request, character) then
            return false, reason
        end

        if reason == "Map transition completed; continue toward the destination" then
            request.RouteTransitionRetries = (request.RouteTransitionRetries or 0) + 1
            if request.RouteTransitionRetries > 2 then
                if finishRequestOnArrival == false then
                    return false, "Map gateway transitions did not reach staging"
                end
                self:_FinishTravel(
                    request,
                    "Map gateway transitions did not reach the selected destination.",
                    "warning"
                )
                return false, reason
            end
            self:_SetStatus(
                "Map transition complete; continuing to " .. request.Label .. ".",
                "info"
            )
        else
            retries += 1
            request.StallRetries = retries
            if retries > MAX_STALL_RETRIES then
                if self.GatewayService then
                    self.GatewayService:RecordTravelPhase(
                        "normal travel stopped after gateway fallback",
                        nil,
                        { Failure = reason }
                    )
                end
                if finishRequestOnArrival == false then
                    return false, reason
                end
                self:_FinishTravel(
                    request,
                    "Travel stalled after "
                        .. tostring(MAX_STALL_RETRIES)
                        .. " retries; copy the status report for movement details, then try again.",
                    "warning"
                )
                return false, reason
            end
            self:_SetStatus(
                "Travel stalled; retrying ("
                    .. tostring(retries)
                    .. "/"
                    .. tostring(MAX_STALL_RETRIES)
                    .. ").",
                "warning"
            )
        end
    end
    return false, "Travel was cancelled"
end

function TeleportFeature:_RequestSpecialTransport(request, character, route)
    if not self:_IsTravelCurrent(request, character) then
        return false, "Travel was interrupted"
    end

    local compatibility = self.Context.Compatibility
    local requestOk, requestError = self.MovementService:RequestSpecialTravelRoute(
        route,
        function()
            return self:_IsTravelCurrent(request, character)
        end
    )
    if not requestOk then
        return false, requestError or "Submarine Worker transport could not start"
    end

    local arrivalReference = route and route.ArrivalReference
    local arrivalRadius = tonumber(route and route.ArrivalRadius) or 3000
    local arrivalName = route and route.Name == "Tiki" and "Tiki Outpost" or "Submerged"
    if typeof(arrivalReference) ~= "Vector3" then
        return false, arrivalName .. " arrival reference is unavailable"
    end

    local deadline = os.clock() + 10
    repeat
        if not self:_IsTravelCurrent(request, character) then
            return false, "Travel was interrupted"
        end
        local currentCharacter, _, currentRoot = compatibility:GetCharacterParts()
        if currentCharacter ~= character or not currentRoot then
            return false, "Character changed during Submerged transport"
        end
        if (currentRoot.Position - arrivalReference).Magnitude <= arrivalRadius then
            return true
        end
        task.wait(0.1)
    until os.clock() >= deadline
    return false, arrivalName .. " transport did not confirm arrival"
end

function TeleportFeature:_ApproachGatewayStand(request, character, route)
    local compatibility = self.Context.Compatibility
    local _, _, approachRoot = compatibility:GetCharacterParts()
    self.GatewayService:RecordTravelPhase("approaching gateway stand", route, {
        PositionBeforeApproach = approachRoot and approachRoot.Position or nil,
        DistanceToStand = approachRoot
                and (approachRoot.Position - route.Stand).Magnitude
            or nil,
    })
    self:_SetStatus("Travelling to map gateway: " .. route.Name .. ".", "info")

    local abortIfTitleUnknown
    if route.ProvisionalTitleAccess == true or route.PlanTitleAccessRoute then
        abortIfTitleUnknown = function()
            return self.GatewayService:ShouldAbortForUnconfirmedTitle(route)
        end
    end
    local reached, movementError, movementStage = self:_MoveAndWait(
        request,
        character,
        CFrame.new(route.Stand),
        abortIfTitleUnknown
    )
    if not reached then
        if movementStage == "title_access" then
            return false, movementError, "title_access"
        end
        if not self:_IsTravelCurrent(request, character) then
            return false, movementError
        end
        self.GatewayService:MarkApproachFailed(route, movementError)
        local _, _, failedRoot = compatibility:GetCharacterParts()
        self.GatewayService:RecordTravelPhase(
            "could not reach gateway stand; trying another gateway",
            route,
            {
                PositionAfterApproach = failedRoot and failedRoot.Position or nil,
                Failure = movementError,
            }
        )
        self:_SetStatus(
            "Could not reach " .. route.Name .. "; checking another route.",
            "warning"
        )
        return false, movementError
    end

    self:_StopMovementSession()
    local _, _, gatewayRoot = compatibility:GetCharacterParts()
    local standDistance = gatewayRoot
            and (gatewayRoot.Position - route.Stand).Magnitude
        or math.huge
    if not gatewayRoot or standDistance > 25 then
        local standError = "Could not reach the gateway pad closely enough"
        self.GatewayService:MarkApproachFailed(route, standError)
        self.GatewayService:RecordTravelPhase(
            "gateway stand not reached; checking another gateway",
            route,
            {
                PositionAtStand = gatewayRoot and gatewayRoot.Position or nil,
                DistanceAtStand = standDistance,
                Failure = standError,
            }
        )
        self:_SetStatus(
            route.Name .. " pad was not reached; checking another route.",
            "warning"
        )
        return false, standError
    end

    local positionBeforeAlignment = gatewayRoot.Position
    local aligned, alignmentError = pcall(function()
        gatewayRoot.CFrame = CFrame.new(route.Stand)
        gatewayRoot.AssemblyLinearVelocity = Vector3.zero
        gatewayRoot.AssemblyAngularVelocity = Vector3.zero
    end)
    if not aligned then
        local standError = "Could not align at the gateway pad: "
            .. tostring(alignmentError)
        self.GatewayService:MarkApproachFailed(route, standError)
        self.GatewayService:RecordTravelPhase(
            "gateway stand alignment failed; checking another gateway",
            route,
            {
                PositionAtStand = positionBeforeAlignment,
                DistanceAtStand = standDistance,
                Failure = standError,
            }
        )
        self:_SetStatus(
            route.Name .. " pad alignment failed; checking another route.",
            "warning"
        )
        return false, standError
    end

    self.GatewayService:RecordTravelPhase("at gateway stand; activating", route, {
        PositionAtStand = positionBeforeAlignment,
        DistanceAtStand = (gatewayRoot.Position - route.Stand).Magnitude,
        PositionBeforeAlignment = positionBeforeAlignment,
        DistanceBeforeAlignment = standDistance,
    })
    return true
end

function TeleportFeature:_RunTravel(request, character)
    local compatibility = self.Context.Compatibility
    local gatewayDestination = request.GatewayDestination or request.Destination
    local attemptedRoutes = {}
    local visitedGatewayPositions = {}
    local gatewayAttempts = 0
    local gatewayFailed = false

    local function findPlanFromCurrentPosition()
        if not self.GatewayService then
            return {}
        end
        local _, _, currentRoot = compatibility:GetCharacterParts()
        if not currentRoot then
            return {}
        end

        if not request.RoutePlanConsumed
            and type(request.RoutePlan) == "table"
            and #request.RoutePlan > 0
            and typeof(request.RoutePlanDestination) == "Vector3"
            and typeof(request.RouteStartPosition) == "Vector3"
            and (request.RoutePlanDestination - gatewayDestination.Position).Magnitude <= 200
            and (request.RouteStartPosition - currentRoot.Position).Magnitude <= 200
        then
            request.RoutePlanConsumed = true
            return request.RoutePlan
        end
        request.RoutePlanConsumed = true

        local planOk, resolvedPlan = pcall(
            self.GatewayService.FindPlan,
            self.GatewayService,
            gatewayDestination.Position,
            currentRoot.Position,
            request.GatewayPlanLabel or request.Label,
            attemptedRoutes,
            visitedGatewayPositions
        )
        if not planOk or type(resolvedPlan) ~= "table" then
            self.GatewayService:RecordTravelPhase(
                "gateway planning failed; using normal travel",
                nil,
                { Failure = resolvedPlan }
            )
            return {}
        end

        if #resolvedPlan == 0
            and self.GatewayService:HasPendingTitleChecks()
        then
            local deadline = os.clock() + TITLE_ACCESS_RECHECK_WINDOW
            while os.clock() < deadline do
                task.wait(0.1)
                if not self:_IsTravelCurrent(request, character) then
                    return {}
                end
                local _, _, retryRoot = compatibility:GetCharacterParts()
                if not retryRoot then
                    break
                end
                planOk, resolvedPlan = pcall(
                    self.GatewayService.FindPlan,
                    self.GatewayService,
                    gatewayDestination.Position,
                    retryRoot.Position,
                    request.GatewayPlanLabel or request.Label,
                    attemptedRoutes,
                    visitedGatewayPositions
                )
                if not planOk or type(resolvedPlan) ~= "table"
                    or #resolvedPlan > 0
                    or not self.GatewayService:HasPendingTitleChecks()
                then
                    break
                end
            end
            if not planOk or type(resolvedPlan) ~= "table" then
                return {}
            end
        end
        return resolvedPlan
    end

    if request.SpecialTravelRoute
        and request.SpecialTravelRoute.Name == "Tiki"
    then
        local route = request.SpecialTravelRoute
        local stagingReached, stagingError = self:_RunDirectTravel(
            request,
            character,
            false,
            route.Stage,
            false
        )
        if not stagingReached then
            if self:_IsTravelCurrent(request, character) then
                self:_FinishTravel(
                    request,
                    "Could not reach Submerged exit staging: " .. tostring(stagingError),
                    "warning"
                )
            end
            return
        end

        self:_SetStatus("Leaving Submerged for Tiki Outpost.", "info")
        self.GatewayService:RecordTravelPhase(
            "at Submerged exit staging; requesting Tiki transport"
        )
        local transported, transportError =
            self:_RequestSpecialTransport(request, character, route)
        if not transported then
            if self:_IsTravelCurrent(request, character) then
                self:_FinishTravel(
                    request,
                    "Could not leave Submerged: " .. tostring(transportError),
                    "warning"
                )
            end
            return
        end

        self.GatewayService:RecordTravelPhase(
            "Tiki arrival confirmed; planning gateway route"
        )
        self:_SetStatus("At Tiki Outpost; planning the next route.", "info")
        request.SpecialTravelRoute = nil
        request.GatewayDestination = request.Destination
        request.GatewayPlanLabel = request.Label
        request.RoutePlan = nil
        request.RoutePlanConsumed = true
        gatewayDestination = request.Destination
    end

    -- Take one leg at a time. A second leg planned before teleporting can be
    -- stale by the time the first transition finishes or fails.
    while gatewayAttempts < MAX_GATEWAY_ATTEMPTS do
        if not self:_IsTravelCurrent(request, character) then
            return
        end
        local plan = findPlanFromCurrentPosition()
        local route = plan[1]
        if not route then
            break
        end
        if attemptedRoutes[route.Name] then
            break
        end
        attemptedRoutes[route.Name] = true
        gatewayAttempts += 1

        self:_SetStatus("Using map gateway: " .. route.Name .. ".", "info")
        local reached, approachError, approachStage =
            self:_ApproachGatewayStand(request, character, route)
        if not reached then
            if not self:_IsTravelCurrent(request, character) then
                return
            end
            if approachStage == "title_access" then
                self.GatewayService:RecordTravelPhase(
                    "Tiki title access was not confirmed; using normal travel",
                    route,
                    { Failure = approachError }
                )
                self:_SetStatus(
                    "Tiki access could not be confirmed; continuing without that gateway.",
                    "info"
                )
                request.RoutePlan = nil
                continue
            end
            gatewayFailed = true
            request.RoutePlan = nil
            continue
        end

        local titleAccessOk, titleAccessError =
            self.GatewayService:WaitForTitleAccess(
                route,
                TITLE_ACCESS_RECHECK_WINDOW,
                function()
                    return self:_IsTravelCurrent(request, character)
                end
            )
        if not titleAccessOk then
            if not self:_IsTravelCurrent(request, character) then
                return
            end
            self.GatewayService:RecordTravelPhase(
                "Tiki title access was not confirmed; using normal travel",
                route,
                { Failure = titleAccessError }
            )
            self:_SetStatus(
                "Tiki access could not be confirmed; continuing without that gateway.",
                "info"
            )
            request.RoutePlan = nil
            continue
        end

        self:_SetStatus("Activating map gateway: " .. route.Name .. ".", "info")
        local used, gatewayError, failureStage = self.GatewayService:Use(route, function()
            return self:_IsTravelCurrent(request, character)
        end)
        if not used then
            if not self:_IsTravelCurrent(request, character) then
                return
            end
            if failureStage == "approach" then
                self.GatewayService:MarkApproachFailed(route, gatewayError)
                self.GatewayService:RecordTravelPhase(
                    "gateway stand not reached; checking another gateway",
                    route,
                    { Failure = gatewayError }
                )
                self:_SetStatus(
                    route.Name .. " pad was not reached; checking another route.",
                    "warning"
                )
            else
                self.GatewayService:MarkFailed(route, gatewayError)
                self.GatewayService:RecordTravelPhase(
                    "gateway activation failed; trying another gateway",
                    route,
                    { Failure = gatewayError }
                )
                self:_SetStatus(
                    route.Name .. " did not confirm arrival; checking another route.",
                    "warning"
                )
            end
            gatewayFailed = true
            if gatewayError then
                request.LastGatewayError = tostring(gatewayError)
            end
            request.RoutePlan = nil
            continue
        end
        request.RoutePlan = nil
        self.GatewayService:RecordTravelPhase(
            "gateway arrival confirmed; continuing to destination",
            route
        )
        self:_SetStatus(
            route.Name .. " arrival confirmed; checking the next leg.",
            "info"
        )
        table.insert(visitedGatewayPositions, route.Destination)
    end

    if self:_IsTravelCurrent(request, character) then
        if gatewayAttempts >= MAX_GATEWAY_ATTEMPTS then
            self.GatewayService:RecordTravelPhase(
                "gateway attempt limit reached; continuing by normal travel",
                nil,
                { GatewayAttempts = gatewayAttempts }
            )
        elseif gatewayFailed then
            self.GatewayService:RecordTravelPhase(
                "no more usable gateway routes; continuing by normal travel",
                nil,
                { GatewayAttempts = gatewayAttempts }
            )
        end
        if request.SpecialTravelRoute
            and request.SpecialTravelRoute.Name == "Submerged"
        then
            local stagingReached, stagingError = self:_RunDirectTravel(
                request,
                character,
                false,
                request.GatewayDestination,
                false
            )
            if not stagingReached then
                if self:_IsTravelCurrent(request, character) then
                    self:_FinishTravel(
                        request,
                        "Could not reach Tiki staging for Submerged travel: "
                            .. tostring(stagingError),
                        "warning"
                    )
                end
                return
            end

            self:_SetStatus("At Tiki; entering Submerged.", "info")
            self.GatewayService:RecordTravelPhase(
                "at Tiki staging; requesting Submerged transport"
            )
            local transported, transportError = self:_RequestSpecialTransport(
                request,
                character,
                request.SpecialTravelRoute
            )
            if not transported then
                if self:_IsTravelCurrent(request, character) then
                    self:_FinishTravel(
                        request,
                        "Could not enter Submerged: " .. tostring(transportError),
                        "warning"
                    )
                end
                return
            end
            self.GatewayService:RecordTravelPhase(
                "Submerged arrival confirmed; continuing to destination"
            )
        end
        self:_RunDirectTravel(request, character, false, request.Destination, true)
    end
end

function TeleportFeature:BuildGatewayDiagnosticReport()
    return self.GatewayService
        and self.GatewayService:BuildDiagnosticReport()
        or nil
end

function TeleportFeature:BuildNpcAvailabilityReport()
    local context = self.Context
    local compatibility = context and context.Compatibility
    local config = context and context.Config
    local workspace = compatibility and compatibility.Workspace
    local replicatedStorage = compatibility and compatibility.ReplicatedStorage
    if not compatibility or not workspace or not replicatedStorage then
        return "===== [TravelNpcDiagnostic] REPORT BEGIN =====\nNPC lookup services are unavailable.\n===== [TravelNpcDiagnostic] REPORT END ====="
    end

    local function normalizeName(name)
        local normalized = string.lower(tostring(name or "")):gsub("[^%w]", "")
        return normalized
    end

    local function targetForName(name)
        local normalized = normalizeName(name)
        for _, target in ipairs(NPC_DIAGNOSTIC_TARGETS) do
            for _, alias in ipairs(target.Names) do
                if normalized == normalizeName(alias) then
                    return target
                end
            end
        end
        return nil
    end

    local function pathOf(instance)
        local ok, path = pcall(function()
            return instance:GetFullName()
        end)
        return ok and path or tostring(instance.Name)
    end

    local function positionOf(root)
        if not root or not root:IsA("BasePart") then
            return "none"
        end
        local position = root.Position
        return string.format("(%.1f, %.1f, %.1f)", position.X, position.Y, position.Z)
    end

    local function isTemplatePositionCurrentSea(root)
        if not root or not root:IsA("BasePart")
            or not config
            or type(config.IsTravelNpcPositionInCurrentSea) ~= "function"
        then
            return false
        end
        local ok, result = pcall(
            config.IsTravelNpcPositionInCurrentSea,
            compatibility,
            root.Position
        )
        return ok and result == true
    end

    local function describeModel(model, sourceLabel, isLive, isDirectNpcSource, seenPaths, lines)
        local modelPath = pathOf(model)
        if seenPaths[modelPath] then
            return false
        end
        seenPaths[modelPath] = true
        local root = model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart
        local validRoot = root and root:IsA("BasePart")
        local humanoid = isLive and model:FindFirstChildOfClass("Humanoid")
        local alive = not humanoid or humanoid.Health > 0
        local templatePositionCurrentSea = isLive or isTemplatePositionCurrentSea(root)
        local selectable = isDirectNpcSource and validRoot and alive and templatePositionCurrentSea
        local reason
        if not isDirectNpcSource then
            reason = "model is outside the direct NPC folders currently searched by travel"
        elseif not validRoot then
            reason = "no direct HumanoidRootPart or PrimaryPart"
        elseif not alive then
            reason = "live NPC is not alive"
        elseif not templatePositionCurrentSea then
            reason = "template root is outside the current-sea travel area"
        else
            reason = "available"
        end
        table.insert(
            lines,
            "  Model: "
                .. modelPath
                .. "; source="
                .. sourceLabel
                .. "; discoverable_by_current_dropdown="
                .. tostring(selectable == true)
                .. "; root="
                .. (validRoot and (root.Name .. " (" .. root.ClassName .. ")") or "none")
                .. "; position="
                .. positionOf(root)
                .. (isLive
                    and "; current_sea_source=live Workspace model"
                    or ("; template_current_sea=" .. tostring(templatePositionCurrentSea)))
                .. (humanoid and ("; health=" .. string.format("%.1f", humanoid.Health)) or "")
                .. "; reason="
                .. reason
        )
        return true
    end

    local liveFolder = workspace:FindFirstChild("NPCs")
    local templateFolder = replicatedStorage:FindFirstChild("NPCs")
    local sourceFolders = {
        { Folder = liveFolder, Label = "Workspace.NPCs", IsLive = true },
        { Folder = templateFolder, Label = "ReplicatedStorage.NPCs", IsLive = false },
    }
    local matches = {}
    local seenPaths = {}
    local lines = {
        "===== [TravelNpcDiagnostic] REPORT BEGIN =====",
        "Sea index: " .. tostring(currentSeaIndex(compatibility) or "unknown"),
        "Scan scope: direct NPC folders, targeted exact-name lookups in Workspace/ReplicatedStorage, and local NPCManager lookup; no remotes invoked",
    }

    for _, target in ipairs(NPC_DIAGNOSTIC_TARGETS) do
        matches[target] = 0
        table.insert(lines, "")
        table.insert(lines, "Target: " .. target.Label)
    end

    for _, source in ipairs(sourceFolders) do
        if source.Folder then
            for _, child in ipairs(source.Folder:GetChildren()) do
                if child:IsA("Model") then
                    local target = targetForName(child.Name)
                    if target then
                        local added = describeModel(
                            child,
                            source.Label,
                            source.IsLive,
                            true,
                            seenPaths,
                            lines
                        )
                        if added then
                            matches[target] += 1
                        end
                    end
                end
            end
        end
    end

    local scanRoots = {
        { Instance = workspace, Label = "Workspace" },
        { Instance = replicatedStorage, Label = "ReplicatedStorage" },
    }
    local seenNamedInstances = {}
    for _, target in ipairs(NPC_DIAGNOSTIC_TARGETS) do
        for _, lookupName in ipairs(target.Names) do
            for _, scanRoot in ipairs(scanRoots) do
                local instance = scanRoot.Instance:FindFirstChild(lookupName, true)
                if instance and not seenNamedInstances[instance] then
                    seenNamedInstances[instance] = true
                    if instance:IsA("Model") then
                        local added = describeModel(
                            instance,
                            scanRoot.Label .. " descendant (outside direct NPC listing unless stated)",
                            instance:IsDescendantOf(workspace),
                            false,
                            seenPaths,
                            lines
                        )
                        if added then
                            matches[target] += 1
                        end
                    else
                        table.insert(
                            lines,
                            scanRoot.Label
                                .. " exact-name instance "
                                .. pathOf(instance)
                                .. " is "
                                .. instance.ClassName
                                .. ", not an NPC Model"
                        )
                    end
                end
            end
        end
    end

    local managerFound = {}
    for _, target in ipairs(NPC_DIAGNOSTIC_TARGETS) do
        local foundManagerModel = false
        for _, lookupName in ipairs(target.Names) do
            local models, lookupError = compatibility:GetNpcModelsByName(lookupName)
            table.insert(
                lines,
                "NPCManager lookup "
                    .. lookupName
                    .. ": "
                    .. (lookupError and ("failed: " .. tostring(lookupError))
                        or (tostring(#models) .. " model(s)"))
            )
            for _, model in ipairs(models) do
                foundManagerModel = true
                local isLive = model:IsDescendantOf(workspace)
                local isDirectNpcSource = model.Parent == liveFolder
                    or model.Parent == templateFolder
                describeModel(
                    model,
                    "NPCManager.getNPCsByName",
                    isLive,
                    isDirectNpcSource,
                    seenPaths,
                    lines
                )
            end
        end
        if not compatibility.GetNpcModelsByName then
            table.insert(
                lines,
                "NPCManager lookup unavailable: Compatibility resolver is missing"
            )
        end
        managerFound[target] = foundManagerModel
    end

    for _, target in ipairs(NPC_DIAGNOSTIC_TARGETS) do
        if matches[target] == 0 and not managerFound[target] then
            table.insert(
                lines,
                "No exact-name model found for "
                    .. target.Label
                    .. " in the scanned folders, descendants, or NPCManager."
            )
        end
    end
    table.insert(lines, "")
    table.insert(lines, "A template position is only reported as evidence; travel still requires a validated current-sea root.")
    table.insert(lines, "===== [TravelNpcDiagnostic] REPORT END =====")
    return table.concat(lines, "\n")
end

function TeleportFeature:_FinishTravel(request, message, kind)
    if request.IsFarmTask == true then
        if self.ActiveFarmTravel ~= request then
            return
        end
        self.ActiveFarmTravel = nil
        self.FarmTravelGeneration += 1
        if self.MovementService then
            self.MovementService:Cancel()
        end
        local statusMessage = "Gateway route finished; farming will continue."
        local statusKind = "info"
        if kind == "warning" or kind == "error" then
            statusMessage = message or statusMessage
            statusKind = kind
        end
        self:_SetStatus(statusMessage, statusKind)
        return
    end
    if self.ActiveTravel ~= request then
        return
    end
    self.ActiveTravel = nil
    self.Generation += 1
    if self.MovementService then
        self.MovementService:Cancel()
        self.MovementService:SetFarmCollisionSuppression(false)
    end
    self:_SetFeatureEnabled(request.Action, false)
    self:_SetStatus(message, kind)
    local coordinator = self.Context and self.Context.TaskCoordinator
    if coordinator and request.CoordinatorLease then
        coordinator:Release(request.CoordinatorLease)
    end
end

function TeleportFeature:Cancel(message, keepActionEnabled)
    local request = self.ActiveTravel
    if not request then
        return false
    end
    self.ActiveTravel = nil
    self.Generation += 1
    if self.MovementService then
        self.MovementService:Cancel()
        self.MovementService:SetFarmCollisionSuppression(false)
    end
    if not keepActionEnabled then
        self:_SetFeatureEnabled(request.Action, false)
    end
    if message then
        self:_SetStatus(message, "warning")
    elseif keepActionEnabled then
        self:_SetStatus("Updating travel destination.", "info")
    else
        self:_SetStatus("Travel cancelled.", "info")
    end
    local coordinator = self.Context and self.Context.TaskCoordinator
    if coordinator and request.CoordinatorLease then
        coordinator:Release(request.CoordinatorLease)
    end
    return true
end

function TeleportFeature:CancelFarmTravel(skipMovementCancel)
    if not self.ActiveFarmTravel then
        return false
    end
    self.ActiveFarmTravel = nil
    self.FarmTravelGeneration += 1
    self.LastFarmGatewayPlanCheck = nil
    if self.MovementService and not skipMovementCancel then
        self.MovementService:Cancel()
    end
    return true
end

function TeleportFeature:MoveFarmTo(destination, options)
    options = options or {}
    if typeof(destination) ~= "CFrame"
        or not self.GatewayService
        or not self.MovementService
    then
        return false, "Gateway-aware farm travel is unavailable"
    end
    local isCurrent = options.IsCurrent or function()
        return true
    end
    if not isCurrent() then
        self:CancelFarmTravel()
        return false, "Farm movement is no longer current"
    end

    local character, _, root = self.Context.Compatibility:GetCharacterParts()
    if not character or not root then
        return false, "Character is unavailable"
    end

    local active = self.ActiveFarmTravel
    if active and self:_IsTravelCurrent(active, active.Character) then
        local shift = (active.Destination.Position - destination.Position).Magnitude
        if shift <= 500 then
            active.Destination = destination
            active.Label = options.Label or active.Label
            return true, "gateway route in progress"
        end
        self:CancelFarmTravel()
    elseif active then
        self:CancelFarmTravel()
    end

    local specialRoute = self.MovementService:GetSpecialTravelRoute(
        destination,
        root.Position
    )
    local gatewayDestination = destination
    local specialTravelRoute
    local outboundTiki = specialRoute and specialRoute.Name == "Tiki"
    if specialRoute
        and (specialRoute.Name == "Submerged" or specialRoute.Name == "Tiki")
    then
        gatewayDestination = specialRoute.Stage
        specialTravelRoute = specialRoute
    end
    local gatewayPlanLabel
    if specialTravelRoute and specialTravelRoute.Name == "Submerged" then
        gatewayPlanLabel = "Tiki staging for Submerged"
    elseif outboundTiki then
        gatewayPlanLabel = "Submerged exit staging"
    else
        gatewayPlanLabel = options.Label or "Farm target"
    end
    local directDistance = (gatewayDestination.Position - root.Position).Magnitude
    if directDistance <= 1500 and not outboundTiki then
        self.LastFarmGatewayPlanCheck = nil
        return false, "No long-distance gateway route needed"
    end

    local now = os.clock()
    local cached = self.LastFarmGatewayPlanCheck
    if not outboundTiki
        and cached
        and now - cached.At < 0.75
        and cached.RouteDestination
        and (cached.RouteDestination - gatewayDestination.Position).Magnitude <= 200
    then
        return false, cached.Error or "No qualifying gateway route"
    end

    local planOk, routePlan = true, {}
    if not outboundTiki then
        planOk, routePlan = pcall(
            self.GatewayService.FindPlan,
            self.GatewayService,
            gatewayDestination.Position,
            root.Position,
            gatewayPlanLabel
        )
    end
    if not planOk
        or type(routePlan) ~= "table"
        or (#routePlan == 0 and not outboundTiki)
    then
        self.LastFarmGatewayPlanCheck = {
            At = now,
            Destination = destination.Position,
            RouteDestination = gatewayDestination.Position,
            Error = planOk and "No qualifying gateway route" or tostring(routePlan),
        }
        return false, self.LastFarmGatewayPlanCheck.Error
    end

    self.FarmTravelGeneration += 1
    local request = {
        IsFarmTask = true,
        Generation = self.FarmTravelGeneration,
        Character = character,
        StartedAt = now,
        Label = options.Label or "Farm target",
        Destination = destination,
        GatewayDestination = gatewayDestination,
        GatewayPlanLabel = gatewayPlanLabel,
        SpecialTravelRoute = specialTravelRoute,
        RoutePlan = routePlan,
        RouteStartPosition = root.Position,
        RoutePlanDestination = gatewayDestination.Position,
        IsCurrent = isCurrent,
        Speed = tonumber(options.Speed) or 190,
        Threshold = tonumber(options.Threshold) or 8,
        KeepSession = options.KeepSession == true,
        StallRetries = 0,
    }
    self.ActiveFarmTravel = request
    self.LastFarmGatewayPlanCheck = nil
    if outboundTiki then
        self:_SetStatus(
            "Leaving Submerged through Tiki before continuing to " .. request.Label .. ".",
            "info"
        )
    else
        self:_SetStatus("Using a shorter gateway route to " .. request.Label .. ".", "info")
    end
    task.spawn(function()
        local runOk, runError = pcall(self._RunTravel, self, request, character)
        if not runOk and self.ActiveFarmTravel == request then
            self:_FinishTravel(
                request,
                "Gateway route failed; farming will retry normal travel: " .. tostring(runError),
                "warning"
            )
        end
    end)
    return true, "gateway route selected"
end

function TeleportFeature:EstimateFarmTravelDistance(currentPosition, destinationPosition)
    if typeof(currentPosition) ~= "Vector3"
        or typeof(destinationPosition) ~= "Vector3"
    then
        return nil, "Travel positions are unavailable"
    end

    local destination = CFrame.new(destinationPosition)
    local specialRoute = self.MovementService
        and self.MovementService:GetSpecialTravelRoute(destination, currentPosition)
    if specialRoute then
        local stagePosition = specialRoute.Stage and specialRoute.Stage.Position
        local arrivalReference = specialRoute.ArrivalReference
        if typeof(stagePosition) ~= "Vector3" then
            return (destinationPosition - currentPosition).Magnitude
        end

        local approachDistance
        if specialRoute.Name == "Tiki" then
            approachDistance = (stagePosition - currentPosition).Magnitude
        elseif self.GatewayService then
            approachDistance = self.GatewayService:EstimateTravelDistance(
                stagePosition,
                currentPosition
            )
        else
            approachDistance = (stagePosition - currentPosition).Magnitude
        end
        local finalDistance = typeof(arrivalReference) == "Vector3"
                and (destinationPosition - arrivalReference).Magnitude
            or 0
        return approachDistance + finalDistance
    end

    if self.GatewayService then
        return self.GatewayService:EstimateTravelDistance(
            destinationPosition,
            currentPosition
        )
    end
    return (destinationPosition - currentPosition).Magnitude
end

function TeleportFeature:_StartTravel(destination, destinationLabel, actionId)
    local context = self.Context
    local compatibility = context and context.Compatibility
    local mainFarm = context and context.MainFarm
    if mainFarm and mainFarm.MainFarmEnabled then
        self:_SetFeatureEnabled(actionId, false)
        self:_SetStatus(
            "Travel unavailable while Main Farming is active.",
            "error",
            "Turn off Start Farm first. Travel and farming can't run together."
        )
        return false, "Main Farming is active"
    end
    if self.ActiveTravel then
        if self.ActiveTravel.Action == actionId then
            return true
        end
        self:_SetFeatureEnabled(actionId, false)
        self:_SetStatus(
            "Travel unavailable: another trip is already active.",
            "error",
            "Turn off the current travel switch before starting a different trip."
        )
        return false, "Another trip is active"
    end
    local character, humanoid, root = compatibility:GetCharacterParts()
    if not character or not humanoid or not root then
        self:_SetFeatureEnabled(actionId, false)
        self:_SetStatus("Travel unavailable: character is not ready.", "error")
        return false, "Character is unavailable"
    end

    local coordinator = context and context.TaskCoordinator
    if not coordinator then
        self:_SetFeatureEnabled(actionId, false)
        self:_SetStatus("Travel is temporarily unavailable.", "error")
        return false, "Task coordination is unavailable"
    end
    local request
    local coordinatorLease, blockingTask = coordinator:TryAcquire(
        "Travel",
        "Travel to " .. destinationLabel,
        "Background",
        function(preemptingGroup, preemptingLabel)
            if request and self.ActiveTravel == request then
                local message = preemptingGroup == "StackFarm"
                    and "Travel stopped so Stack Farming can finish its task."
                    or "Travel stopped so " .. tostring(preemptingLabel or "another task")
                        .. " can use the character."
                self:Cancel(message, false)
            end
        end
    )
    if not coordinatorLease then
        self:_SetFeatureEnabled(actionId, false)
        self:_SetStatus(
            "Travel is waiting for " .. tostring(blockingTask and blockingTask.Label or "current work"),
            "warning",
            "Let the current task finish before starting another trip."
        )
        return false, "Another task is active"
    end

    local collisionCallOk, collisionReady, collisionError = pcall(function()
        return self.MovementService:SetFarmCollisionSuppression(true)
    end)
    if not collisionCallOk then
        collisionError = collisionReady
        collisionReady = false
    end
    if not collisionReady then
        coordinator:Release(coordinatorLease)
        self:_SetFeatureEnabled(actionId, false)
        self:_SetStatus("Travel collision setup failed: " .. tostring(collisionError), "error")
        return false, collisionError
    end

    local specialRoute = self.MovementService:GetSpecialTravelRoute(
        destination,
        root.Position
    )
    local gatewayDestination = destination
    local gatewayPlanLabel = destinationLabel
    if specialRoute and specialRoute.Name == "Tiki" then
        gatewayDestination = specialRoute.Stage
        gatewayPlanLabel = "Submerged exit staging"
    else
        specialRoute = nil
    end

    self.Generation += 1
    request = {
        Generation = self.Generation,
        Character = character,
        StartedAt = os.clock(),
        Label = destinationLabel,
        Action = actionId,
        Destination = destination,
        GatewayDestination = gatewayDestination,
        GatewayPlanLabel = gatewayPlanLabel,
        SpecialTravelRoute = specialRoute,
        StallRetries = 0,
        CoordinatorLease = coordinatorLease,
    }
    self.ActiveTravel = request
    self:_SetFeatureEnabled(actionId, true)

    self:_SetStatus("Travelling to " .. destinationLabel .. ".", "info")
    task.spawn(function()
        local runOk, runError = pcall(self._RunTravel, self, request, character)
        if not runOk and self.ActiveTravel == request then
            self:_FinishTravel(
                request,
                "Travel could not continue: " .. tostring(runError),
                "error"
            )
        end
    end)
    return true
end

function TeleportFeature:_SelectSetting(setting, value, validOptions)
    if type(value) ~= "string" then
        self:_SetStatus("Travel selection must be a destination name.", "error")
        return false, "Invalid selection"
    end
    for _, option in ipairs(validOptions) do
        if option == value then
            self.Context.Config.TravelSettings[setting] = value
            self:_SetStatus("Selected " .. value .. ".", "success")
            return true
        end
    end
    self:_SetStatus("That destination is not available in the current sea.", "warning")
    return false, "Destination is unavailable"
end

function TeleportFeature:_RetargetActiveIslandTravel()
    local request = self.ActiveTravel
    if not request or request.Action ~= "teleport.island" then
        return false
    end

    local island, islandError = self:_GetSelectedIsland()
    if not island then
        self:Cancel(
            "Island travel stopped: "
                .. tostring(islandError or "the selected destination is unavailable")
                .. "."
        )
        return false
    end
    if request.Label == island.Name then
        return true
    end

    local destination, destinationError = self:_ResolveIslandCFrame(island)
    if not destination then
        self:Cancel(
            "Island travel stopped: "
                .. tostring(destinationError or "the selected destination is unavailable")
                .. "."
        )
        return false
    end

    self:Cancel(nil, true)
    return self:_StartTravel(destination, island.Name, request.Action)
end

function TeleportFeature:Handle(actionId, payload)
    local config = self.Context and self.Context.Config
    if actionId == "teleport.npc.report" then
        local report = self:BuildNpcAvailabilityReport()
        local copied = false
        local clipboardOk = pcall(function()
            if type(setclipboard) == "function" then
                setclipboard(report)
                copied = true
            end
        end)
        if clipboardOk and copied then
            self:_SetStatus("NPC availability report copied.", "success")
        else
            print(report)
            self:_SetStatus("Clipboard unavailable; NPC report printed to output.", "warning")
        end
        return true
    elseif actionId == "teleport.island.select" then
        local compatibility = self.Context.Compatibility
        local seaIndex = currentSeaIndex(compatibility)
        local options = {}
        for _, destination in ipairs(
            seaIndex and (config.TravelDestinations[seaIndex] or {}) or {}
        ) do
            table.insert(options, destination.Name)
        end
        local selected = self:_SelectSetting("Island", payload, options)
        if selected then
            self:_RetargetActiveIslandTravel()
        end
        return true
    elseif actionId == "teleport.npc.select" then
        local compatibility = self.Context.Compatibility
        local options = type(config.TravelNpcsForCurrentSea) == "function"
            and config.TravelNpcsForCurrentSea(compatibility)
            or {}
        self:_SelectSetting("Npc", payload, options)
        return true
    elseif actionId == "teleport.island" or actionId == "teleport.npc" then
        if payload ~= true then
            if self.ActiveTravel and self.ActiveTravel.Action == actionId then
                self:Cancel()
            else
                self:_SetFeatureEnabled(actionId, false)
            end
            return true
        end

        local destinationLabel
        local destination
        local destinationError
        if actionId == "teleport.island" then
            local island
            island, destinationError = self:_GetSelectedIsland()
            if island then
                destinationLabel = island.Name
                destination, destinationError = self:_ResolveIslandCFrame(island)
            end
        else
            destination, destinationError = self:_GetNpcDestination()
            destinationLabel = "NPC " .. tostring(config.TravelSettings.Npc)
        end
        if not destination then
            self:_SetFeatureEnabled(actionId, false)
            self:_SetStatus(tostring(destinationError or "Travel target is unavailable") .. ".", "warning")
            return true
        end
        self:_StartTravel(destination, destinationLabel, actionId)
        return true
    end
    return false
end

function TeleportFeature:Initialize(context)
    self:Cleanup()
    self.Context = context
    self.Generation = 0
    self.FarmTravelGeneration = 0
    self.ActiveTravel = nil
    self.ActiveFarmTravel = nil
    self.LastFarmGatewayPlanCheck = nil
    self.MovementService = context.MovementService
    self.GatewayService = MapGatewayService.new(context.Compatibility)
    if self.MovementService then
        self.MovementService.OnCancel = function()
            self:CancelFarmTravel(true)
        end
    end

    local player = context.Compatibility.Player
    if player then
        self.CharacterRemovingConnection = player.CharacterRemoving:Connect(function()
            self:CancelFarmTravel()
            self:Cancel("Travel cancelled because the character is resetting.")
        end)
    end
    return true
end

function TeleportFeature:Cleanup()
    self:CancelFarmTravel()
    self:Cancel("Travel cancelled during hub cleanup.")
    if self.MovementService then
        self.MovementService.OnCancel = nil
    end
    disconnect(self.CharacterRemovingConnection)
    self.CharacterRemovingConnection = nil
    self.Context = nil
    self.MovementService = nil
    self.GatewayService = nil
end

return TeleportFeature
-- END SOURCE: src/ReplicatedStorage/CustomHub/Features/TeleportFeature.lua
end

__bundleFactories["CustomHub.Features.Farm.QuestService"] = function()
-- BEGIN SOURCE: src/ReplicatedStorage/CustomHub/Features/Farm/QuestService.lua
local QuestService = {}
QuestService.__index = QuestService

local MAX_TRACKED_QUEST_TEXT_LENGTH = 160
local MAX_TRACKED_QUEST_PROGRESS_LENGTH = 32
local MAX_MAIN_QUEST_TITLE_LENGTH = 160

local excludedQuestNames = {
    BartiloQuest = true,
    Trainees = true,
    MarineQuest = true,
    CitizenQuest = true,
}

local function diagnosticScalarRepresentation(value)
    local valueType = typeof(value)
    if type(value) == "string" then
        return string.format("<string length=%d>", #value)
    end

    if value == nil or type(value) == "boolean" then
        return tostring(value)
    end
    if type(value) == "number" then
        return "<number-redacted>"
    end
    return "<" .. tostring(valueType) .. ">"
end

local function usableTrackedQuestText(text, maxLength)
    if type(text) ~= "string" or #text == 0 or #text > maxLength then
        return nil
    end

    local trimmed = text:match("^%s*(.-)%s*$")
    if trimmed == "" then
        return nil
    end
    return trimmed
end

local function singularizeQuestTargetWord(word)
    if #word > 3 and word:sub(-3) == "ies" then
        local stem = word:sub(1, -4)
        local lastStemCharacter = stem:sub(-1)
        if lastStemCharacter ~= "" and not lastStemCharacter:match("[aeiou]") then
            return stem .. "y"
        end
    end

    if #word > 4 and word:sub(-2) == "es" then
        local stem = word:sub(1, -3)
        if stem:sub(-1) == "s" or stem:sub(-1) == "x" or stem:sub(-1) == "z"
            or stem:sub(-2) == "ch" or stem:sub(-2) == "sh"
        then
            return stem
        end
    end

    local ending = word:sub(-2)
    if #word > 2 and word:sub(-1) == "s"
        and ending ~= "ss" and ending ~= "us" and ending ~= "is"
    then
        return word:sub(1, -2)
    end
    return word
end

local function normalizeQuestTargetName(name)
    if type(name) ~= "string" or #name == 0 or #name > MAX_TRACKED_QUEST_TEXT_LENGTH then
        return nil
    end

    local words = {}
    for word in name:lower():gmatch("[%w]+") do
        table.insert(words, word)
    end
    if #words == 0 then
        return nil
    end

    words[#words] = singularizeQuestTargetWord(words[#words])
    return table.concat(words, " ")
end

local function trackedTargetMatches(catalogTarget, trackedTarget, allowFirstSeaVariants)
    if catalogTarget == trackedTarget then
        return true
    end
    if not allowFirstSeaVariants then
        return false
    end

    local normalizedCatalogTarget = normalizeQuestTargetName(catalogTarget)
    local normalizedTrackedTarget = normalizeQuestTargetName(trackedTarget)
    return normalizedCatalogTarget ~= nil
        and normalizedCatalogTarget == normalizedTrackedTarget
end

local function isVisibleGuiObjectWithin(instance, root)
    if not instance or not instance:IsA("GuiObject") then
        return false
    end

    local current = instance
    while current and current ~= root do
        if current:IsA("GuiObject") and not current.Visible then
            return false
        end
        if current:IsA("ScreenGui") and not current.Enabled then
            return false
        end
        current = current.Parent
    end
    return current == root
end

local function parseTrackedQuestProgress(text)
    if type(text) ~= "string" or #text > MAX_TRACKED_QUEST_PROGRESS_LENGTH then
        return nil
    end

    local currentText, totalText = text:match("^%s*(%d+)%s*/%s*(%d+)%s*$")
    if not currentText or not totalText then
        return nil
    end

    local current = tonumber(currentText)
    local total = tonumber(totalText)
    if not current or not total
        or current == math.huge
        or total == math.huge
        or total <= 0
        or current >= total
    then
        return nil
    end
    return current, total
end

local function titleContainsTarget(title, targetName, allowFirstSeaVariants)
    if type(title) ~= "string" or type(targetName) ~= "string" then
        return false
    end

    local titleWords = {}
    for word in title:lower():gmatch("[%w]+") do
        table.insert(titleWords, word)
    end
    local targetWords = {}
    for word in targetName:lower():gmatch("[%w]+") do
        table.insert(targetWords, word)
    end
    if #targetWords == 0 or #targetWords > #titleWords then
        return false
    end

    for startIndex = 1, #titleWords - #targetWords + 1 do
        local matches = true
        for offset, expected in ipairs(targetWords) do
            local actual = titleWords[startIndex + offset - 1]
            local finalWord = offset == #targetWords
            local finalWordMatches = finalWord
                and (actual == expected .. "s"
                    or (allowFirstSeaVariants
                        and trackedTargetMatches(actual, expected, true)))
            if actual ~= expected and not finalWordMatches then
                matches = false
                break
            end
        end
        if matches then
            return true
        end
    end
    return false
end

local function parseMainQuestTitleProgress(title)
    if type(title) ~= "string" then
        return nil
    end
    local currentText, totalText = title:match("%((%d+)%s*/%s*(%d+)%)%s*$")
    local current = tonumber(currentText)
    local total = tonumber(totalText)
    if not current or not total or total <= 0 or current >= total then
        return nil
    end
    return current, total
end

local function findEligibleQuestTarget(
    self,
    guideData,
    targetName,
    progressTotal,
    allowFirstSeaActiveQuest
)
    local level = self:GetPlayerLevel()
    local npcList = type(guideData) == "table" and guideData.NPCList or nil
    if not level or type(npcList) ~= "table" or type(self.Quests) ~= "table" then
        return nil
    end

    local firstSeaMatches = {}
    -- Selection exclusions do not hide a separately verified active First Sea quest.
    for _, npcEntry in pairs(npcList) do
        if type(npcEntry) == "table"
            and (allowFirstSeaActiveQuest or not excludedQuestNames[npcEntry.InternalQuestName])
            and type(npcEntry.Levels) == "table"
        then
            local questGroup = self.Quests[npcEntry.InternalQuestName]
            if type(questGroup) == "table" then
                for questId, requiredLevel in pairs(npcEntry.Levels) do
                    local numericLevel = tonumber(requiredLevel)
                    local quest = questGroup[questId]
                    if numericLevel and numericLevel >= 0 and numericLevel <= level
                        and type(quest) == "table" and type(quest.Task) == "table"
                    then
                        if allowFirstSeaActiveQuest then
                            for mobName, count in pairs(quest.Task) do
                                local numericCount = tonumber(count)
                                if type(mobName) == "string"
                                    and trackedTargetMatches(mobName, targetName, true)
                                    and numericCount == progressTotal and numericCount > 1
                                then
                                    firstSeaMatches[mobName] = true
                                end
                            end
                        else
                            local mobName, count = next(quest.Task)
                            local numericCount = tonumber(count)
                            if mobName == targetName and numericCount == progressTotal
                                and numericCount > 1
                            then
                                return mobName
                            end
                        end
                    end
                end
            end
        end
    end

    if allowFirstSeaActiveQuest then
        local matchedTarget = nil
        for mobName in pairs(firstSeaMatches) do
            if matchedTarget then
                return nil
            end
            matchedTarget = mobName
        end
        return matchedTarget
    end
    return nil
end

local function findEligibleTargetFromTitle(self, guideData, title, progressTotal)
    local level = self:GetPlayerLevel()
    local npcList = type(guideData) == "table" and guideData.NPCList or nil
    if not level or type(npcList) ~= "table" or type(self.Quests) ~= "table" then
        return nil, "quest catalog or eligible NPC list is unavailable"
    end

    local bestTarget, bestLength, ambiguous = nil, 0, false
    for _, npcEntry in pairs(npcList) do
        if type(npcEntry) == "table"
            and not excludedQuestNames[npcEntry.InternalQuestName]
            and type(npcEntry.Levels) == "table"
        then
            local questGroup = self.Quests[npcEntry.InternalQuestName]
            if type(questGroup) == "table" then
                for questId, requiredLevel in pairs(npcEntry.Levels) do
                    local numericLevel = tonumber(requiredLevel)
                    local quest = questGroup[questId]
                    if numericLevel and numericLevel >= 0 and numericLevel <= level
                        and type(quest) == "table" and type(quest.Task) == "table"
                    then
                        for mobName, count in pairs(quest.Task) do
                            local numericCount = tonumber(count)
                            if type(mobName) == "string" and numericCount and numericCount > 1
                                and numericCount == progressTotal
                                and titleContainsTarget(title, mobName)
                            then
                                local nameLength = #mobName
                                if nameLength > bestLength then
                                    bestTarget, bestLength, ambiguous = mobName, nameLength, false
                                elseif nameLength == bestLength and bestTarget ~= mobName then
                                    ambiguous = true
                                end
                            end
                        end
                    end
                end
            end
        end
    end

    if ambiguous then
        return nil, "visible quest title matches multiple catalog targets"
    end
    if not bestTarget then
        return nil, "visible quest title does not map to a level-eligible catalog target"
    end
    return bestTarget
end

local function readTrackedQuestTarget(self, guideData, isFirstSea)
    local ok, targetName = pcall(function()
        local compatibility = self.Compatibility
        if not compatibility or type(compatibility.GetPlayerGui) ~= "function" then
            return nil
        end

        local playerGui = compatibility:GetPlayerGui()
        local trackedQuestFrame = playerGui and playerGui:FindFirstChild("TrackedQuestFrame")
        if not trackedQuestFrame or not trackedQuestFrame:IsA("ScreenGui")
            or not trackedQuestFrame.Enabled
        then
            return nil
        end

        local frame = trackedQuestFrame:FindFirstChild("Frame")
        local header = frame and frame:FindFirstChild("header")
        local titleLabel = header and header:FindFirstChild("textLabel")
        local description = frame and frame:FindFirstChild("description")
        local progressLabel = frame and frame:FindFirstChild("progress")
        if isFirstSea
            and (not isVisibleGuiObjectWithin(titleLabel, trackedQuestFrame)
                or not isVisibleGuiObjectWithin(description, trackedQuestFrame)
                or not isVisibleGuiObjectWithin(progressLabel, trackedQuestFrame))
        then
            return nil
        end

        local title = titleLabel and usableTrackedQuestText(
            titleLabel.Text,
            MAX_TRACKED_QUEST_TEXT_LENGTH
        )
        local target = description and usableTrackedQuestText(
            description.Text,
            MAX_TRACKED_QUEST_TEXT_LENGTH
        )
        local progressText = progressLabel and progressLabel.Text
        if not title or not target then
            return nil
        end
        if isFirstSea and not titleContainsTarget(title, target, true) then
            return nil
        end
        local progressCurrent, progressTotal = parseTrackedQuestProgress(progressText)
        if progressCurrent == nil or progressTotal == nil then
            return nil
        end

        return findEligibleQuestTarget(self, guideData, target, progressTotal, isFirstSea == true)
    end)

    if not ok then
        return nil
    end
    return targetName
end

local function visibleDialogueText(label, playerGui)
    local isTextLabel = label and (
        label:IsA("TextLabel")
            or label:IsA("TextButton")
            or label:IsA("TextBox")
    )
    if not isTextLabel or not isVisibleGuiObjectWithin(label, playerGui)
        or type(label.Text) ~= "string"
    then
        return nil
    end

    local text = label.Text:match("^%s*(.-)%s*$")
    if text == "" or #text > 64 then
        return nil
    end
    return text
end

local function matchesQuestDialogueTaskTitle(titleText, quests)
    if type(titleText) ~= "string" or type(quests) ~= "table" then
        return false
    end
    local normalizedTitle = normalizeQuestTargetName(titleText)
    if not normalizedTitle then
        return false
    end

    for _, questGroup in pairs(quests) do
        if type(questGroup) == "table" then
            for _, questData in pairs(questGroup) do
                local task = type(questData) == "table" and questData.Task or nil
                if type(task) == "table" then
                    local targetName, count = next(task)
                    local numericCount = tonumber(count)
                    if type(targetName) == "string" and numericCount and numericCount > 0 then
                        local expectedTitle = "Defeat "
                            .. tostring(numericCount)
                            .. " "
                            .. targetName
                        if normalizeQuestTargetName(expectedTitle) == normalizedTitle then
                            return true
                        end
                    end
                end
            end
        end
    end
    return false
end

local function hasVisibleQuestGiverDialogue(playerGui, guideData, quests)
    local dialogueGui = playerGui and playerGui:FindFirstChild("DialogueGui")
    local titleFrame = dialogueGui
        and dialogueGui:FindFirstChild("dialogueTitleFrame", true)
    if not titleFrame or not isVisibleGuiObjectWithin(titleFrame, playerGui) then
        return false
    end

    local subtitle = titleFrame and titleFrame:FindFirstChild("subtitle")
    local titleLabel = subtitle and subtitle:FindFirstChild("title")
    local titleText = visibleDialogueText(titleLabel, playerGui)
    if titleText and string.lower(titleText) == "quest giver" then
        return true
    end

    -- Some quest-giver pages show the NPC name instead of the generic role
    -- title. Match that label against the live quest catalog.
    local speakerLabel = titleFrame:FindFirstChild("name")
    local speakerText = visibleDialogueText(speakerLabel, playerGui)
    local npcList = type(guideData) == "table" and guideData.NPCList or nil
    if type(npcList) == "table" then
        for _, npcEntry in pairs(npcList) do
            local npcName = type(npcEntry) == "table" and npcEntry.NPCName or nil
            if type(npcName) == "string" then
                npcName = npcName:match("^%s*(.-)%s*$")
                local normalizedNpcName = string.lower(npcName)
                if (titleText and string.lower(titleText) == normalizedNpcName)
                    or (speakerText and string.lower(speakerText) == normalizedNpcName)
                then
                    return true
                end
            end
        end
    end

    -- The second page uses a generic Rewards heading and puts the selected
    -- quest title in the speaker slot (for example, "Defeat 8 Pirates").
    -- Match that title against quest tasks, without accepting the quest.
    return titleText
        and string.lower(titleText) == "rewards"
        and matchesQuestDialogueTaskTitle(speakerText, quests)
        or false
end

local function readFirstSeaQuestHud(self, guideData)
    local ok, state, targetName, reason = pcall(function()
        local compatibility = self.Compatibility
        if not compatibility or type(compatibility.GetPlayerGui) ~= "function" then
            return "unknown", nil, "PlayerGui reader is unavailable"
        end

        local playerGui = compatibility:GetPlayerGui()
        local main = playerGui and playerGui:FindFirstChild("Main")
        if not main then
            return "unknown", nil, "PlayerGui.Main is unavailable"
        end
        if main:IsA("ScreenGui") and not main.Enabled then
            if hasVisibleQuestGiverDialogue(playerGui, guideData, self.Quests) then
                return "none", nil,
                    "visible Quest Giver dialogue; StartQuest still requires active-state confirmation"
            end
            return "unknown", nil,
                "PlayerGui.Main ScreenGui is disabled; no visible Quest Giver dialogue was found"
        end

        local questFrame = main:FindFirstChild("Quest")
        if not questFrame or not questFrame:IsA("GuiObject") then
            return "unknown", nil, "PlayerGui.Main.Quest is unavailable"
        end
        if not questFrame.Visible then
            return "none", nil, "PlayerGui.Main.Quest.Visible is false"
        end

        local container = questFrame:FindFirstChild("Container")
        local questTitle = container and container:FindFirstChild("QuestTitle")
        local titleLabel = questTitle and questTitle:FindFirstChild("Title")
        local titleIsText = titleLabel and (
            titleLabel:IsA("TextLabel")
                or titleLabel:IsA("TextButton")
                or titleLabel:IsA("TextBox")
        )
        if not titleIsText or not titleLabel.Visible
            or not container or (container:IsA("GuiObject") and not container.Visible)
            or not questTitle or (questTitle:IsA("GuiObject") and not questTitle.Visible)
        then
            return "active-unknown", nil, "visible quest panel has no visible readable title label"
        end

        local title = usableTrackedQuestText(titleLabel.Text, MAX_MAIN_QUEST_TITLE_LENGTH)
        if not title then
            return "active-unknown", nil, "visible quest panel title is empty or malformed"
        end
        local _, progressTotal = parseMainQuestTitleProgress(title)
        if not progressTotal then
            return "active-unknown", nil, "visible quest title has no valid incomplete current/total progress"
        end
        local mappedTarget, mappingError = findEligibleTargetFromTitle(
            self,
            guideData,
            title,
            progressTotal
        )
        if not mappedTarget then
            return "active-unknown", nil, mappingError
        end
        return "active", mappedTarget,
            "visible Main.Quest title/progress maps to the level-eligible quest catalog"
    end)

    if not ok then
        return "unknown", nil, "First Sea quest HUD read failed safely"
    end
    return state, targetName, reason
end

function QuestService.new(compatibility)
    local quests, guide, loadError = compatibility:GetQuestModules()
    if not quests then
        return nil, loadError
    end
    return setmetatable({
        Compatibility = compatibility,
        Player = compatibility.Player,
        Quests = quests,
        Guide = guide,
    }, QuestService)
end

function QuestService:GetPlayerLevel()
    local data = self.Player and self.Player:FindFirstChild("Data")
    local level = data and data:FindFirstChild("Level")
    return level and tonumber(level.Value)
end

function QuestService:IsQuestGiverDialogueOpen()
    local ok, isOpen = pcall(function()
        local compatibility = self.Compatibility
        if not compatibility or type(compatibility.GetPlayerGui) ~= "function" then
            return false
        end
        local guideData = self.Guide and self.Guide.Data
        return hasVisibleQuestGiverDialogue(
            compatibility:GetPlayerGui(),
            guideData,
            self.Quests
        )
    end)
    return ok and isOpen == true
end

function QuestService:GetActiveQuestState()
    local guideData = self.Guide and self.Guide.Data
    local questData = type(guideData) == "table" and guideData.QuestData or nil
    if type(questData) == "table" and type(questData.Task) == "table" then
        local targetName = next(questData.Task)
        if type(targetName) == "string" and targetName ~= "" then
            return "active", targetName, "GuideModule.Data.QuestData.Task"
        end
    end

    local firstSea = false
    if self.Compatibility and type(self.Compatibility.IsFirstSea) == "function" then
        local seaReadOk, isFirstSea = pcall(self.Compatibility.IsFirstSea, self.Compatibility)
        firstSea = seaReadOk and isFirstSea == true
    end

    local trackedTarget = readTrackedQuestTarget(self, guideData, firstSea)
    if trackedTarget then
        return "active", trackedTarget, "TrackedQuestFrame title/target/progress mapped to quest catalog"
    end

    if firstSea then
        local hudState, hudTarget, hudReason = readFirstSeaQuestHud(self, guideData)
        return hudState, hudTarget, hudReason
    end

    if type(guideData) ~= "table" then
        return "unknown", nil, "GuideModule.Data is unavailable"
    end
    if questData == nil then
        return "none", nil, "GuideModule.Data.QuestData is absent"
    end
    if type(questData) ~= "table" or type(questData.Task) ~= "table" then
        return "unknown", nil, "GuideModule.Data.QuestData.Task is not a table"
    end
    return "active-unknown", nil, "GuideModule exposes a quest record without a readable task"
end

function QuestService:GetActiveQuestDetails()
    local state, targetName, evidence = self:GetActiveQuestState()
    local details = {
        State = state,
        Target = targetName,
        Title = "Unavailable",
        Progress = "Unavailable",
        Reader = evidence or "Quest reader unavailable",
    }
    if state ~= "active" or type(targetName) ~= "string" then
        return details
    end

    local guideData = self.Guide and self.Guide.Data
    local questData = type(guideData) == "table" and guideData.QuestData or nil
    local taskData = type(questData) == "table" and questData.Task or nil
    local requiredCount = type(taskData) == "table" and tonumber(taskData[targetName]) or nil
    if requiredCount and requiredCount > 0 then
        details.Title = "Defeat " .. tostring(requiredCount) .. " " .. targetName
        details.Progress = "Required: " .. tostring(requiredCount) .. "; current progress unavailable"
    end

    local firstSea = false
    if self.Compatibility and type(self.Compatibility.IsFirstSea) == "function" then
        local seaOk, isFirstSea = pcall(
            self.Compatibility.IsFirstSea,
            self.Compatibility
        )
        firstSea = seaOk and isFirstSea == true
    end

    local ok, guiDetails = pcall(function()
        local compatibility = self.Compatibility
        if not compatibility or type(compatibility.GetPlayerGui) ~= "function" then
            return nil
        end
        local playerGui = compatibility:GetPlayerGui()
        if not playerGui then
            return nil
        end

        local trackedQuestFrame = playerGui:FindFirstChild("TrackedQuestFrame")
        if trackedQuestFrame and trackedQuestFrame:IsA("ScreenGui")
            and trackedQuestFrame.Enabled
        then
            local frame = trackedQuestFrame:FindFirstChild("Frame")
            local header = frame and frame:FindFirstChild("header")
            local titleLabel = header and header:FindFirstChild("textLabel")
            local description = frame and frame:FindFirstChild("description")
            local progressLabel = frame and frame:FindFirstChild("progress")
            if isVisibleGuiObjectWithin(titleLabel, trackedQuestFrame)
                and isVisibleGuiObjectWithin(description, trackedQuestFrame)
                and isVisibleGuiObjectWithin(progressLabel, trackedQuestFrame)
            then
                local title = usableTrackedQuestText(
                    titleLabel.Text,
                    MAX_TRACKED_QUEST_TEXT_LENGTH
                )
                local trackedTarget = usableTrackedQuestText(
                    description.Text,
                    MAX_TRACKED_QUEST_TEXT_LENGTH
                )
                local progressText = usableTrackedQuestText(
                    progressLabel.Text,
                    MAX_TRACKED_QUEST_PROGRESS_LENGTH
                )
                local current, total = parseTrackedQuestProgress(progressText)
                if title and trackedTarget and current ~= nil and total ~= nil
                    and trackedTargetMatches(targetName, trackedTarget, firstSea)
                then
                    return {
                        Title = title,
                        Progress = tostring(current) .. "/" .. tostring(total),
                    }
                end
            end
        end

        if firstSea then
            local main = playerGui:FindFirstChild("Main")
            local questFrame = main and main:FindFirstChild("Quest")
            local container = questFrame and questFrame:FindFirstChild("Container")
            local questTitle = container and container:FindFirstChild("QuestTitle")
            local titleLabel = questTitle and questTitle:FindFirstChild("Title")
            if main and (not main:IsA("ScreenGui") or main.Enabled)
                and questFrame and questFrame:IsA("GuiObject") and questFrame.Visible
                and titleLabel and titleLabel:IsA("TextLabel") and titleLabel.Visible
            then
                local title = usableTrackedQuestText(
                    titleLabel.Text,
                    MAX_MAIN_QUEST_TITLE_LENGTH
                )
                local current, total = parseMainQuestTitleProgress(title)
                if title and current ~= nil and total ~= nil
                    and titleContainsTarget(title, targetName, true)
                then
                    return {
                        Title = title,
                        Progress = tostring(current) .. "/" .. tostring(total),
                    }
                end
            end
        end
        return nil
    end)

    if ok and type(guiDetails) == "table" then
        details.Title = guiDetails.Title or details.Title
        details.Progress = guiDetails.Progress or details.Progress
    end
    return details
end

function QuestService:SelectLevelQuest()
    local level = self:GetPlayerLevel()
    local guideData = self.Guide and self.Guide.Data
    local npcList = guideData and guideData.NPCList
    if not level or type(npcList) ~= "table" then
        return nil, "Player level or GuideModule.Data.NPCList is unavailable"
    end

    local bestLevel = 0
    local bestCandidate = nil
    for _, npcEntry in pairs(npcList) do
        if type(npcEntry) == "table" and not excludedQuestNames[npcEntry.InternalQuestName] then
            local questGroup = self.Quests[npcEntry.InternalQuestName]
            if type(npcEntry.Levels) == "table" and type(questGroup) == "table" then
                for questId, requiredLevel in pairs(npcEntry.Levels) do
                    local quest = questGroup[questId]
                    local numericLevel = tonumber(requiredLevel)
                    if type(quest) == "table"
                        and type(quest.Task) == "table"
                        and numericLevel
                        and numericLevel <= level
                        and numericLevel >= bestLevel
                    then
                        local mobName, count = next(quest.Task)
                        local numericCount = tonumber(count)
                        if type(mobName) == "string" and numericCount and numericCount > 1 then
                            bestCandidate = {
                                Level = numericLevel,
                                Name = npcEntry.NPCName,
                                QuestName = npcEntry.InternalQuestName,
                                Pos = npcEntry.Position,
                                Id = questId,
                                Mob = mobName,
                            }

                            local activeState, activeTarget = self:GetActiveQuestState()
                            local numericQuestId = tonumber(questId)
                            if activeState == "active"
                                and activeTarget == mobName
                                and numericQuestId
                                and numericQuestId > 1
                            then
                                local previousQuest = questGroup[numericQuestId - 1]
                                if previousQuest and type(previousQuest.Task) == "table" then
                                    for previousMob, previousCount in pairs(previousQuest.Task) do
                                        if previousMob ~= activeTarget
                                            and tonumber(previousCount)
                                            and tonumber(previousCount) > 1
                                        then
                                            bestCandidate.Mob = previousMob
                                            bestCandidate.Id = numericQuestId - 1
                                            break
                                        end
                                    end
                                end
                            end
                            bestLevel = numericLevel
                        end
                    end
                end
            end
        end
    end

    if not bestCandidate then
        return nil, "No eligible level-based quest candidate"
    end
    return bestCandidate
end

function QuestService:SelectPreviousLevelQuestTarget(activeTarget)
    if type(activeTarget) ~= "string" or activeTarget == "" then
        return nil, "Active quest target is unavailable"
    end

    local level = self:GetPlayerLevel()
    local guideData = self.Guide and self.Guide.Data
    local npcList = type(guideData) == "table" and guideData.NPCList or nil
    if not level or type(npcList) ~= "table" or type(self.Quests) ~= "table" then
        return nil, "Player level or quest catalog is unavailable"
    end

    local bestCurrentLevel = -1
    local bestCandidate = nil
    for _, npcEntry in pairs(npcList) do
        if type(npcEntry) == "table"
            and not excludedQuestNames[npcEntry.InternalQuestName]
            and type(npcEntry.Levels) == "table"
        then
            local questName = npcEntry.InternalQuestName
            local questGroup = type(questName) == "string" and self.Quests[questName] or nil
            if type(questGroup) == "table" then
                for questId, requiredLevel in pairs(npcEntry.Levels) do
                    local numericQuestId = tonumber(questId)
                    local currentLevel = tonumber(requiredLevel)
                    local currentQuest = questGroup[questId]
                        or (numericQuestId and questGroup[numericQuestId])
                    if numericQuestId and numericQuestId > 1
                        and currentLevel and currentLevel <= level
                        and currentLevel >= bestCurrentLevel
                        and type(currentQuest) == "table"
                        and type(currentQuest.Task) == "table"
                        and tonumber(currentQuest.Task[activeTarget])
                    then
                        local previousQuestId = numericQuestId - 1
                        local previousQuest = questGroup[previousQuestId]
                            or questGroup[tostring(previousQuestId)]
                        if type(previousQuest) == "table"
                            and type(previousQuest.Task) == "table"
                        then
                            local previousLevel = tonumber(previousQuest.LevelReq) or 0
                            for listedId, listedLevel in pairs(npcEntry.Levels) do
                                if tonumber(listedId) == previousQuestId then
                                    previousLevel = math.max(
                                        previousLevel,
                                        tonumber(listedLevel) or 0
                                    )
                                    break
                                end
                            end

                            if previousLevel <= level then
                                for previousMob, previousCount in pairs(previousQuest.Task) do
                                    if type(previousMob) == "string"
                                        and previousMob ~= activeTarget
                                        and tonumber(previousCount)
                                        and tonumber(previousCount) > 1
                                    then
                                        bestCurrentLevel = currentLevel
                                        bestCandidate = {
                                            Level = previousLevel,
                                            Name = npcEntry.NPCName,
                                            QuestName = questName,
                                            Pos = npcEntry.Position,
                                            Id = previousQuestId,
                                            Mob = previousMob,
                                        }
                                        break
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end

    if not bestCandidate then
        return nil, "No eligible previous quest target for the active quest"
    end
    return bestCandidate
end

function QuestService:GetQuestTargets(prefix, maximumLevel)
    if type(prefix) ~= "string" or prefix == "" then
        return nil, "Quest family prefix is invalid"
    end
    local levelLimit = tonumber(maximumLevel)
    if not levelLimit then
        return nil, "Player level is unavailable for quest target lookup"
    end

    local guideData = self.Guide and self.Guide.Data
    local npcList = type(guideData) == "table" and guideData.NPCList or nil
    if type(npcList) ~= "table" then
        return nil, "GuideModule.Data.NPCList is unavailable"
    end

    local targets = {}
    local seen = {}
    for _, npcEntry in pairs(npcList) do
        local questName = type(npcEntry) == "table" and npcEntry.InternalQuestName or nil
        local questGroup = type(questName) == "string"
            and questName:sub(1, #prefix) == prefix
            and self.Quests
            and self.Quests[questName]
            or nil
        if type(questGroup) == "table" and type(npcEntry.Levels) == "table" then
            for questId, requiredLevel in pairs(npcEntry.Levels) do
                local levelRequired = tonumber(requiredLevel)
                local quest = questGroup[questId] or questGroup[tostring(questId)]
                local task = type(quest) == "table" and quest.Task or nil
                if levelRequired and levelRequired <= levelLimit and type(task) == "table" then
                    for targetName, count in pairs(task) do
                        if type(targetName) == "string"
                            and targetName ~= ""
                            and tonumber(count)
                            and tonumber(count) > 0
                            and not seen[targetName]
                        then
                            seen[targetName] = true
                            table.insert(targets, targetName)
                        end
                    end
                end
            end
        end
    end

    table.sort(targets)
    if #targets == 0 then
        return nil, "No eligible targets were found in quest family " .. prefix
    end
    return targets
end

function QuestService:SelectQuest(questName, questId, minimumLevel)
    if type(questName) ~= "string" or questName == "" or questId == nil then
        return nil, "Special quest identity is invalid"
    end
    local level = self:GetPlayerLevel()
    local minimum = tonumber(minimumLevel)
    if not level or not minimum then
        return nil, "Player level or special quest level is unavailable"
    end
    if level < minimum then
        return nil, "Player level is below the selected mode's minimum"
    end

    local questGroup = self.Quests and self.Quests[questName]
    local quest = type(questGroup) == "table"
        and (questGroup[questId] or questGroup[tostring(questId)])
        or nil
    if type(quest) ~= "table" or type(quest.Task) ~= "table" then
        return nil, "The selected quest is missing from the live quest catalog"
    end
    local mobName, count = next(quest.Task)
    if type(mobName) ~= "string" or not tonumber(count) or tonumber(count) <= 0 then
        return nil, "The selected quest has no readable target"
    end

    local guideData = self.Guide and self.Guide.Data
    local npcList = type(guideData) == "table" and guideData.NPCList or nil
    if type(npcList) ~= "table" then
        return nil, "GuideModule.Data.NPCList is unavailable"
    end

    for _, npcEntry in pairs(npcList) do
        if type(npcEntry) == "table"
            and npcEntry.InternalQuestName == questName
            and type(npcEntry.Levels) == "table"
        then
            for listedQuestId, requiredLevel in pairs(npcEntry.Levels) do
                local npcLevel = tonumber(requiredLevel)
                if tostring(listedQuestId) == tostring(questId)
                    and npcLevel
                    and npcLevel <= level
                then
                    local catalogLevel = tonumber(quest.LevelReq)
                    local candidateLevel = math.max(npcLevel, catalogLevel or 0)
                    if candidateLevel > level then
                        return nil, "Player level does not satisfy the live quest catalog"
                    end
                    return {
                        Level = candidateLevel,
                        Name = npcEntry.NPCName,
                        QuestName = questName,
                        Pos = npcEntry.Position,
                        Id = questId,
                        Mob = mobName,
                    }
                end
            end
        end
    end
    return nil, "GuideModule does not expose the selected quest giver and position"
end

function QuestService:RequestStart(candidate)
    self.LastStartDiagnostic = {
        Stage = "pcall_not_reached",
        PcallSucceeded = nil,
        ResultType = "n/a",
        ResultSummary = "not returned",
    }
    if type(candidate) ~= "table" or not candidate.QuestName or candidate.Id == nil then
        self.LastStartDiagnostic.Stage = "candidate_invalid"
        return false, "Quest candidate is incomplete"
    end

    local commF, remoteError = self.Compatibility:GetCommF()
    if not commF then
        self.LastStartDiagnostic.Stage = "remote_unavailable"
        return false, remoteError
    end
    local ok, result = pcall(function()
        return commF:InvokeServer("StartQuest", tostring(candidate.QuestName), candidate.Id)
    end)
    pcall(function()
        self.LastStartDiagnostic = {
            Stage = "pcall_completed",
            PcallSucceeded = ok,
            ResultType = tostring(typeof(result)),
            ResultSummary = diagnosticScalarRepresentation(result),
        }
    end)
    if not ok then
        return false, tostring(result)
    end

    -- BNN ignores this return value; acceptance is confirmed separately through QuestData.Task.
    return true, result
end

return QuestService
-- END SOURCE: src/ReplicatedStorage/CustomHub/Features/Farm/QuestService.lua
end

__bundleFactories["CustomHub.Features.Farm.EnemyService"] = function()
-- BEGIN SOURCE: src/ReplicatedStorage/CustomHub/Features/Farm/EnemyService.lua
local EnemyService = {}
EnemyService.__index = EnemyService

local HIDDEN_SPAWN_REFRESH_INTERVAL = 5
local HIDDEN_SPAWN_RETRY_INTERVAL = 10
local HIDDEN_SPAWN_SCAN_CHUNK_SIZE = 64
local BRING_MOB_COOLDOWN = 0.75
local BRING_MOB_MAX_DISTANCE = 200
local BRING_MOB_PLAYER_RANGE = 50
local BRING_MOB_OTHER_PLAYER_RANGE = 300
local BRING_MOB_MIN_COUNT = 2
local BRING_MOB_MAX_COUNT = 6
local BRING_MOB_MAX_MOVES_PER_CALL = 2
local BRING_MOB_STUCK_HEALTH_TIMEOUT = 2.2

local function disconnect(connection)
    if connection then
        pcall(function()
            connection:Disconnect()
        end)
    end
end

local function singularizeEnemyWord(word)
    if #word > 3 and word:sub(-3) == "ies" then
        local stem = word:sub(1, -4)
        local lastStemCharacter = stem:sub(-1)
        if lastStemCharacter ~= "" and not lastStemCharacter:match("[aeiou]") then
            return stem .. "y"
        end
    end

    if #word > 4 and word:sub(-2) == "es" then
        local stem = word:sub(1, -3)
        if stem:sub(-1) == "s" or stem:sub(-1) == "x" or stem:sub(-1) == "z"
            or stem:sub(-2) == "ch" or stem:sub(-2) == "sh"
        then
            return stem
        end
    end

    local ending = word:sub(-2)
    if #word > 2 and word:sub(-1) == "s"
        and ending ~= "ss" and ending ~= "us" and ending ~= "is"
    then
        return word:sub(1, -2)
    end
    return word
end

local function normalizeEnemyName(name)
    if type(name) ~= "string" or #name == 0 then
        return nil
    end

    local baseName = name:lower():gsub("%s+%p?lv%.?%s*%d+%p?%s*$", "")
    local words = {}
    for word in baseName:gmatch("[%w]+") do
        table.insert(words, word)
    end
    if #words == 0 then
        return nil
    end

    words[#words] = singularizeEnemyWord(words[#words])
    return table.concat(words, " ")
end

local function normalizeTargetNames(targetNames)
    local normalized = {}
    if type(targetNames) == "string" then
        local name = normalizeEnemyName(targetNames)
        if name then
            table.insert(normalized, name)
        end
    elseif type(targetNames) == "table" then
        for _, targetName in ipairs(targetNames) do
            local name = normalizeEnemyName(targetName)
            if name then
                table.insert(normalized, name)
            end
        end
    end
    return normalized
end

local function isDescendantOf(instance, container)
    if not instance or not container then
        return false
    end
    local ok, result = pcall(function()
        return instance:IsDescendantOf(container)
    end)
    return ok and result == true
end

local function matchesSpawnName(spawnName, normalizedTargets)
    local normalizedName = normalizeEnemyName(spawnName)
    if not normalizedName then
        return false
    end
    for _, normalizedTarget in ipairs(normalizedTargets or {}) do
        if normalizedName == normalizedTarget then
            return true
        end
    end
    return false
end

local function matchedTargetName(spawnName, targetNames, normalizedTargets)
    for index, normalizedTarget in ipairs(normalizedTargets) do
        if normalizeEnemyName(spawnName) == normalizedTarget then
            if type(targetNames) == "string" then
                return targetNames
            end
            return targetNames[index]
        end
    end
    return nil
end

local function addNameIndexEntry(index, namesByInstance, instance)
    local normalizedName = normalizeEnemyName(instance.Name)
    if not normalizedName then
        namesByInstance[instance] = nil
        return
    end

    local bucket = index[normalizedName]
    if not bucket then
        bucket = setmetatable({}, { __mode = "k" })
        index[normalizedName] = bucket
    end
    bucket[instance] = true
    namesByInstance[instance] = normalizedName
end

local function removeNameIndexEntry(index, namesByInstance, instance)
    local normalizedName = namesByInstance[instance]
    local bucket = normalizedName and index[normalizedName]
    if bucket then
        bucket[instance] = nil
        if next(bucket) == nil then
            index[normalizedName] = nil
        end
    end
    namesByInstance[instance] = nil
end

function EnemyService.new(compatibility)
    return setmetatable({
        Compatibility = compatibility,
        Workspace = compatibility.Workspace,
        CollisionPartsByTarget = setmetatable({}, { __mode = "k" }),
        IgnoredSpawns = {},
        HiddenSpawnCache = nil,
        PreparedTargets = setmetatable({}, { __mode = "k" }),
        EnemyModels = setmetatable({}, { __mode = "k" }),
        EnemyModelsByName = {},
        EnemyModelNames = setmetatable({}, { __mode = "k" }),
        EnemyNameConnections = setmetatable({}, { __mode = "k" }),
        SpawnMarkers = setmetatable({}, { __mode = "k" }),
        SpawnMarkersByName = {},
        SpawnMarkerNames = setmetatable({}, { __mode = "k" }),
        BringMobNextAt = 0,
        BringMobTarget = nil,
        BringMobRecovery = setmetatable({}, { __mode = "k" }),
        BringMobRejected = setmetatable({}, { __mode = "k" }),
    }, EnemyService)
end

function EnemyService:_GetEnemySpawnsFolder()
    local worldOrigin = self.Workspace:FindFirstChild("_WorldOrigin")
    if not worldOrigin then
        worldOrigin = self.Workspace:FindFirstChild("_WorldOrigin", true)
    end
    if not worldOrigin then
        return self.Workspace:FindFirstChild("EnemySpawns", true)
    end

    local enemySpawns = worldOrigin:FindFirstChild("EnemySpawns")
    if not enemySpawns then
        enemySpawns = worldOrigin:FindFirstChild("EnemySpawns", true)
    end
    if not enemySpawns then
        enemySpawns = self.Workspace:FindFirstChild("EnemySpawns", true)
    end
    return enemySpawns
end

function EnemyService:_GetEnemyModelIndex()
    local enemies = self.Workspace:FindFirstChild("Enemies")
    if not enemies then
        enemies = self.Workspace:FindFirstChild("Enemies", true)
    end
    if enemies == self.EnemyContainer then
        return self.EnemyModels, enemies
    end

    disconnect(self.EnemyAddedConnection)
    disconnect(self.EnemyRemovingConnection)
    for _, connection in pairs(self.EnemyNameConnections) do
        disconnect(connection)
    end
    self.EnemyAddedConnection = nil
    self.EnemyRemovingConnection = nil
    self.EnemyContainer = enemies
    self.EnemyModels = setmetatable({}, { __mode = "k" })
    self.EnemyModelsByName = {}
    self.EnemyModelNames = setmetatable({}, { __mode = "k" })
    self.EnemyNameConnections = setmetatable({}, { __mode = "k" })
    if not enemies then
        return self.EnemyModels, nil
    end

    for _, instance in ipairs(enemies:GetDescendants()) do
        self:_IndexEnemyModel(instance)
    end
    self.EnemyAddedConnection = enemies.DescendantAdded:Connect(function(instance)
        self:_IndexEnemyModel(instance)
    end)
    self.EnemyRemovingConnection = enemies.DescendantRemoving:Connect(function(instance)
        self:_UnindexEnemyModel(instance)
    end)
    return self.EnemyModels, enemies
end

function EnemyService:_IndexEnemyModel(model)
    if not model:IsA("Model") then
        return
    end

    self.EnemyModels[model] = true
    removeNameIndexEntry(self.EnemyModelsByName, self.EnemyModelNames, model)
    addNameIndexEntry(self.EnemyModelsByName, self.EnemyModelNames, model)
    if self.EnemyNameConnections[model] then
        return
    end

    self.EnemyNameConnections[model] = model:GetPropertyChangedSignal("Name"):Connect(function()
        if not self.EnemyModels[model] then
            return
        end
        removeNameIndexEntry(self.EnemyModelsByName, self.EnemyModelNames, model)
        addNameIndexEntry(self.EnemyModelsByName, self.EnemyModelNames, model)
    end)
end

function EnemyService:_UnindexEnemyModel(model)
    if not model:IsA("Model") then
        return
    end
    self.EnemyModels[model] = nil
    removeNameIndexEntry(self.EnemyModelsByName, self.EnemyModelNames, model)
    disconnect(self.EnemyNameConnections[model])
    self.EnemyNameConnections[model] = nil
end

function EnemyService:_GetSpawnMarkerIndex()
    local enemySpawns = self:_GetEnemySpawnsFolder()
    if enemySpawns == self.SpawnContainer then
        return self.SpawnMarkers, enemySpawns
    end

    disconnect(self.SpawnAddedConnection)
    disconnect(self.SpawnRemovingConnection)
    self.SpawnAddedConnection = nil
    self.SpawnRemovingConnection = nil
    self.SpawnContainer = enemySpawns
    self.SpawnMarkers = setmetatable({}, { __mode = "k" })
    self.SpawnMarkersByName = {}
    self.SpawnMarkerNames = setmetatable({}, { __mode = "k" })
    if not enemySpawns then
        return self.SpawnMarkers, nil
    end

    for _, instance in ipairs(enemySpawns:GetDescendants()) do
        self:_IndexSpawnMarker(instance)
    end
    self.SpawnAddedConnection = enemySpawns.DescendantAdded:Connect(function(instance)
        self:_IndexSpawnMarker(instance)
    end)
    self.SpawnRemovingConnection = enemySpawns.DescendantRemoving:Connect(function(instance)
        self:_UnindexSpawnMarker(instance)
    end)
    return self.SpawnMarkers, enemySpawns
end

function EnemyService:_IndexSpawnMarker(spawnPart)
    if not spawnPart:IsA("BasePart") then
        return
    end
    self.SpawnMarkers[spawnPart] = true
    removeNameIndexEntry(self.SpawnMarkersByName, self.SpawnMarkerNames, spawnPart)
    addNameIndexEntry(self.SpawnMarkersByName, self.SpawnMarkerNames, spawnPart)
end

function EnemyService:_UnindexSpawnMarker(spawnPart)
    if not spawnPart:IsA("BasePart") then
        return
    end
    self.SpawnMarkers[spawnPart] = nil
    removeNameIndexEntry(self.SpawnMarkersByName, self.SpawnMarkerNames, spawnPart)
end

function EnemyService:_RefreshHiddenSpawnCache()
    local now = os.clock()
    local current = self.HiddenSpawnCache
    if current and (current.Loading or now < current.ExpiresAt) then
        return current
    end

    local cache = {
        Parts = {},
        ByName = {},
        Available = false,
        Loading = true,
        ExpiresAt = math.huge,
    }
    self.HiddenSpawnCache = cache

    local function markUnavailable()
        if self.HiddenSpawnCache == cache then
            cache.Available = false
            cache.Loading = false
            cache.ExpiresAt = os.clock() + HIDDEN_SPAWN_RETRY_INTERVAL
        end
    end

    task.defer(function()
        local getter = self.Compatibility and self.Compatibility.GetUnparentedInstances
        if type(getter) ~= "function" then
            markUnavailable()
            return
        end

        local callOk, instances = pcall(getter, self.Compatibility)
        if not callOk or type(instances) ~= "table" or self.HiddenSpawnCache ~= cache then
            markUnavailable()
            return
        end

        cache.Available = true
        local scanned = 0
        for _, instance in pairs(instances) do
            if self.HiddenSpawnCache ~= cache then
                return
            end

            local readOk, isBasePart, name, parent = pcall(function()
                return instance:IsA("BasePart"), instance.Name, instance.Parent
            end)
            if readOk and isBasePart and parent == nil and type(name) == "string" then
                cache.Parts[instance] = name
                local normalizedName = normalizeEnemyName(name)
                if normalizedName then
                    local matches = cache.ByName[normalizedName]
                    if not matches then
                        matches = {}
                        cache.ByName[normalizedName] = matches
                    end
                    table.insert(matches, instance)
                end
            end

            scanned += 1
            if scanned % HIDDEN_SPAWN_SCAN_CHUNK_SIZE == 0 then
                task.wait()
            end
        end

        if self.HiddenSpawnCache == cache then
            cache.Loading = false
            cache.ExpiresAt = os.clock() + HIDDEN_SPAWN_REFRESH_INTERVAL
        end
    end)

    return cache
end

function EnemyService:_PruneIgnoredSpawns(enemySpawns, hiddenCache, targetName)
    local normalizedTarget = normalizeTargetNames(targetName)
    for spawnPart in pairs(self.IgnoredSpawns) do
        local readOk, isBasePart, name, parent = pcall(function()
            return spawnPart:IsA("BasePart"), spawnPart.Name, spawnPart.Parent
        end)
        local matchingName = readOk
            and isBasePart
            and type(name) == "string"
            and matchesSpawnName(name, normalizedTarget)
        local replicated = matchingName
            and enemySpawns ~= nil
            and parent ~= nil
            and isDescendantOf(spawnPart, enemySpawns)
        local hidden = matchingName
            and parent == nil
            and hiddenCache.Available
            and hiddenCache.Parts[spawnPart] == name
        if not replicated and not hidden then
            self.IgnoredSpawns[spawnPart] = nil
        end
    end
end

function EnemyService:IsAlive(model)
    if not model or not model.Parent then
        return false
    end
    local root = model:FindFirstChild("HumanoidRootPart")
    local humanoid = model:FindFirstChildWhichIsA("Humanoid")
    return root ~= nil and humanoid ~= nil and humanoid.Health > 0
end

function EnemyService:FindNearest(targetName, origin)
    local enemyModels, enemies = self:_GetEnemyModelIndex()
    local normalizedTargets = normalizeTargetNames(targetName)
    if not enemies or #normalizedTargets == 0 or not origin then
        return nil
    end

    local nearest, nearestDistance = nil, math.huge
    local seen = {}
    for _, normalizedName in ipairs(normalizedTargets) do
        for enemy in pairs(self.EnemyModelsByName[normalizedName] or {}) do
            if not seen[enemy] then
                seen[enemy] = true
                if enemyModels[enemy] and isDescendantOf(enemy, enemies) then
                    local root = enemy:FindFirstChild("HumanoidRootPart")
                    local humanoid = enemy:FindFirstChildWhichIsA("Humanoid")
                    if root and humanoid and humanoid.Health > 0 then
                        local distance = (root.Position - origin).Magnitude
                        if distance < nearestDistance then
                            nearest, nearestDistance = enemy, distance
                        end
                    end
                end
            end
        end
    end
    return nearest, nearestDistance
end

function EnemyService:FindNearestInRange(origin, maxDistance)
    if typeof(origin) ~= "Vector3" then
        return nil
    end
    local radius = tonumber(maxDistance)
    if not radius or radius < 0 or radius ~= radius or math.abs(radius) == math.huge then
        return nil
    end

    local enemyModels, enemies = self:_GetEnemyModelIndex()
    if not enemies then
        return nil
    end

    local nearest, nearestDistance = nil, radius
    for enemy in pairs(enemyModels) do
        if isDescendantOf(enemy, enemies) and self:IsAlive(enemy) then
            local distance = (enemy.HumanoidRootPart.Position - origin).Magnitude
            if distance <= nearestDistance then
                nearest, nearestDistance = enemy, distance
            end
        end
    end
    return nearest, nearestDistance
end

function EnemyService:FindSpawn(targetName, origin)
    local diagnostic = {
        TargetName = type(targetName) == "string" and targetName or "multiple quest targets",
        EnemySpawnsContainerFound = false,
        NormalMarkerFound = false,
        HiddenMarkerFound = false,
        HiddenDiscoveryAvailable = false,
        HiddenDiscoveryChecked = false,
        SelectedSource = "none",
        SelectedName = nil,
        MatchedTarget = nil,
        SelectedDistance = nil,
    }
    local normalizedTarget = normalizeTargetNames(targetName)
    if #normalizedTarget == 0 then
        return nil, false, diagnostic
    end

    local _, enemySpawns = self:_GetSpawnMarkerIndex()
    local now = os.clock()
    local hiddenCache = self.HiddenSpawnCache
    if hiddenCache and not hiddenCache.Loading and now >= hiddenCache.ExpiresAt then
        hiddenCache = nil
    end
    diagnostic.EnemySpawnsContainerFound = enemySpawns ~= nil
    diagnostic.HiddenDiscoveryChecked = hiddenCache ~= nil
    diagnostic.HiddenDiscoveryAvailable = hiddenCache ~= nil
        and hiddenCache.Available == true
    diagnostic.HiddenDiscoveryLoading = hiddenCache ~= nil
        and hiddenCache.Loading == true
    self:_PruneIgnoredSpawns(
        enemySpawns,
        hiddenCache or { Available = false, Parts = {} },
        targetName
    )

    local hasMatchingSpawn = false
    local nearest, nearestDistance = nil, math.huge
    local function considerSpawn(spawnPart, expectedParent, expectedName, source)
        local readOk, isBasePart, name, parent, position = pcall(function()
            return spawnPart:IsA("BasePart"), spawnPart.Name, spawnPart.Parent, spawnPart.Position
        end)
        local inExpectedContainer = source == "EnemySpawns"
            and isDescendantOf(spawnPart, expectedParent)
        local inHiddenCache = source == "unparented-cache" and parent == nil
        if not readOk
            or not isBasePart
            or (source == "EnemySpawns" and not inExpectedContainer)
            or (source == "unparented-cache" and not inHiddenCache)
            or type(name) ~= "string"
            or (expectedName and name ~= expectedName)
            or not matchesSpawnName(name, normalizedTarget)
        then
            return
        end

        hasMatchingSpawn = true
        if source == "EnemySpawns" then
            diagnostic.NormalMarkerFound = true
        elseif source == "unparented-cache" then
            diagnostic.HiddenMarkerFound = true
        end
        if self.IgnoredSpawns[spawnPart] then
            return
        end
        local distance = typeof(origin) == "Vector3"
            and (position - origin).Magnitude
            or 0
        if distance < nearestDistance then
            nearest, nearestDistance = spawnPart, distance
            diagnostic.SelectedSource = source
            diagnostic.SelectedName = name
            diagnostic.MatchedTarget = matchedTargetName(name, targetName, normalizedTarget)
            diagnostic.SelectedDistance = distance
        end
    end

    if enemySpawns then
        local seenNormal = {}
        for _, normalizedName in ipairs(normalizedTarget) do
            for spawnPart in pairs(self.SpawnMarkersByName[normalizedName] or {}) do
                if not seenNormal[spawnPart] then
                    seenNormal[spawnPart] = true
                    considerSpawn(spawnPart, enemySpawns, nil, "EnemySpawns")
                end
            end
        end
    end

    -- Only enumerate all unparented runtime instances if the normal marker index
    -- cannot provide a candidate. A valid cached fallback remains usable meanwhile.
    if not hiddenCache and not nearest then
        hiddenCache = self:_RefreshHiddenSpawnCache()
        diagnostic.HiddenDiscoveryChecked = true
        diagnostic.HiddenDiscoveryAvailable = hiddenCache.Available == true
        diagnostic.HiddenDiscoveryLoading = hiddenCache.Loading == true
    end

    if hiddenCache
        and hiddenCache.Available
        and not hiddenCache.Loading
        and os.clock() < hiddenCache.ExpiresAt
    then
        local seenHidden = {}
        for _, normalizedName in ipairs(normalizedTarget) do
            for _, spawnPart in ipairs(hiddenCache.ByName[normalizedName] or {}) do
                local cachedName = hiddenCache.Parts[spawnPart]
                if cachedName and not seenHidden[spawnPart] then
                    seenHidden[spawnPart] = true
                    considerSpawn(spawnPart, nil, cachedName, "unparented-cache")
                end
            end
        end
    end

    if nearest then
        return nearest, false, diagnostic, diagnostic.MatchedTarget
    end
    return nil, hasMatchingSpawn, diagnostic, nil
end

function EnemyService:IsSpawnAvailable(spawnPart, targetName)
    if not spawnPart then
        return false
    end
    local readOk, isBasePart, name, parent = pcall(function()
        return spawnPart:IsA("BasePart"), spawnPart.Name, spawnPart.Parent
    end)
    if not readOk
        or not isBasePart
        or type(name) ~= "string"
        or self.IgnoredSpawns[spawnPart]
    then
        return false
    end

    local normalizedTarget = normalizeTargetNames(targetName)
    if not matchesSpawnName(name, normalizedTarget) then
        return false
    end

    local enemySpawns = self:_GetEnemySpawnsFolder()
    if enemySpawns ~= nil and parent ~= nil and isDescendantOf(spawnPart, enemySpawns) then
        return true
    end

    local hiddenCache = self.HiddenSpawnCache
    return parent == nil
        and hiddenCache ~= nil
        and hiddenCache.Available
        and os.clock() < hiddenCache.ExpiresAt
        and hiddenCache.Parts[spawnPart] == name
end

function EnemyService:MarkSpawnIgnored(spawnPart, targetName)
    if self:IsSpawnAvailable(spawnPart, targetName) then
        self.IgnoredSpawns[spawnPart] = true
    end
end

function EnemyService:ClearIgnoredSpawns()
    table.clear(self.IgnoredSpawns)
end

function EnemyService:ClearTracking()
    disconnect(self.EnemyAddedConnection)
    disconnect(self.EnemyRemovingConnection)
    disconnect(self.SpawnAddedConnection)
    disconnect(self.SpawnRemovingConnection)
    for _, connection in pairs(self.EnemyNameConnections) do
        disconnect(connection)
    end
    self.EnemyAddedConnection = nil
    self.EnemyRemovingConnection = nil
    self.SpawnAddedConnection = nil
    self.SpawnRemovingConnection = nil
    self.EnemyContainer = nil
    self.SpawnContainer = nil
    self.EnemyModels = setmetatable({}, { __mode = "k" })
    self.EnemyModelsByName = {}
    self.EnemyModelNames = setmetatable({}, { __mode = "k" })
    self.EnemyNameConnections = setmetatable({}, { __mode = "k" })
    self.SpawnMarkers = setmetatable({}, { __mode = "k" })
    self.SpawnMarkersByName = {}
    self.SpawnMarkerNames = setmetatable({}, { __mode = "k" })
    self.HiddenSpawnCache = nil
    self.BringMobNextAt = 0
    self.BringMobTarget = nil
    self.BringMobRecovery = setmetatable({}, { __mode = "k" })
    self.BringMobRejected = setmetatable({}, { __mode = "k" })
    table.clear(self.PreparedTargets)
end

function EnemyService:_HasNearbyOtherPlayer(position)
    local players = self.Compatibility and self.Compatibility.Players
    local localPlayer = self.Compatibility and self.Compatibility.Player
    if not players or type(players.GetPlayers) ~= "function" then
        return false
    end

    for _, player in ipairs(players:GetPlayers()) do
        if player ~= localPlayer then
            local character = player.Character
            local otherRoot = character and character:FindFirstChild("HumanoidRootPart")
            if otherRoot and otherRoot:IsA("BasePart")
                and (otherRoot.Position - position).Magnitude <= BRING_MOB_OTHER_PLAYER_RANGE
            then
                return true
            end
        end
    end
    return false
end

function EnemyService:_WatchBroughtMob(model, target, originalRootCFrame, healthBefore)
    local recovery = {
        Target = target,
        OriginalRootCFrame = originalRootCFrame,
        HealthBefore = healthBefore,
    }
    self.BringMobRecovery[model] = recovery

    task.delay(BRING_MOB_STUCK_HEALTH_TIMEOUT, function()
        if self.BringMobRecovery[model] ~= recovery then
            return
        end
        self.BringMobRecovery[model] = nil

        if not self:IsAlive(model) or not isDescendantOf(model, self.EnemyContainer) then
            return
        end
        local humanoid = model:FindFirstChildWhichIsA("Humanoid")
        local modelRoot = model:FindFirstChild("HumanoidRootPart")
        local targetRoot = recovery.Target
            and recovery.Target:FindFirstChild("HumanoidRootPart")
        if not humanoid or humanoid.Health < recovery.HealthBefore
            or not modelRoot or not modelRoot:IsA("BasePart")
            or not targetRoot or not targetRoot:IsA("BasePart")
            or (modelRoot.Position - targetRoot.Position).Magnitude > 50
        then
            return
        end

        local restored = pcall(function()
            modelRoot.CFrame = recovery.OriginalRootCFrame
        end)
        if restored then
            -- Keep this NPC out of future bring attempts for this session rather
            -- than adding an "Ignored" instance that changes normal farm targeting.
            self.BringMobRejected[model] = true
        end
    end)
end

function EnemyService:BringMatchingMob(target, playerRoot, requestedCount)
    if not self:IsAlive(target) or not playerRoot or not self.EnemyContainer then
        return 0
    end
    local desiredCount = tonumber(requestedCount) or BRING_MOB_MIN_COUNT
    if desiredCount ~= desiredCount or math.abs(desiredCount) == math.huge then
        desiredCount = BRING_MOB_MIN_COUNT
    end
    desiredCount = math.clamp(
        math.floor(desiredCount + 0.5),
        BRING_MOB_MIN_COUNT,
        BRING_MOB_MAX_COUNT
    )

    local targetRoot = target:FindFirstChild("HumanoidRootPart")
    if not targetRoot or not targetRoot:IsA("BasePart")
        or (targetRoot.Position - playerRoot.Position).Magnitude > BRING_MOB_PLAYER_RANGE
    then
        return 0
    end

    local now = os.clock()
    if self.BringMobTarget == target and now < self.BringMobNextAt then
        return 0
    end
    self.BringMobTarget = target
    self.BringMobNextAt = now + BRING_MOB_COOLDOWN

    local normalizedName = normalizeEnemyName(target.Name)
    if not normalizedName then
        return 0
    end
    local bucket = self.EnemyModelsByName[normalizedName] or {}
    local nearbyCount = 1
    local candidates = {}
    local candidateLimit = desiredCount - 1
    for enemy in pairs(bucket) do
        if enemy ~= target
            and enemy.Name == target.Name
            and isDescendantOf(enemy, self.EnemyContainer)
            and not enemy:FindFirstChild("Ignored")
            and not self.BringMobRejected[enemy]
            and not self.BringMobRecovery[enemy]
            and self:IsAlive(enemy)
        then
            local enemyRoot = enemy:FindFirstChild("HumanoidRootPart")
            if enemyRoot and enemyRoot:IsA("BasePart") and not enemyRoot.Anchored then
                local distance = (enemyRoot.Position - targetRoot.Position).Magnitude
                -- This nearby-player check follows the reference hubs' conservative
                -- guard; it is not a guarantee of client network ownership.
                if distance <= 8 then
                    nearbyCount += 1
                elseif distance <= BRING_MOB_MAX_DISTANCE
                    and not self:_HasNearbyOtherPlayer(enemyRoot.Position)
                then
                    local candidate = { Model = enemy, Distance = distance }
                    local insertAt = #candidates + 1
                    while insertAt > 1
                        and candidates[insertAt - 1].Distance > distance
                    do
                        insertAt -= 1
                    end
                    table.insert(candidates, insertAt, candidate)
                    if #candidates > candidateLimit then
                        table.remove(candidates)
                    end
                end
            end
        end
    end

    if nearbyCount >= desiredCount or #candidates == 0 then
        return 0
    end

    -- Honor larger requested groups gradually so one farm tick never moves many NPCs.
    local movesRemaining = math.min(
        desiredCount - nearbyCount,
        BRING_MOB_MAX_MOVES_PER_CALL,
        #candidates
    )
    local movedCount = 0
    for index = 1, movesRemaining do
        local candidateModel = candidates[index].Model
        local candidateRoot = candidateModel:FindFirstChild("HumanoidRootPart")
        local candidateHumanoid = candidateModel:FindFirstChildWhichIsA("Humanoid")
        if candidateRoot and candidateRoot:IsA("BasePart") and not candidateRoot.Anchored then
            local originalRootCFrame = candidateRoot.CFrame
            local healthBefore = candidateHumanoid and candidateHumanoid.Health
            local moved = pcall(function()
                candidateRoot.CFrame = targetRoot.CFrame * CFrame.new(3 + (index - 1) * 2, 0, 0)
            end)
            if moved then
                movedCount += 1
                if candidateHumanoid and type(healthBefore) == "number" then
                    self:_WatchBroughtMob(
                        candidateModel,
                        target,
                        originalRootCFrame,
                        healthBefore
                    )
                end
            end
        end
    end
    return movedCount
end

function EnemyService:PrepareTarget(model, playerRoot)
    if not self:IsAlive(model) or not playerRoot then
        return
    end
    if (model.HumanoidRootPart.Position - playerRoot.Position).Magnitude > 50 then
        return
    end

    if self.PreparedTargets[model] then
        return
    end
    local targetParts = {}
    for _, part in ipairs(model:GetDescendants()) do
        if part:IsA("BasePart") and part.CanCollide then
            targetParts[part] = part.CanCollide
            part.CanCollide = false
        end
    end
    self.CollisionPartsByTarget[model] = targetParts
    self.PreparedTargets[model] = true
end

function EnemyService:RestoreTargetCollision(target)
    if target then
        local targetParts = self.CollisionPartsByTarget[target]
        if targetParts then
            local shouldRestore = target.Parent ~= nil
            if shouldRestore then
                local humanoid = target:FindFirstChildWhichIsA("Humanoid")
                if humanoid and humanoid.Health <= 0 then
                    shouldRestore = false
                end
            end

            if shouldRestore then
                for part, originalCanCollide in pairs(targetParts) do
                    if part.Parent and part.CanCollide ~= originalCanCollide then
                        part.CanCollide = originalCanCollide
                    end
                end
            end
        end
        self.CollisionPartsByTarget[target] = nil
        self.PreparedTargets[target] = nil
        return
    end

    for targetModel, targetParts in pairs(self.CollisionPartsByTarget) do
        for part, originalCanCollide in pairs(targetParts) do
            if part.Parent and part.CanCollide ~= originalCanCollide then
                part.CanCollide = originalCanCollide
            end
        end
        self.CollisionPartsByTarget[targetModel] = nil
    end
    table.clear(self.PreparedTargets)
    table.clear(self.CollisionPartsByTarget)
end

return EnemyService
-- END SOURCE: src/ReplicatedStorage/CustomHub/Features/Farm/EnemyService.lua
end

__bundleFactories["CustomHub.Features.Farm.MovementService"] = function()
-- BEGIN SOURCE: src/ReplicatedStorage/CustomHub/Features/Farm/MovementService.lua
local MovementService = {}
MovementService.__index = MovementService

local SUBMERGED_REFERENCE = Vector3.new(11538.599609375, -2154.7021484375, 9827.3125)
local TIKI_OUTPOST_REFERENCE = Vector3.new(-16204, 10, 479)
local SUBMERGED_STAGING = CFrame.new(
    -16269.4082,
    23.9799957,
    1371.66235,
    -0.999388933,
    0,
    -0.0349550731,
    0,
    1,
    0,
    0.0349550731,
    0,
    -0.999388933
)
local TIKI_STAGING = CFrame.new(
    11427.9189,
    -2156.36401,
    9726.24023,
    -0.929097056,
    -7.17796156E-34,
    0.369835705,
    -7.17796156E-34,
    1,
    1.37611875E-34,
    -0.369835705,
    -1.37611875E-34,
    -0.929097056
)
local function disconnect(connection)
    if connection then
        pcall(function()
            connection:Disconnect()
        end)
    end
end

local function formatPosition(position)
    return string.format("(%.1f, %.1f, %.1f)", position.X, position.Y, position.Z)
end

function MovementService.new(compatibility, report)
    return setmetatable({
        Compatibility = compatibility,
        Report = report,
        Active = nil,
        Generation = 0,
        RouteGeneration = 0,
        TagGeneration = 0,
        OwnsTeleportTag = false,
        LastRouteRequest = {},
        FarmCollisionActive = false,
        FarmCollisionCharacter = nil,
        FarmCollisionCharacterAddedConnection = nil,
        FarmCollisionCharacterRemovingConnection = nil,
        FarmCollisionDescendantAddedConnection = nil,
        FarmCollisionSteppedConnection = nil,
        FarmCollisionOriginals = {},
        FarmCollisionPartConnections = {},
        FarmCollisionErrorReported = false,
        FarmCollisionMaintenanceGeneration = 0,
        HoldForce = nil,
        LastStallDiagnostic = nil,
    }, MovementService)
end

function MovementService:_GetRoute(destination, currentPosition)
    if not self.Compatibility:IsThirdSea() then
        return nil
    end

    local destinationDistance = (destination.Position - SUBMERGED_REFERENCE).Magnitude
    local currentDistance = (currentPosition - SUBMERGED_REFERENCE).Magnitude
    if destinationDistance <= 3000 and currentDistance > 3000 then
        return {
            Name = "Submerged",
            Stage = SUBMERGED_STAGING,
            ArrivalReference = SUBMERGED_REFERENCE,
            ArrivalRadius = 3000,
        }
    end
    if destinationDistance > 3000 and currentDistance <= 3000 then
        return {
            Name = "Tiki",
            Stage = TIKI_STAGING,
            ArrivalReference = TIKI_OUTPOST_REFERENCE,
            ArrivalRadius = 3000,
        }
    end
    return nil
end

function MovementService:GetSpecialTravelRoute(destination, currentPosition)
    return self:_GetRoute(destination, currentPosition)
end

function MovementService:RequestSpecialTravelRoute(route, isCurrent)
    if type(route) ~= "table" or (route.Name ~= "Submerged" and route.Name ~= "Tiki") then
        return false, "Unsupported special travel route"
    end
    if type(isCurrent) ~= "function" then
        isCurrent = function()
            return true
        end
    end
    return self:_RequestRoute(route, isCurrent, self.RouteGeneration)
end

function MovementService:_RestoreCollision(active)
    for part, canCollide in pairs(active.CollisionOriginals) do
        if part and part.Parent then
            part.CanCollide = canCollide
        end
        active.CollisionOriginals[part] = nil
    end
end

function MovementService:_RestoreFarmCollision()
    disconnect(self.FarmCollisionDescendantAddedConnection)
    self.FarmCollisionDescendantAddedConnection = nil
    for part, canCollide in pairs(self.FarmCollisionOriginals) do
        disconnect(self.FarmCollisionPartConnections[part])
        self.FarmCollisionPartConnections[part] = nil
        pcall(function()
            if part.Parent then
                part.CanCollide = canCollide
            end
        end)
    end
    table.clear(self.FarmCollisionOriginals)
    self.FarmCollisionCharacter = nil
end

function MovementService:_ReportFarmCollisionError(err)
    if self.FarmCollisionErrorReported or not self.Report then
        return
    end
    self.FarmCollisionErrorReported = true
    self.Report("Character collision maintenance error: " .. tostring(err), "warning")
end

function MovementService:_CaptureStallDiagnostic(active, root, goal, distance)
    local collisionParts = {}
    local collidableParts = {}
    local collidableCount = 0
    local seenParts = {}
    local function inspectPart(part)
        if not part or seenParts[part] or not part.Parent then
            return
        end
        seenParts[part] = true
        collisionParts[#collisionParts + 1] = part
        if part.CanCollide then
            collidableCount += 1
            if #collidableParts < 5 then
                collidableParts[#collidableParts + 1] = part.Name
            end
        end
    end

    for part in pairs(self.FarmCollisionOriginals) do
        inspectPart(part)
    end
    for part in pairs(active.CollisionOriginals or {}) do
        inspectPart(part)
    end

    local obstacle = "no hit within 30 studs"
    local raycastOk, raycastResult = pcall(function()
        local offset = goal.Position - root.Position
        local castDistance = math.min(offset.Magnitude, 30)
        if castDistance <= 0 then
            return nil
        end
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        params.FilterDescendantsInstances = { active.Character }
        return self.Compatibility.Workspace:Raycast(
            root.Position,
            offset.Unit * castDistance,
            params
        )
    end)
    if not raycastOk then
        obstacle = "raycast unavailable: " .. tostring(raycastResult)
    elseif raycastResult then
        local instance = raycastResult.Instance
        local canCollide = "n/a"
        if instance:IsA("BasePart") then
            canCollide = tostring(instance.CanCollide)
        end
        obstacle = string.format(
            "hit=%s (%s); distance=%.1f; CanCollide=%s; material=%s",
            tostring(instance.Name),
            tostring(instance.ClassName),
            raycastResult.Distance,
            canCollide,
            tostring(raycastResult.Material)
        )
    end

    local correctionDistance = active.LastCommandError
        and string.format("%.1f studs", active.LastCommandError)
        or "not available"
    local collidableSummary = #collidableParts > 0
        and table.concat(collidableParts, ", ")
        or "none"
    local lines = {
        "===== [MovementStallDiagnostic] REPORT BEGIN =====",
        string.format("Stall duration: %.2f seconds", os.clock() - active.LastProgressAt),
        string.format("Root position: %s", formatPosition(root.Position)),
        string.format("Goal position: %s; current distance=%.1f studs", formatPosition(goal.Position), distance),
        "Tracked character parts: "
            .. tostring(#collisionParts)
            .. "; currently collidable: "
            .. tostring(collidableCount)
            .. "; examples: "
            .. collidableSummary,
        "Distance from last commanded position: " .. correctionDistance,
        "Forward obstacle check: " .. obstacle,
        "A clear ray only describes the corridor; it does not confirm the root accepted position commands.",
        "===== [MovementStallDiagnostic] REPORT END =====",
    }
    local text = table.concat(lines, "\n")
    self.LastStallDiagnostic = {
        At = os.clock(),
        Text = text,
    }
    return text
end

function MovementService:_MaintainFarmCollision()
    if not self.FarmCollisionActive then
        return
    end

    local player = self.Compatibility.Player
    if player and player.Character ~= self.FarmCollisionCharacter then
        self:_ApplyFarmCollision()
        return
    end

    for part in pairs(self.FarmCollisionOriginals) do
        if not part.Parent then
            disconnect(self.FarmCollisionPartConnections[part])
            self.FarmCollisionPartConnections[part] = nil
            self.FarmCollisionOriginals[part] = nil
        elseif part.CanCollide then
            self:_ApplyFarmCollisionPart(part)
        end
    end
end

function MovementService:_StartFarmCollisionMaintenance()
    self.FarmCollisionMaintenanceGeneration += 1
    local generation = self.FarmCollisionMaintenanceGeneration
    disconnect(self.FarmCollisionSteppedConnection)
    self.FarmCollisionSteppedConnection = self.Compatibility.RunService.Stepped:Connect(function()
        if not self.FarmCollisionActive
            or self.FarmCollisionMaintenanceGeneration ~= generation
        then
            return
        end

        -- Reassert collision suppression before each physics step, but only
        -- across the cached, event-maintained character parts. This prevents
        -- game scripts from restoring CanCollide between low-frequency checks
        -- without rescanning the character hierarchy every frame.
        do
            local ok, err = pcall(self._MaintainFarmCollision, self)
            if ok then
                self.FarmCollisionErrorReported = false
            else
                self:_ReportFarmCollisionError(err)
            end
        end
    end)
end

function MovementService:_ApplyFarmCollisionPart(part)
    if not self.FarmCollisionActive or not part:IsA("BasePart") then
        return
    end

    if self.FarmCollisionOriginals[part] == nil then
        self.FarmCollisionOriginals[part] = part.CanCollide
        self.FarmCollisionPartConnections[part] =
            part:GetPropertyChangedSignal("CanCollide"):Connect(function()
                if self.FarmCollisionActive and part.Parent and part.CanCollide then
                    part.CanCollide = false
                end
            end)
    end
    if part.CanCollide then
        part.CanCollide = false
    end
end

function MovementService:_ApplyFarmCollision()
    if not self.FarmCollisionActive then
        return true
    end

    local player = self.Compatibility.Player
    local character = player and player.Character
    if character == self.FarmCollisionCharacter then
        return true
    end

    self:_RestoreFarmCollision()
    self.FarmCollisionCharacter = character
    if not character then
        return true
    end

    self.FarmCollisionDescendantAddedConnection = character.DescendantAdded:Connect(function(descendant)
        local ok, err = pcall(self._ApplyFarmCollisionPart, self, descendant)
        if ok then
            self.FarmCollisionErrorReported = false
        else
            self:_ReportFarmCollisionError(err)
        end
    end)
    for _, descendant in ipairs(character:GetDescendants()) do
        self:_ApplyFarmCollisionPart(descendant)
    end
    return true
end

function MovementService:SetFarmCollisionSuppression(enabled)
    enabled = enabled == true
    if not enabled then
        self.FarmCollisionActive = false
        self.FarmCollisionMaintenanceGeneration += 1
        disconnect(self.FarmCollisionSteppedConnection)
        self.FarmCollisionSteppedConnection = nil
        disconnect(self.FarmCollisionCharacterAddedConnection)
        disconnect(self.FarmCollisionCharacterRemovingConnection)
        self.FarmCollisionCharacterAddedConnection = nil
        self.FarmCollisionCharacterRemovingConnection = nil
        self:_RestoreFarmCollision()
        self.FarmCollisionErrorReported = false
        return true
    end

    if self.FarmCollisionActive then
        local ok, err = pcall(self._ApplyFarmCollision, self)
        if not ok then
            return false, tostring(err)
        end
        return true
    end

    self.FarmCollisionActive = true
    local ok, err = pcall(function()
        self:_ApplyFarmCollision()
        local player = self.Compatibility.Player
        if player then
            self.FarmCollisionCharacterAddedConnection = player.CharacterAdded:Connect(function()
                local applyOk, applyError = pcall(self._ApplyFarmCollision, self)
                if applyOk then
                    self.FarmCollisionErrorReported = false
                else
                    self:_ReportFarmCollisionError(applyError)
                end
            end)
            self.FarmCollisionCharacterRemovingConnection =
                player.CharacterRemoving:Connect(function(character)
                    if self.FarmCollisionCharacter == character then
                        self:_RestoreFarmCollision()
                    end
                end)
        end
    end)
    if not ok then
        self.FarmCollisionActive = false
        self.FarmCollisionMaintenanceGeneration += 1
        disconnect(self.FarmCollisionSteppedConnection)
        self.FarmCollisionSteppedConnection = nil
        disconnect(self.FarmCollisionCharacterAddedConnection)
        disconnect(self.FarmCollisionCharacterRemovingConnection)
        self.FarmCollisionCharacterAddedConnection = nil
        self.FarmCollisionCharacterRemovingConnection = nil
        self:_RestoreFarmCollision()
        return false, tostring(err)
    end

    self.FarmCollisionErrorReported = false
    self:_StartFarmCollisionMaintenance()
    return true
end

function MovementService:_Finish(active, delayTagRemoval)
    if self.Active ~= active then
        return
    end
    self.Active = nil
    if active.Connection and active.Connection.Connected then
        active.Connection:Disconnect()
    end
    self:_RestoreCollision(active)

    if active.FloatForce and active.FloatForce.Parent then
        active.FloatForce:Destroy()
    end
    if active.Humanoid and active.Humanoid.Parent then
        active.Humanoid.PlatformStand = false
    end

    if active.HasTeleportTag then
        local tagGeneration = self.TagGeneration
        local function removeTag()
            if self.Active == nil
                and self.TagGeneration == tagGeneration
                and self.Compatibility.CollectionService:HasTag(self.Compatibility.Player, "Teleporting")
            then
                self.Compatibility.CollectionService:RemoveTag(self.Compatibility.Player, "Teleporting")
                self.OwnsTeleportTag = false
            end
        end
        if delayTagRemoval then
            task.delay(1.5, removeTag)
        else
            removeTag()
        end
    end
end

function MovementService:_StopMovement()
    self.Generation += 1
    local active = self.Active
    if active then
        self:_Finish(active, true)
    end
end

function MovementService:_DestroyHoldForce()
    if self.HoldForce and self.HoldForce.Parent then
        self.HoldForce:Destroy()
    end
    self.HoldForce = nil
end

function MovementService:Cancel()
    self.RouteGeneration += 1
    if type(self.OnCancel) == "function" then
        pcall(self.OnCancel)
    end
    self:_StopMovement()
    self:_DestroyHoldForce()
end

function MovementService:HoldPosition(isCurrent)
    local character, humanoid, root = self.Compatibility:GetCharacterParts()
    if not character or not humanoid or not root then
        return false, "Character is unavailable"
    end
    isCurrent = isCurrent or function()
        return true
    end
    if not isCurrent() then
        return false, "Farm session is no longer current"
    end

    local active = self.Active
    if active
        and active.Character == character
        and active.KeepSession
        and active.IsCurrent()
    then
        if active.HoldingForSearch then
            return true, "already holding"
        end
        active.Goal = root.CFrame
        active.Threshold = 1
        active.Speed = 0
        active.Holding = false
        active.HoldingForSearch = true
        active.BestDistance = 0
        active.LastProgressAt = os.clock()
        return true, "holding current position"
    end

    if active then
        self:_StopMovement()
    end
    if self.HoldForce and self.HoldForce.Parent ~= root then
        self:_DestroyHoldForce()
    end
    if not self.HoldForce then
        local holdForce = Instance.new("BodyVelocity")
        holdForce.Name = "CustomHubFarmHoldForce"
        holdForce.Velocity = Vector3.zero
        holdForce.MaxForce = Vector3.new(100000, 100000, 100000)
        holdForce.P = 10000
        holdForce.Parent = root
        self.HoldForce = holdForce
    end
    self.HoldForce.Velocity = Vector3.zero
    return true, "holding current position"
end

function MovementService:_RequestRoute(route, isCurrent, routeGeneration)
    local now = os.clock()
    if now - (self.LastRouteRequest[route.Name] or 0) < 5 then
        return false, "Travel request is cooling down"
    end
    self.LastRouteRequest[route.Name] = now

    task.spawn(function()
        if not isCurrent() or self.RouteGeneration ~= routeGeneration then
            return
        end
        local replication = self.Compatibility.ReplicatedStorage
        local modules = replication:FindFirstChild("Modules")
        local netContainer = modules and modules:FindFirstChild("Net")
        local commF, commFError = self.Compatibility:GetCommF()
        if not netContainer or not commF then
            self.Report("Travel dependencies are unavailable", "error")
            return
        end

        local ok, err = pcall(function()
            if route.Name == "Submerged" then
                local remote = netContainer:FindFirstChild("RF/SubmarineWorkerSpeak")
                if not remote then
                    error("Modules.Net.RF/SubmarineWorkerSpeak is unavailable")
                end
                remote:InvokeServer("TravelToSubmergedIsland")
                if isCurrent() and self.RouteGeneration == routeGeneration then
                    commF:InvokeServer("SetLastSpawnPoint", "SubmergedIsland")
                end
            else
                local remote = netContainer:FindFirstChild("RF/SubmarineTransportation")
                if not remote then
                    error("Modules.Net.RF/SubmarineTransportation is unavailable")
                end
                remote:InvokeServer("GetAvailableLocations")
                if isCurrent() and self.RouteGeneration == routeGeneration then
                    remote:InvokeServer("InitiateTeleport", "Tiki Outpost")
                end
            end
        end)
        if not isCurrent() or self.RouteGeneration ~= routeGeneration then
            return
        end
        if ok then
            self.Report(route.Name .. " travel request submitted", "info")
        else
            self.Report("Travel request error: " .. tostring(err), "error")
        end
    end)
    return true
end

function MovementService:MoveTo(destination, options)
    options = options or {}
    if typeof(destination) ~= "CFrame" then
        return false, "Movement destination must be a CFrame"
    end

    local character, humanoid, root = self.Compatibility:GetCharacterParts()
    if not character or not humanoid or not root then
        return false, "Character is unavailable"
    end
    if self.LastStallAt and os.clock() - self.LastStallAt < 1 then
        return false, "Movement retry cooldown after a stall"
    end

    local route = self:_GetRoute(destination, root.Position)
    local goal = route and route.Stage or destination
    local threshold = route and 8 or (tonumber(options.Threshold) or 2.5)
    local isCurrent = options.IsCurrent or function()
        return true
    end

    local active = self.Active
    -- A reached destination is not a reusable "already moving" goal: let the
    -- retained-session branch below refresh it, even for a small target shift.
    if active
        and active.Character == character
        and active.RouteName == (route and route.Name)
        and not active.Holding
        and not active.HoldingForSearch
        and (active.Goal.Position - goal.Position).Magnitude <= 12
    then
        return true, "already moving"
    end

    if active
        and active.Character == character
        and active.KeepSession
        and options.KeepSession == true
        and not active.Route
        and not route
        and active.IsCurrent()
    then
        local previousGoal = active.Goal.Position
        local destinationShift = (previousGoal - goal.Position).Magnitude
        local wasHolding = active.Holding or active.HoldingForSearch
        active.Goal = goal
        active.Threshold = threshold
        active.Speed = tonumber(options.Speed) or active.Speed
        active.IsCurrent = isCurrent
        active.Holding = false
        active.HoldingForSearch = false
        if wasHolding or destinationShift > 12 then
            active.BestDistance = (goal.Position - root.Position).Magnitude
            active.LastProgressAt = os.clock()
        end
        if active.BestDistance <= threshold then
            root.CFrame = destination
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
            active.Holding = true
        end
        return true, active.Holding and "retargeted and holding" or "retargeted"
    end

    self:_StopMovement()
    if (goal.Position - root.Position).Magnitude <= threshold then
        if route then
            local requested, requestError = self:_RequestRoute(
                route,
                isCurrent,
                self.RouteGeneration
            )
            return requested, requestError or "at travel staging point"
        end
        root.CFrame = destination
        return true, "arrived"
    end

    self:_DestroyHoldForce()
    self.Generation += 1
    self.TagGeneration += 1
    local generation = self.Generation
    local collisionOriginals = {}
    for _, descendant in ipairs(character:GetDescendants()) do
        if descendant:IsA("BasePart") then
            collisionOriginals[descendant] = descendant.CanCollide
            descendant.CanCollide = false
        end
    end

    local floatForce = root:FindFirstChild("FloatForce")
    local ownsFloatForce = false
    if not floatForce then
        floatForce = Instance.new("BodyVelocity")
        floatForce.Name = "FloatForce"
        floatForce.Velocity = Vector3.zero
        floatForce.MaxForce = Vector3.new(100000, 100000, 100000)
        floatForce.P = 10000
        floatForce.Parent = root
        ownsFloatForce = true
    end

    local hasTag = self.Compatibility.CollectionService:HasTag(
        self.Compatibility.Player,
        "Teleporting"
    )
    if not hasTag then
        self.Compatibility.CollectionService:AddTag(self.Compatibility.Player, "Teleporting")
        self.OwnsTeleportTag = true
    end

    active = {
        Character = character,
        Humanoid = humanoid,
        Root = root,
        Goal = goal,
        RouteName = route and route.Name,
        Route = route,
        Threshold = threshold,
        Speed = route and 190 or (tonumber(options.Speed) or 300),
        IsCurrent = isCurrent,
        Generation = generation,
        CollisionOriginals = collisionOriginals,
        FloatForce = ownsFloatForce and floatForce or nil,
        HasTeleportTag = self.OwnsTeleportTag,
        KeepSession = options.KeepSession == true and route == nil,
        Holding = false,
        HoldingForSearch = false,
        BestDistance = (goal.Position - root.Position).Magnitude,
        LastProgressAt = os.clock(),
    }
    self.Active = active

    active.Connection = self.Compatibility.RunService.Heartbeat:Connect(function(deltaTime)
        if self.Active ~= active or self.Generation ~= generation or not active.IsCurrent() then
            self:_Finish(active, true)
            return
        end

        local currentCharacter, currentHumanoid, currentRoot = self.Compatibility:GetCharacterParts()
        if currentCharacter ~= character
            or currentHumanoid ~= humanoid
            or currentRoot ~= root
            or root.Anchored
        then
            self.LastStallAt = os.clock()
            self:_Finish(active, true)
            self.Report("Movement interrupted by character replacement or an anchored root", "warning")
            return
        end

        local goalNow = active.Goal
        local thresholdNow = active.Threshold
        if active.HoldingForSearch then
            root.CFrame = goalNow
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
            active.LastCommandedPosition = goalNow.Position
            active.Holding = true
            active.BestDistance = 0
            active.LastProgressAt = os.clock()
            return
        end
        local offset = goalNow.Position - root.Position
        local distance = offset.Magnitude
        active.LastCommandError = active.LastCommandedPosition
            and (root.Position - active.LastCommandedPosition).Magnitude
            or nil
        if distance <= thresholdNow then
            root.CFrame = goalNow
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
            active.LastCommandedPosition = goalNow.Position
            if active.KeepSession then
                active.Holding = true
                active.BestDistance = distance
                active.LastProgressAt = os.clock()
                return
            end
            self:_Finish(active, true)
            if active.Route then
                self:_RequestRoute(active.Route, active.IsCurrent, self.RouteGeneration)
            end
            return
        end
        active.Holding = false
        if distance < active.BestDistance - 1 then
            active.BestDistance = distance
            active.LastProgressAt = os.clock()
        elseif os.clock() - active.LastProgressAt > 2.5 then
            self.LastStallAt = os.clock()
            local diagnosticOk, diagnosticError = pcall(
                self._CaptureStallDiagnostic,
                self,
                active,
                root,
                goalNow,
                distance
            )
            if not diagnosticOk then
                self.LastStallDiagnostic = {
                    At = os.clock(),
                    Text = "===== [MovementStallDiagnostic] REPORT BEGIN =====\n"
                        .. "Snapshot failed: "
                        .. tostring(diagnosticError)
                        .. "\n===== [MovementStallDiagnostic] REPORT END =====",
                }
            end
            self:_Finish(active, true)
            self:HoldPosition(active.IsCurrent)
            self.Report(
                "Movement stalled; cancelling this attempt before retry. Copy the status report for details.",
                "warning"
            )
            return
        end

        local step = math.min(active.Speed * deltaTime, 18)
        if step <= 0 then
            return
        end
        local nextPosition = root.Position + offset.Unit * math.min(step, distance)
        root.CFrame = CFrame.new(nextPosition)
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
        active.LastCommandedPosition = nextPosition
    end)

    return true, route and ("moving to " .. route.Name .. " staging") or "moving"
end

return MovementService
-- END SOURCE: src/ReplicatedStorage/CustomHub/Features/Farm/MovementService.lua
end

__bundleFactories["CustomHub.Features.Farm.SkillAimRedirect"] = function()
-- BEGIN SOURCE: src/ReplicatedStorage/CustomHub/Features/Farm/SkillAimRedirect.lua
local SkillAimRedirect = {}

local STATE_KEY = "__CustomHubSkillAimRedirectV1"

local function getSharedState()
    local environment = _G
    local getterOk, getEnvironment = pcall(function()
        return getgenv
    end)
    if getterOk and type(getEnvironment) == "function" then
        local environmentOk, executorEnvironment = pcall(getEnvironment)
        if environmentOk and type(executorEnvironment) == "table" then
            environment = executorEnvironment
        end
    end

    local stateOk, existingState = pcall(function()
        return environment[STATE_KEY]
    end)
    if stateOk and type(existingState) == "table" and existingState.Version == 1 then
        return existingState
    end

    local newState = {
        Version = 1,
        ActiveContext = nil,
        Installed = false,
        InstallError = nil,
    }
    pcall(function()
        environment[STATE_KEY] = newState
    end)
    return newState
end

local state = getSharedState()

local function clearExpiredContext()
    local context = state.ActiveContext
    if context and context.ExpiresAt and os.clock() > context.ExpiresAt then
        context.Active = false
        state.ActiveContext = nil
        return nil
    end
    return context
end

local function installNamecallHook()
    if state.Installed then
        return true
    end

    local getterOk, getRawMetatable = pcall(function()
        return getrawmetatable
    end)
    local readonlyOk, setReadonly = pcall(function()
        return setreadonly
    end)
    local closureOk, newClosure = pcall(function()
        return newcclosure
    end)
    local methodOk, getNamecallMethod = pcall(function()
        return getnamecallmethod
    end)
    if not getterOk or type(getRawMetatable) ~= "function"
        or not readonlyOk or type(setReadonly) ~= "function"
        or not closureOk or type(newClosure) ~= "function"
        or not methodOk or type(getNamecallMethod) ~= "function"
    then
        state.InstallError = "Executor remote-aim hooks are unavailable"
        return false, state.InstallError
    end

    local metatableOk, gameMetatable = pcall(getRawMetatable, game)
    if not metatableOk or type(gameMetatable) ~= "table"
        or type(gameMetatable.__namecall) ~= "function"
    then
        state.InstallError = "Game remote-aim hook target is unavailable"
        return false, state.InstallError
    end

    local oldNamecall = gameMetatable.__namecall
    local wrapperOk, replacement = pcall(newClosure, function(remote, ...)
        local context = clearExpiredContext()
        if context and context.Active then
            local currentMethodOk, currentMethod = pcall(getNamecallMethod)
            if currentMethodOk and currentMethod == "FireServer" then
                local nameOk, remoteName = pcall(function()
                    return remote.Name
                end)
                if nameOk and remoteName == "RemoteEvent" then
                    local arguments = table.pack(...)
                    if arguments.n == 1 then
                        local argument = arguments[1]
                        if typeof(argument) == "Vector3" then
                            arguments[1] = context.Position
                            return oldNamecall(
                                remote,
                                table.unpack(arguments, 1, arguments.n)
                            )
                        elseif typeof(argument) == "CFrame" then
                            arguments[1] = context.CFrame
                            return oldNamecall(
                                remote,
                                table.unpack(arguments, 1, arguments.n)
                            )
                        end
                    end
                end
            end
        end
        return oldNamecall(remote, ...)
    end)
    if not wrapperOk or type(replacement) ~= "function" then
        state.InstallError = "Could not create the skill aim redirect"
        return false, state.InstallError
    end

    local writable, writableError = pcall(setReadonly, gameMetatable, false)
    if not writable then
        state.InstallError = "Could not enable the skill aim redirect: "
            .. tostring(writableError)
        return false, state.InstallError
    end

    local assigned, assignError = pcall(function()
        gameMetatable.__namecall = replacement
    end)
    pcall(setReadonly, gameMetatable, true)
    if not assigned then
        state.InstallError = "Could not install the skill aim redirect: "
            .. tostring(assignError)
        return false, state.InstallError
    end

    state.Installed = true
    state.InstallError = nil
    return true
end

function SkillAimRedirect:Begin(targetPart)
    if not targetPart or not targetPart:IsA("BasePart") then
        return nil, "Skill aim target is unavailable"
    end
    local context = clearExpiredContext()
    if context and context.InputActive then
        return nil, "Another skill aim redirect is already active"
    end

    local installed, installError = installNamecallHook()
    if not installed then
        return nil, installError
    end

    if not context then
        context = {
            Active = true,
            Persistent = false,
            InputActive = false,
        }
        state.ActiveContext = context
    end
    context.Active = true
    context.InputActive = true
    context.ExpiresAt = nil
    local updated, updateError = self:Update(context, targetPart)
    if not updated then
        self:End(context)
        return nil, updateError
    end
    return context
end

function SkillAimRedirect:SetTarget(targetPart, owner)
    if not targetPart or not targetPart:IsA("BasePart") then
        return false, "Skill aim target is unavailable"
    end

    local context = clearExpiredContext()
    if context and context.InputActive then
        return false, "A skill cast is already using the aim target"
    end

    local installed, installError = installNamecallHook()
    if not installed then
        return false, installError
    end

    if not context then
        context = {
            Active = true,
            Persistent = true,
            InputActive = false,
        }
        state.ActiveContext = context
    end
    context.Active = true
    context.Persistent = true
    context.InputActive = false
    context.Owner = owner
    context.ExpiresAt = nil
    local updated, updateError = self:Update(context, targetPart)
    if not updated then
        self:ClearTarget(owner)
        return false, updateError
    end
    return true
end

function SkillAimRedirect:Update(context, targetPart)
    if not context or context.Active ~= true or state.ActiveContext ~= context then
        return false, "Skill aim redirect is no longer active"
    end
    if not targetPart or not targetPart:IsA("BasePart") or not targetPart.Parent then
        return false, "Skill aim target part is unavailable"
    end

    context.Position = targetPart.Position
    context.CFrame = targetPart.CFrame
    if context.Persistent or context.InputActive then
        context.ExpiresAt = nil
    else
        context.ExpiresAt = os.clock() + 1
    end
    return true
end

function SkillAimRedirect:End(context)
    if not context then
        return
    end
    context.InputActive = false
    if context.Persistent then
        context.Active = true
        context.ExpiresAt = nil
    else
        context.Active = true
        context.ExpiresAt = os.clock() + 1
    end
end

function SkillAimRedirect:ClearTarget(owner)
    local context = clearExpiredContext()
    if not context or (owner and context.Owner ~= owner) then
        return false
    end

    context.Persistent = false
    context.Owner = nil
    if context.InputActive then
        return true
    end
    context.Active = false
    state.ActiveContext = nil
    return true
end

return SkillAimRedirect
-- END SOURCE: src/ReplicatedStorage/CustomHub/Features/Farm/SkillAimRedirect.lua
end

__bundleFactories["CustomHub.Features.Farm.CombatService"] = function()
-- BEGIN SOURCE: src/ReplicatedStorage/CustomHub/Features/Farm/CombatService.lua
local CombatService = {}
CombatService.__index = CombatService
local SkillAimRedirect = __bundleLoad("CustomHub.Features.Farm.SkillAimRedirect")

local validHitPartNames = {
    RightUpperArm = true,
    RightLowerArm = true,
    RightHand = true,
    RightUpperLeg = true,
    RightLowerLeg = true,
    RightFoot = true,
    LeftUpperArm = true,
    LeftLowerArm = true,
    LeftHand = true,
    LeftUpperLeg = true,
    LeftLowerLeg = true,
    LeftFoot = true,
    UpperTorso = true,
    LowerTorso = true,
    Head = true,
}
local skillCategories = {
    { Name = "Melee", Token = "Melee", Keys = { "Z", "X", "C" } },
    { Name = "Sword", Token = "Sword", Keys = { "Z", "X" } },
    { Name = "Gun", Token = "Gun", Keys = { "Z", "X" } },
    { Name = "Blox Fruit", Token = "BloxFruit", Keys = { "Z", "X", "C", "V", "F" } },
}

local function listSkillUiToolNames(skills)
    if not skills then
        return "missing"
    end
    local names = {}
    for _, child in ipairs(skills:GetChildren()) do
        table.insert(names, child.Name)
    end
    if #names == 0 then
        return "none"
    end
    return table.concat(names, ", ")
end

local function listCategoryToolNames(container, categoryName)
    if not container then
        return "missing"
    end
    local names = {}
    for _, item in ipairs(container:GetChildren()) do
        if item:IsA("Tool") and item.ToolTip == categoryName then
            table.insert(names, item.Name)
        end
    end
    return #names > 0 and table.concat(names, ", ") or "none"
end

function CombatService.new(compatibility, enemyService)
    local dependencies, dependencyError = compatibility:GetCombatDependencies()
    if not dependencies then
        return nil, dependencyError
    end
    return setmetatable({
        Compatibility = compatibility,
        EnemyService = enemyService,
        Dependencies = dependencies,
        AttackIndex = 0,
        FruitAttackIndex = 1,
        NextGunM1At = {},
    }, CombatService)
end

function CombatService:FindEquippedWeapon(category)
    local player = self.Compatibility.Player
    local character = player and player.Character
    if not character then
        return nil, "Character is unavailable"
    end
    for _, item in ipairs(character:GetChildren()) do
        if item:IsA("Tool") and item.ToolTip == category then
            return item
        end
    end
    return nil, "No equipped " .. tostring(category) .. " tool is available"
end

function CombatService:ResetGunM1Cooldown(tool)
    if tool and self.NextGunM1At then
        self.NextGunM1At[tool] = nil
        return true
    end
    return false
end

function CombatService:FindWeapon(category)
    local player = self.Compatibility.Player
    local backpack = player and player:FindFirstChild("Backpack")
    local character = player and player.Character
    -- Prefer Skull Guitar for the Gun category wherever it is currently loaded:
    -- AttackGunM1 selects TAP only after this tool is actually equipped.
    if category == "Gun" then
        if character then
            for _, item in ipairs(character:GetChildren()) do
                if item:IsA("Tool")
                    and item.ToolTip == "Gun"
                    and item.Name == "Skull Guitar"
                then
                    return item
                end
            end
        end
        if backpack then
            for _, item in ipairs(backpack:GetChildren()) do
                if item:IsA("Tool")
                    and item.ToolTip == "Gun"
                    and item.Name == "Skull Guitar"
                then
                    return item
                end
            end
        end
    end
    -- Otherwise prefer any matching equipped tool before a hotbar tool.
    if character then
        for _, item in ipairs(character:GetChildren()) do
            if item:IsA("Tool") and item.ToolTip == category then
                return item
            end
        end
    end
    if backpack then
        for _, item in ipairs(backpack:GetChildren()) do
            if item:IsA("Tool") and item.ToolTip == category then
                return item
            end
        end
    end
    return nil
end

function CombatService:FindSkillWeapon(category, preferEquipped)
    local player = self.Compatibility.Player
    local backpack = player and player:FindFirstChild("Backpack")
    local character = player and player.Character

    if preferEquipped then
        local equipped = self:FindEquippedWeapon(category)
        if equipped then
            return equipped
        end
    end

    local function findMatchingTool(container, exactName)
        if not container then
            return nil
        end
        for _, item in ipairs(container:GetChildren()) do
            if item:IsA("Tool")
                and item.ToolTip == category
                and (not exactName or item.Name == exactName)
            then
                return item
            end
        end
        return nil
    end

    -- Preserve the existing non-Mastery Skull Guitar preference, then mirror
    -- BNN's NameWeapon order: hotbar Backpack first, equipped Character next.
    if category == "Gun" and not preferEquipped then
        local skullGuitar = findMatchingTool(backpack, "Skull Guitar")
            or findMatchingTool(character, "Skull Guitar")
        if skullGuitar then
            return skullGuitar
        end
    end
    return findMatchingTool(backpack) or findMatchingTool(character)
end

function CombatService:FindToolByName(toolName)
    local player = self.Compatibility.Player
    local character = player and player.Character
    local backpack = player and player:FindFirstChild("Backpack")
    local containers = {}
    if character then
        table.insert(containers, character)
    end
    if backpack then
        table.insert(containers, backpack)
    end
    for _, container in ipairs(containers) do
        local tool = container:FindFirstChild(toolName)
        if tool and tool:IsA("Tool") then
            return tool
        end
    end
    return nil
end

function CombatService:EquipTool(tool)
    if not tool or not tool:IsA("Tool") then
        return false, "Selected tool is unavailable"
    end
    local character, humanoid = self.Compatibility:GetCharacterParts()
    if not character or not humanoid or humanoid.Sit then
        return false, "Character cannot equip a tool"
    end
    if tool.Parent ~= character then
        local player = self.Compatibility.Player
        local backpack = player and player:FindFirstChild("Backpack")
        if tool.Parent ~= backpack then
            return false, "Selected tool is not in the character or Backpack"
        end
        humanoid:EquipTool(tool)
    end
    if tool.Parent ~= character then
        return false, "Selected tool did not equip"
    end
    return true, tool
end

function CombatService:EquipWeapon(category)
    local tool, findError = self:FindWeapon(category)
    if not tool then
        return false, findError or ("No owned " .. tostring(category) .. " tool was found")
    end
    return self:EquipTool(tool)
end

function CombatService:_FindReadySkill(
    isEnabled,
    preferredCategory,
    ignoredTools,
    onlyCategory
)
    local playerGui = self.Compatibility:GetPlayerGui()
    local main = playerGui and playerGui:FindFirstChild("Main")
    local skills = main and main:FindFirstChild("Skills")
    if not skills then
        return nil, "PlayerGui.Main.Skills is unavailable"
    end

    local selectedKeyCount = 0
    local checkedToolCount = 0
    local missingToolCategory
    local ignoredToolName
    local incompleteSkillControls
    local unavailableSkillTitle
    local masterySkillNotReady
    local orderedCategories = {}
    for _, category in ipairs(skillCategories) do
        if category.Name == preferredCategory then
            table.insert(orderedCategories, 1, category)
        else
            table.insert(orderedCategories, category)
        end
    end
    for _, category in ipairs(orderedCategories) do
        if not onlyCategory or category.Name == onlyCategory then
            local tool = self:FindSkillWeapon(category.Name, onlyCategory ~= nil)
            local selectedKeys = {}
            local selectedKeySet = {}
            for _, keyName in ipairs(category.Keys) do
                if isEnabled(category, keyName) then
                    table.insert(selectedKeys, keyName)
                    selectedKeySet[keyName] = true
                end
            end
            selectedKeyCount += #selectedKeys
            if #selectedKeys > 0 and not tool then
                missingToolCategory = missingToolCategory or category.Name
            elseif tool and #selectedKeys > 0
                and ignoredTools
                and ignoredTools[tool.Name]
            then
                ignoredToolName = ignoredToolName or tool.Name
            elseif tool and #selectedKeys > 0 then
                checkedToolCount += 1
                if onlyCategory then
                    -- BNN equips the selected hotbar tool, then inspects its
                    -- Skills row in the same pass. The UI row can be ready
                    -- before Roblox finishes reparenting the Tool, so do not
                    -- gate skill discovery on Parent changing synchronously.
                    pcall(self.EquipTool, self, tool)
                end
                local toolSkills = skills:FindFirstChild(tool.Name)
                if not toolSkills then
                    local equipped, equipResult = self:EquipTool(tool)
                    if not equipped then
                        return nil, tostring(equipResult), tool
                    end
                    return nil,
                        "Waiting for PlayerGui.Main.Skills entry '"
                            .. tool.Name .. "' (entries: "
                            .. listSkillUiToolNames(skills) .. ")",
                        tool
                end
                for _, frame in ipairs(toolSkills:GetChildren()) do
                    local keyName = frame.Name
                    local selectedKey = selectedKeySet[keyName]
                    local title = frame and frame:FindFirstChild("Title")
                    local cooldown = frame and frame:FindFirstChild("Cooldown")
                    local titleText = title and title:IsA("TextLabel") and title.Text or ""
                    local cooldownEmpty = cooldown
                        and cooldown:IsA("GuiObject")
                        and cooldown.Size == UDim2.new(0, 0, 1, -1)
                    local cooldownFull = cooldown
                        and cooldown:IsA("GuiObject")
                        and cooldown.Size == UDim2.new(1, 0, 1, -1)
                    local hasSkillControls = frame
                        and frame:IsA("Frame")
                        and title
                        and title:IsA("TextLabel")
                        and cooldown
                        and cooldown:IsA("GuiObject")
                    if frame.Name ~= "Template"
                        and selectedKey
                        and not hasSkillControls
                    then
                        incompleteSkillControls = incompleteSkillControls or (
                            tool.Name .. " " .. keyName .. " controls are incomplete"
                        )
                        if onlyCategory then
                            masterySkillUiTool = masterySkillUiTool or tool
                        end
                    elseif frame.Name ~= "Template"
                        and selectedKey
                        and (titleText == "" or titleText == "???")
                    then
                        unavailableSkillTitle = unavailableSkillTitle or (
                            tool.Name .. " " .. keyName .. " title is unavailable"
                        )
                        if onlyCategory then
                            masterySkillUiTool = masterySkillUiTool or tool
                        end
                    elseif frame.Name ~= "Template"
                        and selectedKey
                        and string.find(titleText, "Transformation", 1, true)
                    then
                        unavailableSkillTitle = unavailableSkillTitle or (
                            tool.Name .. " " .. keyName .. " is not an attack skill"
                        )
                    elseif frame.Name ~= "Template" and selectedKey then
                        local titleColor = title.TextColor3
                        local titleIsReady = titleColor == Color3.new(1, 1, 1)
                        local isReady = (titleIsReady and cooldownEmpty) or cooldownFull
                        if isReady then
                            return {
                                Tool = tool,
                                Category = category.Name,
                                Key = keyName,
                                Setting = "FarmSkill_" .. category.Token .. "_" .. keyName,
                            }
                        elseif onlyCategory and cooldownEmpty and not cooldownFull
                            and not titleIsReady
                        then
                            masterySkillNotReady = masterySkillNotReady
                                or (tool.Name .. " " .. keyName
                                    .. " is not ready (locked or unavailable)")
                        end
                    end
                end
            end
        end
    end
    if selectedKeyCount == 0 then
        return nil, "No selected skill keys are enabled"
    end
    if checkedToolCount == 0 and ignoredToolName then
        return nil, "Skill controls are temporarily unavailable for " .. ignoredToolName
    end
    if checkedToolCount == 0 and missingToolCategory then
        return nil, "No usable " .. missingToolCategory .. " skill weapon is available"
    end
    if incompleteSkillControls then
        return nil,
            "Skill UI incomplete: " .. incompleteSkillControls,
            onlyCategory and masterySkillUiTool or nil
    end
    if unavailableSkillTitle then
        return nil,
            "Selected skill unavailable: " .. unavailableSkillTitle,
            onlyCategory and masterySkillUiTool or nil
    end
    if masterySkillNotReady then
        return nil, "No selected mastery skill is ready: " .. masterySkillNotReady
    end
    return nil, "All selected skill keys are on cooldown"
end

function CombatService:FindReadyFarmSkill(
    farmSettings,
    preferredCategory,
    ignoredTools,
    onlyCategory
)
    return self:_FindReadySkill(function(category, keyName)
        return farmSettings["FarmSkill_" .. category.Token .. "_" .. keyName] == true
    end, preferredCategory, ignoredTools, onlyCategory)
end

function CombatService:BuildFarmSkillDiagnostic(farmSettings, categoryName, preferEquipped)
    local player = self.Compatibility.Player
    local character = player and player.Character
    local backpack = player and player:FindFirstChild("Backpack")
    local playerGui = self.Compatibility:GetPlayerGui()
    local main = playerGui and playerGui:FindFirstChild("Main")
    local skills = main and main:FindFirstChild("Skills")
    local tool = self:FindSkillWeapon(categoryName, preferEquipped == true)
    local toolParent = "none"
    if tool then
        if tool.Parent == character then
            toolParent = "Character"
        elseif tool.Parent == backpack then
            toolParent = "Backpack"
        else
            toolParent = tool.Parent and tool.Parent.Name or "unparented"
        end
    end

    local mainEnabled = "n/a"
    if main and main:IsA("ScreenGui") then
        mainEnabled = tostring(main.Enabled)
    end
    local skillsVisible = "n/a"
    if skills and skills:IsA("GuiObject") then
        skillsVisible = tostring(skills.Visible)
    end
    local entry = skills and tool and skills:FindFirstChild(tool.Name)
    local categoryDefinition
    for _, category in ipairs(skillCategories) do
        if category.Name == categoryName then
            categoryDefinition = category
            break
        end
    end

    local lines = {
        "Category: " .. tostring(categoryName),
        "Tool: " .. (tool and tool.Name or "none")
            .. "; parent=" .. toolParent
            .. "; character matches=" .. listCategoryToolNames(character, categoryName)
            .. "; backpack matches=" .. listCategoryToolNames(backpack, categoryName),
        "GUI: PlayerGui=" .. (playerGui and "present" or "missing")
            .. "; Main=" .. (main and main.ClassName or "missing")
            .. "; Main.Enabled=" .. mainEnabled
            .. "; Skills=" .. (skills and skills.ClassName or "missing")
            .. "; Skills.Visible=" .. skillsVisible,
        "Skills entries: " .. listSkillUiToolNames(skills),
        "Selected tool entry: " .. (entry and "present" or "missing"),
    }

    if categoryDefinition then
        local enabledKeys = {}
        for _, keyName in ipairs(categoryDefinition.Keys) do
            local settingName = "FarmSkill_" .. categoryDefinition.Token .. "_" .. keyName
            if farmSettings and farmSettings[settingName] == true then
                table.insert(enabledKeys, keyName)
                local frame = entry and entry:FindFirstChild(keyName)
                local title = frame and frame:FindFirstChild("Title")
                local cooldown = frame and frame:FindFirstChild("Cooldown")
                local titleText = title
                    and title:IsA("TextLabel")
                    and title.Text
                    or "missing"
                if #titleText > 48 then
                    titleText = titleText:sub(1, 48)
                end
                local titleReady = title
                    and title:IsA("TextLabel")
                    and title.TextColor3 == Color3.new(1, 1, 1)
                local cooldownEmpty = cooldown
                    and cooldown:IsA("GuiObject")
                    and cooldown.Size == UDim2.new(0, 0, 1, -1)
                local cooldownFull = cooldown
                    and cooldown:IsA("GuiObject")
                    and cooldown.Size == UDim2.new(1, 0, 1, -1)
                local hasControls = frame
                    and frame:IsA("Frame")
                    and title
                    and title:IsA("TextLabel")
                    and cooldown
                    and cooldown:IsA("GuiObject")
                local ready = frame
                    and frame.Name ~= "Template"
                    and hasControls
                    and ((titleReady and cooldownEmpty) or cooldownFull)
                table.insert(
                    lines,
                    keyName .. ": frame=" .. (frame and frame.ClassName or "missing")
                        .. "; visible=" .. tostring(frame and frame.Visible or "n/a")
                        .. "; controls=" .. tostring(hasControls == true)
                        .. "; title=" .. tostring(titleText)
                        .. "; titleReady=" .. tostring(titleReady == true)
                        .. "; cooldownEmpty=" .. tostring(cooldownEmpty == true)
                        .. "; cooldownFull=" .. tostring(cooldownFull == true)
                        .. "; ready=" .. tostring(ready == true)
                )
            end
        end
        table.insert(
            lines,
            2,
            "Selected keys: " .. (#enabledKeys > 0 and table.concat(enabledKeys, ", ") or "none")
        )
    else
        table.insert(lines, 2, "Selected keys: no matching skill category")
    end

    return table.concat(lines, "\n")
end

function CombatService:FindReadyTikiSkill()
    return self:_FindReadySkill(function()
        return true
    end)
end

function CombatService:_GetAimTarget(target, preferRoot)
    if not target then
        return nil, nil
    end
    if target:IsA("BasePart") then
        return target, target
    end
    if not target:IsA("Model") then
        return nil, nil
    end

    local preferredParts = preferRoot
        and { "HumanoidRootPart", "UpperTorso", "Torso", "Head" }
        or { "UpperTorso", "Torso", "HumanoidRootPart", "Head" }
    for _, partName in ipairs(preferredParts) do
        local part = target:FindFirstChild(partName)
        if part and part:IsA("BasePart") then
            return part, target
        end
    end
    if target.PrimaryPart and target.PrimaryPart:IsA("BasePart") then
        return target.PrimaryPart, target
    end
    local part = target:FindFirstChildWhichIsA("BasePart", true)
    if part then
        return part, target
    end
    return nil, nil
end

function CombatService:_UpdateTemporaryAim(aimContext, target)
    local targetPart, mouseTarget =
        self:_GetAimTarget(target, aimContext.PreferRoot)
    if not targetPart then
        return false, "Skill target has no aimable BasePart"
    end
    local setAimOk = pcall(function()
        aimContext.Mouse.Hit = targetPart.CFrame
        aimContext.Mouse.Target = mouseTarget
    end)
    local verifyAimOk, assignedHit, assignedTarget = pcall(function()
        return aimContext.Mouse.Hit, aimContext.Mouse.Target
    end)
    if not setAimOk or not verifyAimOk
        or typeof(assignedHit) ~= "CFrame"
        or (assignedHit.Position - targetPart.Position).Magnitude > 0.1
        or assignedTarget ~= mouseTarget
    then
        return false, "ReplicatedStorage.Mouse rejected the temporary target-model aim"
    end
    if aimContext.RemoteAim then
        local redirectUpdated, redirectError =
            SkillAimRedirect:Update(aimContext.RemoteAim, targetPart)
        if not redirectUpdated then
            return false, tostring(redirectError)
        end
    end
    aimContext.TargetPart = targetPart
    return true
end

function CombatService:_SetTemporaryAim(target, redirectSkillRemote)
    local mouse = self.Dependencies.Mouse
    if type(mouse) ~= "table" then
        return nil, "ReplicatedStorage.Mouse did not expose the BNN aim table"
    end
    local readAimOk, oldHit, oldTarget = pcall(function()
        return mouse.Hit, mouse.Target
    end)
    if not readAimOk then
        return nil, "ReplicatedStorage.Mouse aim state is unreadable"
    end

    local targetPart, mouseTarget = self:_GetAimTarget(target, redirectSkillRemote == true)
    if not targetPart then
        return nil, "Skill target has no aimable BasePart"
    end
    local remoteAim
    if redirectSkillRemote then
        local redirectError
        remoteAim, redirectError = SkillAimRedirect:Begin(targetPart)
        if not remoteAim then
            return nil, tostring(redirectError)
        end
    end

    local aimContext = {
        Mouse = mouse,
        OldHit = oldHit,
        OldTarget = oldTarget,
        RemoteAim = remoteAim,
        PreferRoot = redirectSkillRemote == true,
    }
    local aimOk, aimError = self:_UpdateTemporaryAim(aimContext, target)
    if not aimOk then
        self:_RestoreTemporaryAim(aimContext)
        return nil, aimError
    end
    return aimContext
end

function CombatService:_RestoreTemporaryAim(aimContext)
    if not aimContext then
        return
    end
    SkillAimRedirect:End(aimContext.RemoteAim)
    if not aimContext.Mouse then
        return
    end
    pcall(function()
        aimContext.Mouse.Hit = aimContext.OldHit
        aimContext.Mouse.Target = aimContext.OldTarget
    end)
end

function CombatService:SetFarmSkillAimTarget(target)
    local targetPart = self:_GetAimTarget(target, true)
    if not targetPart then
        self:ClearFarmSkillAimTarget()
        return false, "Skill target has no aimable BasePart"
    end
    return SkillAimRedirect:SetTarget(targetPart, self)
end

function CombatService:ClearFarmSkillAimTarget()
    return SkillAimRedirect:ClearTarget(self)
end

function CombatService:UseSkill(tool, keyName, target, holdSeconds, shouldContinue)
    if not tool or not tool:IsA("Tool") or type(keyName) ~= "string" then
        return false, "Skill input is invalid"
    end
    if not target or not target.Parent or target:GetAttribute("AlreadyDestroyedClient") == true then
        return false, "Skill target is no longer available"
    end

    local character = self.Compatibility.Player and self.Compatibility.Player.Character
    local equipped, equipResult = self:EquipTool(tool)
    if not equipped then
        return false, tostring(equipResult)
    end
    character = self.Compatibility.Player and self.Compatibility.Player.Character
    if not character or tool.Parent ~= character then
        return false, "Selected skill weapon did not equip"
    end

    local aimContext, aimError = self:_SetTemporaryAim(target, true)
    if not aimContext then
        return false, tostring(aimError)
    end

    -- Match the reference hubs: activate skill keys through VirtualInputManager
    -- on desktop and touch clients alike. Firing GUI signal connections does not
    -- produce a real input event on many mobile executors.
    local inputOk, inputService = pcall(function()
        return game:GetService("VirtualInputManager")
    end)
    if not inputOk or not inputService then
        self:_RestoreTemporaryAim(aimContext)
        return false, "Skill input is unavailable in this runtime"
    end
    local pressed, pressError = pcall(function()
        inputService:SendKeyEvent(true, keyName, false, game)
    end)
    if not pressed then
        self:_RestoreTemporaryAim(aimContext)
        return false, "Skill key press failed: " .. tostring(pressError)
    end
    local inputReleased = false
    local function releaseInput()
        if inputReleased then
            return true
        end
        inputReleased = true
        local releaseOk, releaseError = pcall(function()
            inputService:SendKeyEvent(false, keyName, false, game)
        end)
        SkillAimRedirect:End(aimContext.RemoteAim)
        aimContext.RemoteAim = nil
        if not releaseOk then
            error(releaseError)
        end
        return true
    end
    self.ActiveInputRelease = releaseInput
    self.ActiveInputService = inputService
    self.ActiveSkillKey = keyName

    local holdDuration = math.clamp(tonumber(holdSeconds) or 0.5, 0.05, 5)
    local holdUntil = os.clock() + holdDuration
    local aimUpdateError
    local farmStateChanged = false
    local waitOk, waitError = pcall(function()
        while os.clock() < holdUntil do
            if shouldContinue and not shouldContinue() then
                farmStateChanged = true
                break
            end
            local aimUpdated, aimResult = self:_UpdateTemporaryAim(aimContext, target)
            if not aimUpdated then
                aimUpdateError = aimResult
                break
            end
            task.wait(math.min(0.05, math.max(0.01, holdUntil - os.clock())))
        end
    end)

    local releaseOk, releaseResult = pcall(releaseInput)
    local releaseError = releaseResult == false and "Skill release did not fire" or releaseResult
    if self.ActiveInputRelease == releaseInput then
        self.ActiveInputRelease = nil
        self.ActiveInputService = nil
        self.ActiveSkillKey = nil
    end
    self:_RestoreTemporaryAim(aimContext)

    if not releaseOk then
        return false, "Skill key release failed: " .. tostring(releaseError)
    end
    if not waitOk then
        return false, "Skill hold failed: " .. tostring(waitError)
    end
    if aimUpdateError then
        return false, "Skill aim update failed: " .. tostring(aimUpdateError)
    end
    if farmStateChanged then
        return false, "Skill input cancelled because farm state changed"
    end
    return true, keyName .. " skill key sent"
end

function CombatService:UseTikiSkill(tool, keyName, target, holdSeconds, shouldContinue)
    return self:UseSkill(tool, keyName, target, holdSeconds, shouldContinue)
end

function CombatService:_GetToolCooldown(tool)
    local cooldownValue = tool and tool:FindFirstChild("Cooldown")
    if cooldownValue
        and (
            cooldownValue:IsA("NumberValue")
            or cooldownValue:IsA("IntValue")
        )
    then
        local cooldown = tonumber(cooldownValue.Value)
        if cooldown and cooldown > 0 then
            return math.clamp(cooldown, 0.05, 5)
        end
    end

    local combatUtil = self.Dependencies.CombatUtil
    if tool and combatUtil and type(combatUtil.GetWeaponData) == "function" then
        local dataOk, weaponData = pcall(combatUtil.GetWeaponData, combatUtil, tool.Name)
        if dataOk and type(weaponData) == "table" then
            local cooldown = tonumber(weaponData.Cooldown)
            if cooldown and cooldown > 0 then
                return math.clamp(cooldown, 0.05, 5)
            end
        end
    end
    return nil
end

function CombatService:_InvokeGunShootInput(tool, targetPart)
    if self.GunM1Active then
        return false, false, "Another gun input is still being processed"
    end
    if type(targetPart) ~= "table"
        and (typeof(targetPart) ~= "Instance" or not targetPart:IsA("BasePart"))
    then
        return false, false, "Gun target is not a usable part"
    end

    local shootGun, targetAssist, resolveError =
        self.Compatibility:GetGunShootFunction()
    if type(shootGun) ~= "function" or type(targetAssist) ~= "table"
        or type(targetAssist.getTargetInfo) ~= "function"
    then
        return false, false, tostring(resolveError or "Gun target lookup is unavailable")
    end

    local inputService = game:GetService("UserInputService")
    local touchOnly = inputService.TouchEnabled and not inputService.MouseEnabled
    local input = {
        UserInputType = touchOnly
            and Enum.UserInputType.Touch
            or Enum.UserInputType.MouseButton1,
        Position = Vector3.zero,
    }

    local beforeShotsLeft = tonumber(tool:GetAttribute("LocalShotsLeft"))
    local beforeTotalShots = tonumber(tool:GetAttribute("LocalTotalShots"))
    local beforeEnabled = tool.Enabled
    local previousTargetInfo = targetAssist.getTargetInfo
    local overrideTargetInfo = function()
        return { Part = targetPart }
    end

    local overrideOk, overrideError = pcall(function()
        targetAssist.getTargetInfo = overrideTargetInfo
    end)
    if not overrideOk then
        return false, false, "Could not direct gun aim to the selected target: "
            .. tostring(overrideError)
    end

    self.GunM1Active = true
    local callOk, callError = pcall(shootGun, tool, input)
    local restoreOk, restoreError = pcall(function()
        targetAssist.getTargetInfo = previousTargetInfo
    end)

    if not restoreOk then
        self.GunM1Active = false
        return false, false, "Gun target lookup could not be restored: "
            .. tostring(restoreError)
    end
    if not callOk then
        self.GunM1Active = false
        return false, false, "Game gun input failed: " .. tostring(callError)
    end

    local waitOk, waitError = pcall(function()
        local runService = self.Compatibility.RunService
        if runService and runService.Heartbeat then
            runService.Heartbeat:Wait()
        else
            task.wait()
        end
    end)
    if not waitOk then
        self.GunM1Active = false
        return true, false, "Gun input was invoked, but shot-state check failed: "
            .. tostring(waitError)
    end

    local afterShotsLeft = tonumber(tool:GetAttribute("LocalShotsLeft"))
    local afterTotalShots = tonumber(tool:GetAttribute("LocalTotalShots"))
    local reloadObserved = false
    local combatUtil = self.Dependencies.CombatUtil
    if combatUtil and type(combatUtil.IsGunReloading) == "function" then
        local reloadOk, isReloading =
            pcall(combatUtil.IsGunReloading, combatUtil, tool)
        reloadObserved = reloadOk and isReloading == true
    end

    local shotStateChanged = (
        beforeShotsLeft ~= nil
            and afterShotsLeft ~= nil
            and afterShotsLeft < beforeShotsLeft
    ) or (
        beforeTotalShots ~= nil
            and afterTotalShots ~= nil
            and afterTotalShots ~= beforeTotalShots
    ) or (
        beforeEnabled == true and tool.Enabled == false
    ) or reloadObserved

    self.GunM1Active = false
    return true, shotStateChanged, shotStateChanged
        and "Gun client firing state changed; server damage is unconfirmed"
        or "Gun input sent, but no client firing-state change was observed"
end

function CombatService:AttackGunM1(target, requiredTool)
    if not self.EnemyService:IsAlive(target) then
        return false, "Gun M1 target is no longer alive"
    end
    if not target:IsA("Model") then
        return false, "Gun M1 target is not an enemy model"
    end
    local targetRoot = target:FindFirstChild("HumanoidRootPart")
        or target.PrimaryPart
    if not targetRoot or not targetRoot:IsA("BasePart") then
        return false, "Gun M1 target has no HumanoidRootPart"
    end

    local character, _, playerRoot = self.Compatibility:GetCharacterParts()
    if not character or not playerRoot then
        return false, "Gun M1 character is unavailable"
    end
    if (playerRoot.Position - targetRoot.Position).Magnitude >= 70 then
        return false, "Gun M1 target is outside firing range"
    end

    local tool, findError
    if requiredTool then
        tool = requiredTool
        local equippedCharacter = self.Compatibility.Player
            and self.Compatibility.Player.Character
        if not tool:IsA("Tool")
            or tool.Parent ~= equippedCharacter
            or tool.ToolTip ~= "Gun"
        then
            return false, "Selected mastery Gun is no longer equipped"
        end
    else
        tool, findError = self:FindEquippedWeapon("Gun")
    end
    if not tool then
        return false, findError or "No equipped Gun tool is available"
    end
    if character:FindFirstChild(tool.Name) ~= tool then
        return false, "Gun M1 weapon did not equip"
    end
    -- A newly selected hotbar Gun can retain Enabled=false across the swap.
    -- Let the native ShootGun handler decide; reload, ammo, and this service's
    -- per-tool cooldown remain the actual firing gates.
    local localShotsLeft = tonumber(tool:GetAttribute("LocalShotsLeft"))
    if localShotsLeft and localShotsLeft < 1 then
        return false, "Gun has no shots left"
    end

    local combatUtil = self.Dependencies.CombatUtil
    if not combatUtil or type(combatUtil.IsGunReloading) ~= "function" then
        return false, "CombatUtil reload check is unavailable"
    end
    local reloadOk, isReloading = pcall(combatUtil.IsGunReloading, combatUtil, tool)
    if not reloadOk then
        return false, "Gun reload check failed: " .. tostring(isReloading)
    end
    if isReloading then
        return false, "Gun is reloading"
    end

    local now = os.clock()
    self.NextGunM1At = self.NextGunM1At or {}
    if now < (self.NextGunM1At[tool] or 0) then
        return false, "Gun M1 is cooling down"
    end

    local inputSent, shotStateChanged, inputResult =
        self:_InvokeGunShootInput(tool, targetRoot)
    if not inputSent then
        return false, tostring(inputResult)
    end

    local cooldown = self:_GetToolCooldown(tool) or 0.25
    self.NextGunM1At[tool] = now + (
        shotStateChanged and cooldown or math.min(cooldown, 0.25)
    )
    return true, tostring(inputResult), shotStateChanged
end

function CombatService:TapSkullGuitar(targetPosition)
    if typeof(targetPosition) ~= "Vector3" then
        return false, "Skull Guitar target position is invalid"
    end
    local tool = self:FindToolByName("Skull Guitar")
    if not tool then
        return false, "Owned Skull Guitar is not loaded into the character or Backpack"
    end
    local equipped, equipResult = self:EquipTool(tool)
    if not equipped then
        return false, tostring(equipResult)
    end

    local combatUtil = self.Dependencies.CombatUtil
    if not combatUtil or type(combatUtil.IsGunReloading) ~= "function" then
        return false, "CombatUtil reload check is unavailable"
    end
    local reloadOk, isReloading = pcall(combatUtil.IsGunReloading, combatUtil, tool)
    if not reloadOk then
        return false, "Skull Guitar reload check failed: " .. tostring(isReloading)
    end
    if isReloading then
        return false, "Skull Guitar is reloading"
    end

    if not tool.Enabled then
        return false, "Skull Guitar is disabled"
    end
    local now = os.clock()
    self.NextGunM1At = self.NextGunM1At or {}
    if now < (self.NextGunM1At[tool] or 0) then
        return false, "Skull Guitar is cooling down"
    end

    local targetPart = {
        CFrame = CFrame.new(targetPosition),
        Position = targetPosition,
    }
    local inputSent, shotStateChanged, inputResult =
        self:_InvokeGunShootInput(tool, targetPart)
    if not inputSent then
        return false, "Skull Guitar input failed: " .. tostring(inputResult)
    end

    local cooldown = self:_GetToolCooldown(tool) or 0.25
    self.NextGunM1At[tool] = now + (
        shotStateChanged and cooldown or math.min(cooldown, 0.25)
    )
    return true, shotStateChanged
        and "Skull Guitar client firing state changed; puzzle progress is unconfirmed"
        or "Skull Guitar input sent; no client firing-state change was observed",
        shotStateChanged
end

function CombatService:_FindBladeHitParts(character, root, range)
    local enemies = self.Compatibility.Workspace:FindFirstChild("Enemies")
    if not enemies then
        return {}
    end

    local parts = {}
    for _, model in ipairs(enemies:GetChildren()) do
        if model ~= character and model:IsDescendantOf(self.Compatibility.Workspace) then
            local targetRoot = model:FindFirstChild("HumanoidRootPart")
            if targetRoot then
                local effectiveRange = range
                local points = { targetRoot.Position }
                if targetRoot.Size.Y > 5 then
                    table.insert(
                        points,
                        (targetRoot.CFrame * CFrame.new(0, -targetRoot.Size.Y * 1.5 + 3, 0)).Position
                    )
                end

                for _, point in ipairs(points) do
                    if (point - root.Position).Magnitude < 10 + effectiveRange + targetRoot.Size.X / 2 then
                        for _, part in ipairs(model:GetChildren()) do
                            if part:IsA("BasePart")
                                and (part.Position - root.Position).Magnitude
                                    <= effectiveRange + targetRoot.Size.X / 2
                            then
                                table.insert(parts, part)
                            end
                        end
                        break
                    end
                end
            end
        end
    end
    return parts
end

function CombatService:_GetAttackCandidates(character, root, range)
    local combatUtil = self.Dependencies.CombatUtil
    local candidates, seenRigs = {}, {}
    for _, hitPart in ipairs(self:_FindBladeHitParts(character, root, range)) do
        local rig = combatUtil:GetRigOfHitPart(hitPart)
        if rig and not seenRigs[rig] and validHitPartNames[hitPart.Name] and combatUtil:IsVulnerable(rig) then
            local summoner = rig:FindFirstChild("Summoner")
            local ownSummoner = character:FindFirstChild("Summoner")
            local ownSummonerCharacter = ownSummoner and ownSummoner.Value
            local allowed = rig ~= character
                and (not ownSummonerCharacter or rig ~= ownSummonerCharacter.Character)
                and (not summoner
                    or summoner.Value ~= game:GetService("Players"):GetPlayerFromCharacter(character))
            if allowed then
                table.insert(candidates, { rig, hitPart })
                seenRigs[rig] = true
            end
        end
    end
    return candidates
end

function CombatService:_AttackFruitM1(target, character, root, tool)
    local targetPart = target and (target.PrimaryPart or target:FindFirstChild("HumanoidRootPart"))
    if not targetPart then
        return false, "Fruit M1 target is unavailable"
    end

    local aimPosition = targetPart.Position
    local direction = aimPosition - root.Position
    if direction.Magnitude <= 0 then
        return false, "Fruit M1 target direction is unavailable"
    end
    direction = direction.Unit

    if not tool or tool.Parent ~= character or tool.ToolTip ~= "Blox Fruit" then
        return false, "Selected fruit tool is not equipped"
    end

    local leftClickRemote = tool:FindFirstChild("LeftClickRemote")
    local remoteFunction = tool:FindFirstChild("RemoteFunction")
    local remoteEvent = tool:FindFirstChild("RemoteEvent")
    if not leftClickRemote and remoteFunction then
        if remoteEvent then
            remoteEvent:FireServer(aimPosition)
        end
        remoteFunction:InvokeServer("TAP")
        return true, "Fruit M1 request issued"
    end

    if leftClickRemote and tool.Name == "Mammoth-Mammoth" then
        leftClickRemote:FireServer(direction)
        return true, "Fruit M1 request issued"
    end
    if leftClickRemote then
        self.FruitAttackIndex += 1
        if self.FruitAttackIndex > 5 then
            self.FruitAttackIndex = 1
        end
        leftClickRemote:FireServer(direction, self.FruitAttackIndex)
        return true, "Fruit M1 request issued"
    end
    return false, "Selected fruit tool has no supported M1 remote"
end

function CombatService:AttackM1(target, range, weaponCategory, attackNoAnimation, requiredTool)
    local character, humanoid, root = self.Compatibility:GetCharacterParts()
    if not character or not humanoid or not root or not self.EnemyService:IsAlive(target) then
        return false, "Target or character is invalid"
    end

    local targetRoot = target:FindFirstChild("HumanoidRootPart")
    if not targetRoot or (root.Position - targetRoot.Position).Magnitude >= 70 then
        return false, "Target is outside ClickM1 range"
    end

    weaponCategory = weaponCategory or "Melee"
    local tool = character:FindFirstChildOfClass("Tool")
    if requiredTool and (not requiredTool:IsA("Tool") or tool ~= requiredTool) then
        return false, "Selected mastery weapon is no longer equipped"
    end
    if not tool or tool.ToolTip ~= weaponCategory then
        return false, "Selected weapon category is not equipped"
    end

    if weaponCategory == "Blox Fruit" then
        local fruitCallOk, fruitIssued, fruitResult = pcall(
            self._AttackFruitM1,
            self,
            target,
            character,
            root,
            tool
        )
        if not fruitCallOk then
            return false, "Fruit M1 request failed: " .. tostring(fruitIssued)
        end
        if fruitIssued then
            return true, fruitResult
        end
        return false, fruitResult
    end

    local stun = character:FindFirstChild("Stun")
    if not stun or stun.Value ~= 0 then
        return false, "Character is stunned or has no Stun state"
    end

    local combatUtil = self.Dependencies.CombatUtil
    local weaponName = combatUtil:GetWeaponName(tool)
    local weaponData = combatUtil:GetWeaponData(weaponName)
    if not weaponData then
        return false, "CombatUtil weapon data is unavailable"
    end

    local weaponType = weaponData.WeaponType
    if not combatUtil:CanAttack(character, weaponType) then
        return false, "CombatUtil rejected attack timing"
    end

    local candidates = self:_GetAttackCandidates(character, root, tonumber(range) or 30)
    if #candidates == 0 then
        return false, "No valid hit parts in BNN attack range"
    end

    local hitPart = table.remove(candidates, 1)[2]
    if attackNoAnimation == true then
        self.Dependencies.RegisterAttack:FireServer(0)
        self.Dependencies.RegisterHit:FireServer(hitPart, candidates)
        return true, "M1 request issued without animation"
    end

    local animationCache = combatUtil:GetMovesetAnimCache(humanoid)
    if not animationCache or not weaponData.Moveset or not weaponData.Moveset.Basic then
        return false, "CombatUtil moveset data is unavailable"
    end
    local basics = weaponData.Moveset.Basic
    if #basics == 0 then
        return false, "Weapon has no basic attack animations"
    end
    self.AttackIndex = self.AttackIndex % #basics + 1

    local pureWeaponName = combatUtil:GetPureWeaponName(weaponName)
    local animation = animationCache[pureWeaponName .. "-basic" .. self.AttackIndex]
    if not animation then
        return false, "Basic attack animation is not cached"
    end

    local speedMultiplier = animation:GetAttribute("SpeedMult") or 1
    if speedMultiplier <= 0 then
        speedMultiplier = 1
    end
    local duration = animation.Length / speedMultiplier

    self.Dependencies.RegisterAttack:FireServer(duration)
    self.Dependencies.RegisterHit:FireServer(hitPart, candidates)
    animation:Play(0.1, 1, speedMultiplier)

    return true, "M1 request issued"
end

function CombatService:Cancel()
    if self.ActiveInputRelease then
        pcall(self.ActiveInputRelease)
    elseif self.ActiveInputService and self.ActiveSkillKey then
        pcall(function()
            self.ActiveInputService:SendKeyEvent(false, self.ActiveSkillKey, false, game)
        end)
    end
    self.ActiveInputRelease = nil
    self.ActiveInputService = nil
    self.ActiveSkillKey = nil
    self:ClearFarmSkillAimTarget()
    return true
end

return CombatService
-- END SOURCE: src/ReplicatedStorage/CustomHub/Features/Farm/CombatService.lua
end

__bundleFactories["CustomHub.Features.Farm.StackTaskQueue"] = function()
-- BEGIN SOURCE: src/ReplicatedStorage/CustomHub/Features/Farm/StackTaskQueue.lua
local StackTaskQueue = {}
StackTaskQueue.__index = StackTaskQueue

local TASK_KIND = {
    CakePrince = true,
    EliteHunter = true,
    RipIndra = true,
    SoulReaper = true,
    DoughKing = true,
    Darkbeard = true,
    Fruit = true,
    Berry = true,
    HopEliteHunter = true,
    HopBerry = true,
}

local SPAWNED_BOSS_KINDS = {
    ["rip_indra True Form"] = "RipIndra",
    ["Soul Reaper"] = "SoulReaper",
    ["Dough King"] = "DoughKing",
    ["Darkbeard"] = "Darkbeard",
}

local ELITE_HUNTER_NAMES = {
    Deandre = true,
    Urban = true,
    Diablo = true,
}

local function isAliveEliteHunter(instance)
    if not instance or not instance:IsA("Model") or not ELITE_HUNTER_NAMES[instance.Name] then
        return false
    end
    local root = instance:FindFirstChild("HumanoidRootPart")
    local humanoid = instance:FindFirstChildWhichIsA("Humanoid")
    return root ~= nil and humanoid ~= nil and humanoid.Health > 0
end

local function isSpawnedStackBoss(instance)
    return instance ~= nil
        and instance:IsA("Model")
        and SPAWNED_BOSS_KINDS[instance.Name] ~= nil
end

local function isSpawnedBossKind(kind)
    return kind == "RipIndra"
        or kind == "SoulReaper"
        or kind == "DoughKing"
        or kind == "Darkbeard"
end

local function isFruitCandidate(instance)
    return instance ~= nil
        and (instance:IsA("Tool") or instance:IsA("Model"))
        and string.find(string.lower(instance.Name), "fruit", 1, true) ~= nil
end

local function findFruitHandle(instance)
    local handle = instance and instance:FindFirstChild("Handle")
    if handle and handle:IsA("BasePart") then
        return handle
    end
    return instance and instance:FindFirstChildWhichIsA("BasePart", true) or nil
end

local function isCakePrinceCandidate(instance)
    return instance ~= nil
        and instance:IsA("Model")
        and instance.Name == "Cake Prince"
end

local function hasBerrySpawnData(bush)
    if not bush then
        return false
    end
    for _, value in pairs(bush:GetAttributes()) do
        if value ~= nil and value ~= false and value ~= "" then
            return true
        end
    end
    return false
end

local function findBerryPickup(bush)
    if not bush then
        return nil, nil
    end
    for _, child in ipairs(bush:GetChildren()) do
        local prompt
        if child:IsA("ProximityPrompt") then
            prompt = child
        else
            prompt = child:FindFirstChildWhichIsA("ProximityPrompt", true)
        end
        if prompt then
            return child:IsA("ProximityPrompt") and child.Parent or child, prompt
        end
    end
    return nil, nil
end

local function instancePivot(instance)
    if not instance then
        return nil
    end
    if instance:IsA("BasePart") then
        return instance.CFrame
    elseif instance:IsA("Model") then
        return instance:GetPivot()
    end
    local cframe = instance:GetAttribute("CFrame")
    if typeof(cframe) == "CFrame" then
        return cframe
    elseif typeof(cframe) == "Vector3" then
        return CFrame.new(cframe)
    end
    return nil
end

function StackTaskQueue.new(workspaceService, collectionService, replicatedStorage)
    return setmetatable({
        Workspace = workspaceService,
        CollectionService = collectionService,
        ReplicatedStorage = replicatedStorage,
        Enabled = {
            CakePrince = false,
            EliteHunter = false,
            RipIndra = false,
            SoulReaper = false,
            DoughKing = false,
            Darkbeard = false,
            Fruit = false,
            Berry = false,
            HopEliteHunter = false,
            HopBerry = false,
        },
        Pending = {},
        PendingByInstance = setmetatable({}, { __mode = "k" }),
        ActiveByInstance = setmetatable({}, { __mode = "k" }),
        CompletedByInstance = setmetatable({}, { __mode = "k" }),
        KindByInstance = setmetatable({}, { __mode = "k" }),
        SpawnOrderByInstance = setmetatable({}, { __mode = "k" }),
        FruitWatchers = setmetatable({}, { __mode = "k" }),
        BerryWatchers = setmetatable({}, { __mode = "k" }),
        BerryActiveByBush = setmetatable({}, { __mode = "k" }),
        BerryPickupByBush = setmetatable({}, { __mode = "k" }),
        EliteByName = {},
        Sequence = 0,
        Connections = {},
        EnemiesConnection = nil,
        EnemiesFolder = nil,
    }, StackTaskQueue)
end

function StackTaskQueue:_DisconnectFruitWatcher(instance)
    local connections = self.FruitWatchers[instance]
    if not connections then
        return
    end
    self.FruitWatchers[instance] = nil
    for _, connection in ipairs(connections) do
        if connection.Connected then
            connection:Disconnect()
        end
    end
end

function StackTaskQueue:_DisconnectBerryWatcher(instance)
    local connections = self.BerryWatchers[instance]
    if not connections then
        return
    end
    self.BerryWatchers[instance] = nil
    for _, connection in ipairs(connections) do
        if connection.Connected then
            connection:Disconnect()
        end
    end
end

function StackTaskQueue:_RememberSpawn(kind, instance)
    if self.SpawnOrderByInstance[instance] == nil then
        self.Sequence += 1
        self.SpawnOrderByInstance[instance] = self.Sequence
        self.KindByInstance[instance] = kind
    end
    return self.SpawnOrderByInstance[instance]
end

function StackTaskQueue:_Queue(kind, instance)
    if not self.Enabled[kind]
        or self.PendingByInstance[instance]
        or self.ActiveByInstance[instance]
        or self.CompletedByInstance[instance]
    then
        return
    end

    local spawnSequence = self:_RememberSpawn(kind, instance)
    local entry = {
        Kind = kind,
        Instance = instance,
        Sequence = spawnSequence,
        QueueSequence = spawnSequence,
        QueuedAt = os.clock(),
        HadHandle = kind == "Fruit",
    }
    self.PendingByInstance[instance] = entry
    table.insert(self.Pending, entry)
end

function StackTaskQueue:_ObserveFruit(instance)
    if not isFruitCandidate(instance) then
        return
    end
    self:_RememberSpawn("Fruit", instance)
    if not self.Enabled.Fruit or instance.Parent ~= self.Workspace then
        return
    end

    if findFruitHandle(instance) then
        self:_DisconnectFruitWatcher(instance)
        self:_Queue("Fruit", instance)
        return
    end
    if self.FruitWatchers[instance] then
        return
    end

    local connections = {}
    self.FruitWatchers[instance] = connections
    local function checkReady()
        if not self.Workspace or instance.Parent ~= self.Workspace then
            self:_DisconnectFruitWatcher(instance)
            return
        end
        if findFruitHandle(instance) then
            self:_DisconnectFruitWatcher(instance)
            self:_Queue("Fruit", instance)
        end
    end
    table.insert(connections, instance.DescendantAdded:Connect(checkReady))
    table.insert(connections, instance.AncestryChanged:Connect(function(_, parent)
        if parent ~= self.Workspace then
            self:_DisconnectFruitWatcher(instance)
        end
    end))
    checkReady()
end

function StackTaskQueue:_ObserveCakePrince(instance)
    if not isCakePrinceCandidate(instance) then
        return
    end
    self:_RememberSpawn("CakePrince", instance)
    self:_Queue("CakePrince", instance)
end

function StackTaskQueue:_ObserveEliteHunter(instance)
    if not isAliveEliteHunter(instance) then
        return
    end

    self:_RememberSpawn("EliteHunter", instance)
    if not self.Enabled.EliteHunter then
        return
    end

    local existing = self.EliteByName[instance.Name]
    if existing then
        local existingInstance = existing.Instance
        if existingInstance == instance then
            return
        end

        local oldIsAlive = isAliveEliteHunter(existingInstance)
        if not oldIsAlive then
            self:_RemovePendingInstance("EliteHunter", existingInstance)
            self.ActiveByInstance[existingInstance] = nil
            self.EliteByName[instance.Name] = nil
            existing = nil
        end
    end

    if existing then
        local existingInstance = existing.Instance
        local wasActive = existingInstance and self.ActiveByInstance[existingInstance] == true
        local oldIsInWorkspace = existingInstance
            and existingInstance:IsDescendantOf(self.Workspace)
        local newIsInWorkspace = instance:IsDescendantOf(self.Workspace)
        if newIsInWorkspace and not oldIsInWorkspace then
            self.PendingByInstance[existingInstance] = nil
            self.ActiveByInstance[existingInstance] = nil
            existing.Instance = instance
            self.PendingByInstance[instance] = existing
            if wasActive then
                self.ActiveByInstance[instance] = true
            end
        end
        return
    end

    self:_Queue("EliteHunter", instance)
    local entry = self.PendingByInstance[instance]
    if entry then
        self.EliteByName[instance.Name] = entry
    end
end

function StackTaskQueue:_ObserveSpawnedBoss(instance)
    if not isSpawnedStackBoss(instance) then
        return
    end
    local kind = SPAWNED_BOSS_KINDS[instance.Name]
    self:_RememberSpawn(kind, instance)
    self:_Queue(kind, instance)
end

function StackTaskQueue:BindLiveEliteTarget(entry, target)
    if not entry
        or entry.Kind ~= "EliteHunter"
        or not isAliveEliteHunter(target)
        or not self.EnemiesFolder
        or target.Parent ~= self.EnemiesFolder
    then
        return false
    end

    local previous = entry.Instance
    if previous ~= target then
        self.PendingByInstance[previous] = nil
        self.ActiveByInstance[previous] = nil
        entry.Instance = target
        self.PendingByInstance[target] = nil
        self.ActiveByInstance[target] = true
        self.CompletedByInstance[target] = nil
        self.KindByInstance[target] = "EliteHunter"
        self.SpawnOrderByInstance[target] = entry.QueueSequence
        self.EliteByName[target.Name] = entry
    end
    return true
end

function StackTaskQueue:_ForgetBerryBush(bush)
    self:_DisconnectBerryWatcher(bush)
    self:_RemovePendingInstance("Berry", bush)
    self.BerryActiveByBush[bush] = nil
    self.BerryPickupByBush[bush] = nil
    self.PendingByInstance[bush] = nil
    self.CompletedByInstance[bush] = nil
    self.KindByInstance[bush] = nil
    self.SpawnOrderByInstance[bush] = nil
end

function StackTaskQueue:_ObserveBerry(bush)
    if not self.CollectionService
        or not bush
        or not self.CollectionService:HasTag(bush, "BerryBush")
    then
        return
    end

    local parent = bush.Parent
    if not parent then
        return
    end
    if parent:FindFirstChild("IgnoredBerry") or parent:FindFirstChild("Ignored") then
        self:_RemovePendingInstance("Berry", bush)
        self.CompletedByInstance[bush] = nil
        self.BerryActiveByBush[bush] = false
        self.KindByInstance[bush] = nil
        self.SpawnOrderByInstance[bush] = nil
        return
    end

    local berryModel = findBerryPickup(bush)
    local active = hasBerrySpawnData(bush) or berryModel ~= nil
    if not active then
        if self.BerryActiveByBush[bush] ~= false then
            self:_RemovePendingInstance("Berry", bush)
            self.CompletedByInstance[bush] = nil
            self.KindByInstance[bush] = nil
            self.SpawnOrderByInstance[bush] = nil
        end
        self.BerryActiveByBush[bush] = false
        return
    end

    if self.BerryActiveByBush[bush] == false then
        self.CompletedByInstance[bush] = nil
        self.KindByInstance[bush] = nil
        self.SpawnOrderByInstance[bush] = nil
    end
    self.BerryActiveByBush[bush] = true
    local previousPickup = self.BerryPickupByBush[bush]
    if berryModel and berryModel ~= previousPickup then
        self.BerryPickupByBush[bush] = berryModel
        self.CompletedByInstance[bush] = nil
    elseif previousPickup and not previousPickup:IsDescendantOf(bush) then
        self.BerryPickupByBush[bush] = nil
    end
    if not self.Enabled.Berry then
        return
    end

    self:_RememberSpawn("Berry", bush)
    if not self.BerryWatchers[bush] then
        local connections = {}
        self.BerryWatchers[bush] = connections
        table.insert(connections, bush.AttributeChanged:Connect(function()
            self:_ObserveBerry(bush)
        end))
        table.insert(connections, bush.DescendantAdded:Connect(function()
            self:_ObserveBerry(bush)
        end))
        table.insert(connections, bush.DescendantRemoving:Connect(function()
            task.defer(function()
                if self.BerryWatchers[bush] then
                    self:_ObserveBerry(bush)
                end
            end)
        end))
        table.insert(connections, bush.AncestryChanged:Connect(function(_, newParent)
            if not newParent then
                self:_ForgetBerryBush(bush)
            end
        end))
    end
    self:_Queue("Berry", bush)
end

function StackTaskQueue:_RemovePendingInstance(kind, instance)
    for index = #self.Pending, 1, -1 do
        local entry = self.Pending[index]
        if entry.Kind == kind and entry.Instance == instance then
            self.PendingByInstance[instance] = nil
            table.remove(self.Pending, index)
        end
    end
end

function StackTaskQueue:IsBerryBush(bush)
    return self.CollectionService ~= nil
        and bush ~= nil
        and self.CollectionService:HasTag(bush, "BerryBush")
end

function StackTaskQueue:IsBerryActive(bush)
    if not self:IsBerryBush(bush) then
        return false
    end
    local parent = bush.Parent
    if not parent or parent:FindFirstChild("IgnoredBerry") or parent:FindFirstChild("Ignored") then
        return false
    end
    local model = findBerryPickup(bush)
    return hasBerrySpawnData(bush) or model ~= nil
end

function StackTaskQueue:GetBerryPickup(bush)
    local model, prompt = findBerryPickup(bush)
    local destination = instancePivot(model)
    if not destination then
        destination = instancePivot(bush and bush.Parent)
    end
    if not destination then
        destination = instancePivot(bush)
    end
    return model, prompt, destination
end

function StackTaskQueue:_WatchEnemies(folder)
    if not folder or folder == self.EnemiesFolder then
        return
    end
    if self.EnemiesConnection then
        self.EnemiesConnection:Disconnect()
        self.EnemiesConnection = nil
    end
    self.EnemiesFolder = folder
    self.EnemiesConnection = folder.ChildAdded:Connect(function(instance)
        self:_ObserveCakePrince(instance)
        self:_ObserveEliteHunter(instance)
        self:_ObserveSpawnedBoss(instance)
    end)
    for _, instance in ipairs(folder:GetChildren()) do
        self:_ObserveCakePrince(instance)
        self:_ObserveEliteHunter(instance)
        self:_ObserveSpawnedBoss(instance)
    end
end

function StackTaskQueue:Initialize()
    local workspaceService = self.Workspace
    if not workspaceService then
        return false, "Workspace is unavailable"
    end

    table.insert(self.Connections, workspaceService.ChildAdded:Connect(function(instance)
        if instance.Name == "Enemies" then
            self:_WatchEnemies(instance)
        end
        self:_ObserveFruit(instance)
    end))

    local replicatedStorage = self.ReplicatedStorage
    if replicatedStorage then
        table.insert(
            self.Connections,
            replicatedStorage.ChildAdded:Connect(function(instance)
                self:_ObserveEliteHunter(instance)
            end)
        )
    end

    self:_WatchEnemies(workspaceService:FindFirstChild("Enemies"))
    for _, instance in ipairs(workspaceService:GetChildren()) do
        self:_ObserveFruit(instance)
    end
    if replicatedStorage then
        for _, instance in ipairs(replicatedStorage:GetChildren()) do
            self:_ObserveEliteHunter(instance)
        end
    end

    local collectionService = self.CollectionService
    if collectionService then
        table.insert(
            self.Connections,
            collectionService:GetInstanceAddedSignal("BerryBush"):Connect(function(bush)
                self:_ObserveBerry(bush)
            end)
        )
        table.insert(
            self.Connections,
            collectionService:GetInstanceRemovedSignal("BerryBush"):Connect(function(bush)
                self:_ForgetBerryBush(bush)
            end)
        )
    end
    return true
end

function StackTaskQueue:_QueueExisting(kind)
    local workspaceService = self.Workspace
    if not workspaceService then
        return
    end

    if kind == "Fruit" then
        for _, instance in ipairs(workspaceService:GetChildren()) do
            self:_ObserveFruit(instance)
        end
    elseif kind == "CakePrince" then
        local enemies = workspaceService:FindFirstChild("Enemies")
        if enemies then
            self:_WatchEnemies(enemies)
            for _, instance in ipairs(enemies:GetChildren()) do
                self:_ObserveCakePrince(instance)
            end
        end
    elseif kind == "EliteHunter" then
        local replicatedStorage = self.ReplicatedStorage
        if replicatedStorage then
            for _, instance in ipairs(replicatedStorage:GetChildren()) do
                self:_ObserveEliteHunter(instance)
            end
        end
        local enemies = workspaceService:FindFirstChild("Enemies")
        if enemies then
            self:_WatchEnemies(enemies)
            for _, instance in ipairs(enemies:GetChildren()) do
                self:_ObserveEliteHunter(instance)
            end
        end
    elseif isSpawnedBossKind(kind) then
        local enemies = self.Workspace:FindFirstChild("Enemies")
        if enemies then
            self:_WatchEnemies(enemies)
            for _, instance in ipairs(enemies:GetChildren()) do
                self:_ObserveSpawnedBoss(instance)
            end
        end
    elseif kind == "Berry" then
        local collectionService = self.CollectionService
        if collectionService then
            for _, bush in ipairs(collectionService:GetTagged("BerryBush")) do
                self:_ObserveBerry(bush)
            end
        end
    end
end

function StackTaskQueue:_RemovePending(kind)
    for index = #self.Pending, 1, -1 do
        local entry = self.Pending[index]
        if entry.Kind == kind then
            self.PendingByInstance[entry.Instance] = nil
            table.remove(self.Pending, index)
        end
    end
end

function StackTaskQueue:SetEnabled(kind, enabled)
    if not TASK_KIND[kind] then
        return false, "Unsupported stack task"
    end

    enabled = enabled == true
    if enabled and kind == "Berry" and not self.CollectionService then
        return false, "Berry detection is unavailable"
    end
    if self.Enabled[kind] == enabled then
        return true
    end
    self.Enabled[kind] = enabled

    if enabled then
        if kind ~= "HopEliteHunter" and kind ~= "HopBerry" then
            self:_QueueExisting(kind)
        end
    else
        self:_RemovePending(kind)
        if kind == "Fruit" then
            for instance in pairs(self.FruitWatchers) do
                self:_DisconnectFruitWatcher(instance)
            end
        elseif kind == "Berry" then
            for bush in pairs(self.BerryWatchers) do
                self:_DisconnectBerryWatcher(bush)
            end
        end
        for instance, observedKind in pairs(self.KindByInstance) do
            if observedKind == kind then
                self.CompletedByInstance[instance] = nil
            end
        end
        if kind == "EliteHunter" then
            table.clear(self.EliteByName)
        end
    end
    return true
end

function StackTaskQueue:IsEnabled(entry)
    return entry ~= nil and self.Enabled[entry.Kind] == true
end

local function optimizeFruitRun(entries, currentPosition, estimateTravelCost)
    local count = #entries
    if count < 2 or typeof(currentPosition) ~= "Vector3" then
        return entries
    end

    local positions = {}
    for index, entry in ipairs(entries) do
        local handle = findFruitHandle(entry.Instance)
        if not handle then
            return entries
        end
        positions[index] = handle.Position
    end

    local costs = {}
    local function getCost(fromIndex, toIndex)
        costs[fromIndex] = costs[fromIndex] or {}
        local cached = costs[fromIndex][toIndex]
        if cached then
            return cached
        end

        local fromPosition = fromIndex == 0 and currentPosition or positions[fromIndex]
        local toPosition = positions[toIndex]
        local cost
        if type(estimateTravelCost) == "function" then
            local ok, result = pcall(estimateTravelCost, fromPosition, toPosition)
            if ok and type(result) == "number" and result == result and result < math.huge then
                cost = result
            end
        end
        if not cost then
            cost = (toPosition - fromPosition).Magnitude
        end
        costs[fromIndex][toIndex] = cost
        return cost
    end

    local order = {}
    if count <= 10 then
        -- Exact shortest visiting order for the small fruit batches normally seen in a server.
        local fullMask = 2 ^ count - 1
        local memo = {}
        local function solve(mask, lastIndex)
            if mask == fullMask then
                return 0
            end
            local memoKey = mask * (count + 1) + lastIndex
            local cached = memo[memoKey]
            if cached then
                return cached.Cost
            end

            local bestCost = math.huge
            local bestNext
            for nextIndex = 1, count do
                local bit = 2 ^ (nextIndex - 1)
                if math.floor(mask / bit) % 2 == 0 then
                    local nextMask = mask + bit
                    local total = getCost(lastIndex, nextIndex)
                        + solve(nextMask, nextIndex)
                    if total < bestCost then
                        bestCost = total
                        bestNext = nextIndex
                    end
                end
            end
            memo[memoKey] = { Cost = bestCost, Next = bestNext }
            return bestCost
        end

        solve(0, 0)
        local mask = 0
        local lastIndex = 0
        while mask ~= fullMask do
            local choice = memo[mask * (count + 1) + lastIndex]
            local nextIndex = choice and choice.Next
            if not nextIndex then
                return entries
            end
            table.insert(order, nextIndex)
            mask += 2 ^ (nextIndex - 1)
            lastIndex = nextIndex
        end
    else
        -- Keep unusually large batches responsive; use gateway-aware nearest-next selection.
        local remaining = {}
        for index = 1, count do
            remaining[index] = true
        end
        local lastIndex = 0
        for _ = 1, count do
            local bestIndex
            local bestCost = math.huge
            for index = 1, count do
                if remaining[index] then
                    local cost = getCost(lastIndex, index)
                    if cost < bestCost then
                        bestCost = cost
                        bestIndex = index
                    end
                end
            end
            if not bestIndex then
                return entries
            end
            table.insert(order, bestIndex)
            remaining[bestIndex] = nil
            lastIndex = bestIndex
        end
    end

    local ordered = {}
    for _, index in ipairs(order) do
        ordered[#ordered + 1] = entries[index]
    end
    return ordered
end

function StackTaskQueue:HasEnabledTasks()
    return self.Enabled.CakePrince == true
        or self.Enabled.EliteHunter == true
        or self.Enabled.RipIndra == true
        or self.Enabled.SoulReaper == true
        or self.Enabled.DoughKing == true
        or self.Enabled.Darkbeard == true
        or self.Enabled.Fruit == true
        or self.Enabled.Berry == true
        or self.Enabled.HopEliteHunter == true
        or self.Enabled.HopBerry == true
end

function StackTaskQueue:TakePendingKind(kind)
    for index, entry in ipairs(self.Pending) do
        if entry.Kind == kind then
            local instance = entry.Instance
            local isPresent = instance
                and instance.Parent == self.EnemiesFolder
                and isSpawnedStackBoss(instance)
            table.remove(self.Pending, index)
            self.PendingByInstance[instance] = nil
            if self:IsEnabled(entry) and isPresent then
                self.ActiveByInstance[instance] = true
                return entry
            end
            self.CompletedByInstance[instance] = true
            return nil, "The boss was defeated before it could be reached"
        end
    end
    return nil
end

function StackTaskQueue:PopNext(currentPosition, estimateTravelCost)
    table.sort(self.Pending, function(left, right)
        return left.QueueSequence < right.QueueSequence
    end)

    local validPending = {}
    for _, entry in ipairs(self.Pending) do
        local instance = entry.Instance
        local isPresent = instance
            and (
                entry.Kind == "Fruit"
                    and instance.Parent == self.Workspace
                    or entry.Kind == "EliteHunter"
                    and instance.Parent ~= nil
                    and isAliveEliteHunter(instance)
                    or isSpawnedBossKind(entry.Kind)
                    and instance.Parent == self.EnemiesFolder
                    and isSpawnedStackBoss(instance)
                    or entry.Kind ~= "Fruit"
                    and entry.Kind ~= "EliteHunter"
                    and not isSpawnedBossKind(entry.Kind)
                    and instance.Parent ~= nil
            )
        if self:IsEnabled(entry) and isPresent and not self.CompletedByInstance[instance] then
            validPending[#validPending + 1] = entry
        else
            self.PendingByInstance[instance] = nil
        end
    end
    self.Pending = validPending

    if self.Pending[1] and self.Pending[1].Kind == "Fruit" then
        local fruitRun = {}
        local index = 1
        while self.Pending[index] and self.Pending[index].Kind == "Fruit" do
            fruitRun[#fruitRun + 1] = self.Pending[index]
            index += 1
        end
        if #fruitRun > 1 then
            local ordered = optimizeFruitRun(fruitRun, currentPosition, estimateTravelCost)
            local queueSlots = {}
            for fruitIndex, entry in ipairs(fruitRun) do
                queueSlots[fruitIndex] = entry.QueueSequence
            end
            for fruitIndex, entry in ipairs(ordered) do
                entry.QueueSequence = queueSlots[fruitIndex]
                self.Pending[fruitIndex] = entry
            end
        end
    end

    while #self.Pending > 0 do
        local entry = table.remove(self.Pending, 1)
        self.PendingByInstance[entry.Instance] = nil
        if self:IsEnabled(entry) and entry.Instance then
            self.ActiveByInstance[entry.Instance] = true
            return entry
        end
    end
    return nil
end

function StackTaskQueue:Complete(entry, markCompleted)
    if not entry or not entry.Instance then
        return
    end
    self.PendingByInstance[entry.Instance] = nil
    self.ActiveByInstance[entry.Instance] = nil
    if markCompleted == false then
        self.CompletedByInstance[entry.Instance] = nil
    else
        self.CompletedByInstance[entry.Instance] = true
    end
    if entry.Kind == "EliteHunter"
        and self.EliteByName[entry.Instance.Name] == entry
    then
        self.EliteByName[entry.Instance.Name] = nil
    end
end

function StackTaskQueue:Cleanup()
    if self.EnemiesConnection then
        self.EnemiesConnection:Disconnect()
        self.EnemiesConnection = nil
    end
    for _, connection in ipairs(self.Connections) do
        connection:Disconnect()
    end
    for instance in pairs(self.FruitWatchers) do
        self:_DisconnectFruitWatcher(instance)
    end
    for bush in pairs(self.BerryWatchers) do
        self:_DisconnectBerryWatcher(bush)
    end
    table.clear(self.Connections)
    table.clear(self.Pending)
    self.PendingByInstance = setmetatable({}, { __mode = "k" })
    self.ActiveByInstance = setmetatable({}, { __mode = "k" })
    self.CompletedByInstance = setmetatable({}, { __mode = "k" })
    self.KindByInstance = setmetatable({}, { __mode = "k" })
    self.SpawnOrderByInstance = setmetatable({}, { __mode = "k" })
    self.FruitWatchers = setmetatable({}, { __mode = "k" })
    self.BerryWatchers = setmetatable({}, { __mode = "k" })
    self.BerryActiveByBush = setmetatable({}, { __mode = "k" })
    self.BerryPickupByBush = setmetatable({}, { __mode = "k" })
    table.clear(self.EliteByName)
    self.EnemiesFolder = nil
    self.CollectionService = nil
    self.Workspace = nil
    self.ReplicatedStorage = nil
end

return StackTaskQueue
-- END SOURCE: src/ReplicatedStorage/CustomHub/Features/Farm/StackTaskQueue.lua
end

__bundleFactories["CustomHub.Features.ServerHopService"] = function()
-- BEGIN SOURCE: src/ReplicatedStorage/CustomHub/Features/ServerHopService.lua
local ServerHopService = {}
ServerHopService.__index = ServerHopService

local INITIAL_SCAN_DELAY = 6
local ARRIVAL_SCAN_DELAY = 8
local RETRY_DELAY = 3
local PAGE_DELAY = 0.5
local TELEPORT_TIMEOUT = 25
local SESSION_LIFETIME = 3600
local MAX_VISITED_SERVERS = 300
local MAX_PERSISTED_VISITED_SERVERS = 40

local function shortError(value)
    local message = tostring(value or "unknown error"):gsub("[%c]", " ")
    if #message > 180 then
        message = message:sub(1, 177) .. "..."
    end
    return message
end

local function validJobId(value)
    return type(value) == "string"
        and #value > 0
        and #value <= 128
        and not value:find("[%c]")
end

function ServerHopService.new(compatibility, settingsPersistence, setStatus, coordinator)
    return setmetatable({
        Compatibility = compatibility,
        SettingsPersistence = settingsPersistence,
        SetStatus = setStatus,
        Coordinator = coordinator,
        CoordinatorLease = nil,
        Settings = nil,
        Session = nil,
        ResumePending = false,
        Fetching = false,
        InFlight = false,
        PendingJobId = nil,
        PendingDeadline = 0,
        NextAttemptAt = 0,
        PageCount = 0,
        Generation = 0,
        Destroyed = false,
        TeleportFailureConnection = nil,
        LastErrorStatus = nil,
    }, ServerHopService)
end

function ServerHopService:_SetStatus(message, kind)
    if type(self.SetStatus) == "function" then
        pcall(self.SetStatus, message, kind or "info")
    end
end

function ServerHopService:_ReleaseCoordinatorLease()
    if self.Coordinator and self.CoordinatorLease then
        self.Coordinator:Release(self.CoordinatorLease)
    end
    self.CoordinatorLease = nil
end

function ServerHopService:OwnsLease(lease)
    return lease ~= nil and self.CoordinatorLease == lease
end

function ServerHopService:_ReadModes()
    local settings = self.Settings or {}
    return {
        EliteHunter = settings.HopForEliteHunter == true,
        Berry = settings.HopForBerries == true,
    }
end

function ServerHopService:_HasEnabledMode()
    local modes = self:_ReadModes()
    return modes.EliteHunter or modes.Berry
end

function ServerHopService:_ModeLabel()
    local modes = self:_ReadModes()
    if modes.EliteHunter and modes.Berry then
        return "Elite Hunters and berries"
    elseif modes.EliteHunter then
        return "Elite Hunters"
    elseif modes.Berry then
        return "berries"
    end
    return "targets"
end

function ServerHopService:_IsThirdSea()
    local compatibility = self.Compatibility
    if not compatibility or type(compatibility.IsThirdSea) ~= "function" then
        return false
    end
    local ok, result = pcall(compatibility.IsThirdSea, compatibility)
    return ok and result == true
end

function ServerHopService:_CopySession(session)
    if type(session) ~= "table" then
        return nil
    end
    local copy = {
        PlaceId = session.PlaceId,
        ExpiresAt = session.ExpiresAt,
        Modes = {
            EliteHunter = session.Modes and session.Modes.EliteHunter == true,
            Berry = session.Modes and session.Modes.Berry == true,
        },
        Visited = {},
        Cursor = session.Cursor,
        PendingJobId = session.PendingJobId,
    }
    for _, jobId in ipairs(session.Visited or {}) do
        if validJobId(jobId) then
            copy.Visited[#copy.Visited + 1] = jobId
            if #copy.Visited >= MAX_VISITED_SERVERS then
                break
            end
        end
    end
    return copy
end

function ServerHopService:_SaveSession()
    local persistence = self.SettingsPersistence
    if not persistence or type(persistence.SetHopSession) ~= "function" then
        return false, "Settings storage is unavailable"
    end
    local copy = self:_CopySession(self.Session)
    if not copy then
        return false, "Hop session is unavailable"
    end
    if #copy.Visited > MAX_PERSISTED_VISITED_SERVERS then
        local recent = {}
        for index = #copy.Visited - MAX_PERSISTED_VISITED_SERVERS + 1, #copy.Visited do
            recent[#recent + 1] = copy.Visited[index]
        end
        copy.Visited = recent
    end
    copy.ExpiresAt = os.time() + SESSION_LIFETIME
    self.Session.ExpiresAt = copy.ExpiresAt
    local ok, saved, saveError = pcall(
        persistence.SetHopSession,
        persistence,
        copy
    )
    if not ok then
        return false, "Settings storage could not save the search session"
    end
    return saved, saveError
end

function ServerHopService:_ClearSavedSession()
    local persistence = self.SettingsPersistence
    if persistence and type(persistence.ClearHopSession) == "function" then
        pcall(persistence.ClearHopSession, persistence)
    end
    self.Session = nil
    self.PendingJobId = nil
    self.PendingDeadline = 0
    self.InFlight = false
    self:_ReleaseCoordinatorLease()
end

function ServerHopService:_EnsureSession()
    if self.Session then
        self.Session.Modes = self:_ReadModes()
        return self.Session
    end

    local modes = self:_ReadModes()
    if not modes.EliteHunter and not modes.Berry then
        return nil
    end

    local currentJobId = tostring(game.JobId or "")
    self.Session = {
        PlaceId = tonumber(game.PlaceId),
        ExpiresAt = os.time() + SESSION_LIFETIME,
        Modes = modes,
        Visited = {},
        Cursor = nil,
    }
    if validJobId(currentJobId) then
        self.Session.Visited[1] = currentJobId
    end
    return self.Session
end

function ServerHopService:_MarkVisited(jobId)
    if not self.Session or not validJobId(jobId) then
        return
    end
    for _, existing in ipairs(self.Session.Visited) do
        if existing == jobId then
            return
        end
    end
    table.insert(self.Session.Visited, jobId)
    while #self.Session.Visited > MAX_VISITED_SERVERS do
        table.remove(self.Session.Visited, 1)
    end
end

function ServerHopService:_IsVisited(jobId)
    for _, existing in ipairs((self.Session and self.Session.Visited) or {}) do
        if existing == jobId then
            return true
        end
    end
    return false
end

function ServerHopService:_SetModesOnSavedSession()
    if not self.Session then
        return
    end
    self.Session.Modes = self:_ReadModes()
    if not self.Session.Modes.EliteHunter and not self.Session.Modes.Berry then
        self:_ClearSavedSession()
        return
    end
    if self.Session.PendingJobId then
        local saved = self:_SaveSession()
        if not saved then
            self:_SetStatus(
                "Server search couldn't save its next hop; it will try again.",
                "warning"
            )
        end
    end
end

function ServerHopService:_FailPending(message)
    if not self.PendingJobId then
        return
    end
    self:_MarkVisited(self.PendingJobId)
    self.PendingJobId = nil
    self.PendingDeadline = 0
    self.InFlight = false
    if self.Session then
        self.Session.PendingJobId = nil
        self.Session.Modes = self:_ReadModes()
        self:_SaveSession()
    end
    self.NextAttemptAt = os.clock() + RETRY_DELAY
    self:_SetStatus(message or "That server could not be joined; trying another.", "warning")
    self:_ReleaseCoordinatorLease()
end

function ServerHopService:_OnTeleportInitFailed(player, teleportResult, errorMessage)
    if player ~= self.Compatibility.Player or not self.PendingJobId then
        return
    end
    local reason = errorMessage or teleportResult or "Roblox rejected the join"
    self:_FailPending(
        "Roblox rejected the server join (" .. shortError(reason) .. "); trying another."
    )
end

function ServerHopService:Initialize(settings)
    self.Settings = settings or {}
    self.Destroyed = false

    local teleportService
    pcall(function()
        teleportService = game:GetService("TeleportService")
    end)
    if teleportService and teleportService.TeleportInitFailed then
        local connectOk, connection = pcall(function()
            return teleportService.TeleportInitFailed:Connect(function(...)
                self:_OnTeleportInitFailed(...)
            end)
        end)
        if connectOk then
            self.TeleportFailureConnection = connection
        end
    end

    local persistence = self.SettingsPersistence
    local savedSession
    if persistence and type(persistence.GetHopSession) == "function" then
        local readOk, session = pcall(persistence.GetHopSession, persistence)
        if readOk then
            savedSession = session
        end
    end
    local currentJobId = tostring(game.JobId or "")
    local modes = self:_ReadModes()
    local shouldResume = savedSession ~= nil
        and tonumber(savedSession.PlaceId) == tonumber(game.PlaceId)
        and savedSession.PendingJobId == currentJobId
        and savedSession.ExpiresAt > os.time()
        and self:_IsThirdSea()
        and (modes.EliteHunter or modes.Berry)

    if shouldResume then
        self.Session = self:_CopySession(savedSession)
        self.Session.PendingJobId = nil
        self.ResumePending = true
        self.NextAttemptAt = os.clock() + ARRIVAL_SCAN_DELAY
        self:_MarkVisited(currentJobId)
        return true
    end

    if savedSession then
        self:_ClearSavedSession()
    end
    return true
end

function ServerHopService:ShouldResume()
    return self.ResumePending == true
end

function ServerHopService:ConsumeResume()
    if not self.ResumePending then
        return false
    end
    self.ResumePending = false
    if self.Session then
        self.Session.PendingJobId = nil
        self.Session.Modes = self:_ReadModes()
        self:_SaveSession()
    end
    self.NextAttemptAt = os.clock() + ARRIVAL_SCAN_DELAY
    self:_SetStatus("Checking this server for " .. self:_ModeLabel(), "info")
    return true
end

function ServerHopService:CancelResume()
    if not self.ResumePending then
        return false
    end
    self.ResumePending = false
    self:_ClearSavedSession()
    return true
end

function ServerHopService:SetEnabled(mode, enabled)
    if mode ~= "EliteHunter" and mode ~= "Berry" then
        return false, "Unsupported server search mode"
    end
    if type(enabled) ~= "boolean" then
        return false, "Server search setting is invalid"
    end
    if enabled then
        if not self:_IsThirdSea() then
            return false, "Elite Hunter and berry hopping is only available in Third Sea"
        end
        local persistence = self.SettingsPersistence
        if not persistence
            or type(persistence.CanPersistHopSession) ~= "function"
            or not persistence:CanPersistHopSession()
        then
            return false, "Server hopping needs local settings storage to resume after joining"
        end
    end

    self.NextAttemptAt = enabled
        and math.max(self.NextAttemptAt or 0, os.clock() + INITIAL_SCAN_DELAY)
        or self.NextAttemptAt
    self.Generation += 1
    self:_SetModesOnSavedSession()
    if not self:_HasEnabledMode() then
        self:_ClearSavedSession()
    elseif enabled then
        self:_SetStatus("Checking this server before searching for another", "info")
    end
    return true
end

function ServerHopService:HasEnabledModes()
    return self:_HasEnabledMode()
end

function ServerHopService:OnStackTaskStarted(kind)
    if (kind == "EliteHunter" and self:_ReadModes().EliteHunter)
        or (kind == "Berry" and self:_ReadModes().Berry)
    then
        self.NextAttemptAt = os.clock() + 2
    end
end

function ServerHopService:_BeginFetch()
    if self.Fetching or self.Destroyed then
        return
    end
    local session = self:_EnsureSession()
    if not session then
        return
    end
    if self.Coordinator and not self.CoordinatorLease then
        local lease = self.Coordinator:TryAcquire(
            "StackFarming",
            "Checking public servers",
            "StackFarm"
        )
        if not lease then
            return
        end
        self.CoordinatorLease = lease
    end
    self.Fetching = true
    local cursor = session.Cursor
    local generation = self.Generation
    self:_SetStatus("Checking public servers for " .. self:_ModeLabel(), "info")
    task.spawn(function()
        local callOk, result, fetchError = pcall(function()
            return self.Compatibility:GetPublicServers(cursor)
        end)
        if not callOk then
            fetchError = result
            result = nil
        end
        if self.Destroyed then
            self.Fetching = false
            self:_ReleaseCoordinatorLease()
            return
        end
        self.Fetching = false
        if generation ~= self.Generation then
            self:_ReleaseCoordinatorLease()
            return
        end
        if not self:_HasEnabledMode() then
            self:_ReleaseCoordinatorLease()
            return
        end
        if not result then
            if not self.LastErrorStatus then
                self.LastErrorStatus = true
                self:_SetStatus(
                    "Can't check public servers for place "
                        .. tostring(game.PlaceId)
                        .. " ("
                        .. shortError(fetchError)
                        .. "); retrying shortly.",
                    "warning"
                )
            end
            self.NextAttemptAt = os.clock() + 12
            self:_ReleaseCoordinatorLease()
            return
        end

        self.LastErrorStatus = nil
        local candidates = {}
        for _, server in ipairs(result.Servers or {}) do
            local jobId = type(server) == "table" and server.id
            local playing = type(server) == "table" and tonumber(server.playing)
            local maxPlayers = type(server) == "table" and tonumber(server.maxPlayers)
            if validJobId(jobId)
                and jobId ~= tostring(game.JobId)
                and not self:_IsVisited(jobId)
                and playing ~= nil
                and maxPlayers ~= nil
                and playing < maxPlayers
            then
                candidates[#candidates + 1] = jobId
            end
        end

        if #candidates == 0 then
            session.Cursor = result.NextCursor
            self.PageCount += 1
            if session.Cursor then
                local pause = PAGE_DELAY
                if self.PageCount >= 4 then
                    self.PageCount = 0
                    pause = 5
                    self:_SetStatus("Still checking public servers", "info")
                end
                self.NextAttemptAt = os.clock() + pause
                self:_ReleaseCoordinatorLease()
                return
            end

            session.Visited = {}
            self:_MarkVisited(tostring(game.JobId or ""))
            self.PageCount = 0
            self.NextAttemptAt = os.clock() + 8
            self:_SetStatus("No new public servers found; checking again shortly", "warning")
            self:_ReleaseCoordinatorLease()
            return
        end

        session.Cursor = result.NextCursor
        local jobId = candidates[math.random(1, #candidates)]
        self:_MarkVisited(jobId)
        session.PendingJobId = jobId
        session.Modes = self:_ReadModes()
        local saved, saveError = self:_SaveSession()
        if not saved then
            session.PendingJobId = nil
            self.NextAttemptAt = os.clock() + 12
            self:_SetStatus(
                "Server hopping can't continue because the search session couldn't be saved.",
                "error"
            )
            self:_ReleaseCoordinatorLease()
            return
        end

        self.PendingJobId = jobId
        self.PendingDeadline = os.clock() + TELEPORT_TIMEOUT
        self.InFlight = true
        self:_SetStatus("Joining another public server to check for targets", "info")
        local teleportCallOk, joined, joinError = pcall(function()
            return self.Compatibility:TeleportToPublicServer(jobId)
        end)
        if not teleportCallOk or not joined then
            if not teleportCallOk then
                joinError = joined
            end
            self:_FailPending(
                "Couldn't start the server hop ("
                    .. shortError(joinError)
                    .. "); trying another."
            )
        end
    end)
end

function ServerHopService:Step()
    if self.Destroyed or not self:_HasEnabledMode() then
        return false
    end
    if not self:_IsThirdSea() then
        self:_SetStatus("Server search is only available in Third Sea", "warning")
        self.NextAttemptAt = os.clock() + 30
        return false
    end

    if self.InFlight then
        if tostring(game.JobId or "") == self.PendingJobId then
            self.InFlight = false
            self.PendingJobId = nil
            self.PendingDeadline = 0
            self.NextAttemptAt = os.clock() + ARRIVAL_SCAN_DELAY
            self:_ReleaseCoordinatorLease()
            return false
        end
        if os.clock() >= self.PendingDeadline then
            self:_FailPending("The server join timed out; trying another server")
        else
            return true
        end
    end
    if self.Fetching or os.clock() < self.NextAttemptAt then
        return false
    end
    self:_BeginFetch()
    return false
end

function ServerHopService:Destroy()
    self.Destroyed = true
    self.Generation += 1
    self.Fetching = false
    self:_ReleaseCoordinatorLease()
    if self.TeleportFailureConnection then
        self.TeleportFailureConnection:Disconnect()
        self.TeleportFailureConnection = nil
    end
end

return ServerHopService
-- END SOURCE: src/ReplicatedStorage/CustomHub/Features/ServerHopService.lua
end

__bundleFactories["CustomHub.Features.TaskCoordinator"] = function()
-- BEGIN SOURCE: src/ReplicatedStorage/CustomHub/Features/TaskCoordinator.lua
local TaskCoordinator = {}
TaskCoordinator.__index = TaskCoordinator

local VALID_GROUPS = {
    MainFarm = true,
    Background = true,
    StackFarm = true,
    Protected = true,
}

function TaskCoordinator.new()
    return setmetatable({
        Current = nil,
        NextLeaseId = 0,
        Destroyed = false,
    }, TaskCoordinator)
end

-- Background work is normal Main Farming or user-directed Travel. Stack work
-- may pause either; task-owned Protected work may pause manual Travel only.
function TaskCoordinator:TryAcquire(owner, label, group, onPreempt)
    if self.Destroyed then
        return nil, "Task coordination has stopped"
    end
    if type(owner) ~= "string" or owner == "" then
        return nil, "Task owner is required"
    end
    if type(label) ~= "string" or label == "" then
        return nil, "Task label is required"
    end
    if not VALID_GROUPS[group] then
        return nil, "Unsupported task group"
    end

    local current = self.Current
    if current then
        if current.Owner == owner
            and current.Label == label
            and current.Group == group
        then
            return current
        end
        local canPreemptMainFarm = group == "StackFarm"
            and current.Group == "MainFarm"
        local canPreemptBackground = (
                group == "StackFarm" or group == "Protected"
            )
            and current.Group == "Background"
        if canPreemptMainFarm or canPreemptBackground then
            self.Current = nil
            if type(current.OnPreempt) == "function" then
                pcall(current.OnPreempt, group, label)
            end
        else
            return nil, current
        end
    end

    self.NextLeaseId += 1
    local lease = {
        Id = self.NextLeaseId,
        Owner = owner,
        Label = label,
        Group = group,
        OnPreempt = onPreempt,
    }
    self.Current = lease
    return lease
end

function TaskCoordinator:CanRunStack(stackLease)
    local current = self.Current
    if not current then
        return true
    end
    if current == stackLease
        or current.Group == "MainFarm"
        or current.Group == "Background"
    then
        return true
    end
    return false, current
end

function TaskCoordinator:GetCurrent()
    return self.Current
end

function TaskCoordinator:IsCurrent(lease)
    return lease ~= nil and self.Current == lease
end

function TaskCoordinator:Release(lease)
    if not lease or self.Current ~= lease then
        return false
    end
    self.Current = nil
    return true
end

function TaskCoordinator:Cleanup()
    self.Destroyed = true
    self.Current = nil
end

return TaskCoordinator
-- END SOURCE: src/ReplicatedStorage/CustomHub/Features/TaskCoordinator.lua
end

__bundleFactories["CustomHub.Features.MainFarm"] = function()
-- BEGIN SOURCE: src/ReplicatedStorage/CustomHub/Features/MainFarm.lua
local QuestService = __bundleLoad("CustomHub.Features.Farm.QuestService")
